window.READER_DATA={"title": "Yakan Mishkilat", "slug": "yakan-mishkilat", "pages": [{"n": 1, "paras": ["فتحي يكن", "مشكلات الدعوة والداعية", "مؤسسة الرسالة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0001.png"}, {"n": 2, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0002.png"}, {"n": 3, "paras": ["نحو وعي حركي إسلامي", "مشكلات الدعوة والداعية", "فتحي يكن", "مؤسسة الرسالة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0003.png"}, {"n": 4, "paras": ["جَميع الحقوق محفوظة الطبعة السادسة عشر", "١٤١٧ ه - ١٩٩٦ م", "مؤسسة الرسالة - بيروت - وطى المصيطبة - مبنى عندالله شليت تلفاكس ٨١٥١٢٠ - ٣١٩٠٣٩ - ٣٢٤٣٠٦ - ص ب ٧٤٦ - برقياً موته آر"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0004.png"}, {"n": 5, "paras": ["الإهداء", "إلى العاملين في الحقل الإسلامي أياً كانوا وأينما وجدوا ...", "إلى الذين يعيشون الإسلام وللإسلام ... أقدم هذا الكتاب", "أبو بلال"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0005.png"}, {"n": 6, "paras": ["(blank or image-only page)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0006.png"}, {"n": 7, "paras": ["مقدمة الطبعة الأولى", "في ميدان العمل الاسلامي - اليوم - مشكلات عديدة ، تتعرض لها الدعوة كما يتعرض الدعاة .. مشكلات في محيط الاسرة والمجتمع ، مع النفس والجنس ، في نطاق التنظيم والتخطيط ، في دائرة التصور والتفكير .. هذه وغيرها من المشكلات أوجدتها بل فرضتها الظروف والأوضاع والمناخات غير الاسلامية التي تعيشها الدعوة والداعية في مجتمعات منحرفة لا تمت إلى الإسلام إلا بصلة الانتساب العفوي الموروث !!", "والداعية .. مضطر للعيش في مثل هذه البيئة .. فهي ميدان عمله الوحيد .. عليه أن يتفاعل معها .. يؤثر فيها ولا يتأثر بلوثاتها.. ومهمة خطيرة ودقيقة ينبغي أن يأخذ لها الدعاة كل أسباب الوقاية والحماية والمناعة ..", "وإن من واجب ( الدعوة ) كذلك أن تكون دقيقة غاية الدقة ، واعية تمام الوعي ، مهتمة كل الاهتمام في تكوين دعاتها والمنتسبين اليها وفق مناهج محكمة تسلك لبناء ( الشخصية الإسلامية ) سبيل الواقعية .. فلا تفريط ولا إفراط .. ولا ترخص ولا تزمت .. ولا غلو ولا تساهل تحقيقاً للتوازن الفطري الصحيح بين عناصر ( الشخصية ) العقلية والنفسية والجسدية. إن التناقض المخيف بين ما يؤمن به ( الداعية ) من أفكار"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0007.png"}, {"n": 8, "paras": ["وقيم وأخلاق ومبادىء ومثل ، وبين ما هو كائن في المجتمع من مظاهر الجاهلية الحديثة. سبب رئيسي مساعد في نشوء كثير من المشكلات والأزمات في حياته .. وإن من واجب ( الدعوة ) في كل الأحوال أن تتابع بيقظة ووعي بواعث هذه المشكلات وعوارضها ، بالتشخيص أولاً ، ثم بالحلول الجذرية السليمة ، تفادياً لما قد تخلفه من عقد وانحرافات وشذوذ في حياة الشباب المسلم .. إن على (الدعوة) أن تستفيد ما وسعها الاستفادة من تجارب التطبيق العملي في حياتها ضماناً لتطوير وسلامة مناهجها.. وهذا ما يفرض دراسة كافة المشكلات التي يتعرض لها الدعاة في شق الظروف والأحوال .. وهذا الجهد المقل الذي أضعه - اليوم - بين يدي ( الدعوة والداعية) إنما هو محاولة متواضعة لاستكتاب أهل الرأي والخبرة من العاملين في الحقل الإسلامي ، تمهيداً لوضع دراسة تفصيلية شاملة تتناول كافة المشكلات التي تواجه الدعوة والداعية في المشكلات التي تواجه الدعوة والداعية في هذا العصر مشفوعة بالحلول التي ينبغي اعتمادها وتبنيها .. وإني لأرجو أن أكون قد أديت بعض الواجب ، ومعذرة إلى الله ، والله ولي الأمر والتوفيق .", "الطبعة الأولى :", "١٣٧٧ ه", "١٩٦٧ م", "المؤلف"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0008.png"}, {"n": 9, "paras": ["مقدمة الطبعة الثانية", "منذ ربع قرن والحركة الإسلامية الحديثة تعيش محناً ضارية تقدم فيها الشهيد تلو الشهيد ، وتبذل الثمن غالياً من وجودها وحياتها ، دون أن يكون لها من ذلك أدنى مردود ؟! بل الأنكى من ذلك أنها هي التي تزرع وسواها يحصد .. وانها هي التي تبني وسواها يستولي على البناء ؟! والحركة الإسلامية بالرغم من كل هذا لا يزال اسلوبها في العمل نفس الأسلوب الذي مارسته في ظل أوضاع غدت في خبر كان .. بل وغدت ممارستها له اليوم ، وفي أعقاب التحول الجذري الذي شهدته المنطقة ضرباً من الانتحار ، وجريمة لا يجوز السكوت عنها !! هذه الظواهر هي الحافز الأساسي التي دفعتني لوضع هذا الكتاب بقسميه الأول والثاني، مساهمة في تطوير التصور لطبيعة العمل الإسلامي ، وإسهاماً في الوصول بالحركة الإسلامية إلى مستوى المواجهة مع جاهلية اليوم وتحدياتها المتمادية .. ( وإن الله لهاد الذين آمنوا إلى صراط مستقيم )", "الطبعة الثانية : ١٣٩٠ ه", "١٩٧٠ م المؤلف"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0009.png"}, {"n": 10, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0010.png"}, {"n": 11, "paras": ["موضوعات الكتاب", "• الحركة الاسلامية في مدار الأربعين عاماً .", "• المحنة في حياة الدعوة والداعية .", "• المنعطفات الكبرى في حياة الدعاة .", "• الداعية بين الفهم والتطبيق", "• القيادة بين التوجيه والتنظيم", "• العلاقات التنظيمية بين الدعوة والداعية", "• حاجتنا إلى الطبيعة الحركية", "• شخصية الداعية وكيف تبنى", "• الداعية وأسلوب الدعوة", "• دعاة الاسلام وتفاوت القابليات", "• بين العقائدية والحزبية", "• الحركة الاسلامية بين التكامل والتآكل", "• مظاهر وأسباب تشوه الشخصية الاسلامية الحديثة", "• من أمراضنا التنظيمية", "• من أمراضنا النفسية", "• نحو حركة إسلامية عالمية واحدة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0011.png"}, {"n": 12, "paras": ["الحركة الإسلامية في مَدَارِ الأربعينَ عَامًا", "• في المناهج والأساليب", "• في التنظيم والتخطيط", "• في التصور والتفكير", "• في التقييم والتقدير"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0012.png"}, {"n": 13, "paras": ["إن تعرض ( الحركة الإسلامية ) في السنوات الأخيرة لسلسلة متلاحقة من المحن والظروف العصيبة القاسية يقتضي استنفار العاملين في الحقل الإسلامي في شتى ديار الإسلام ، لإعادة النظر في ( الخط التجريبي ) الذي مرت به الدعوة الإسلامية في مدار الأربعين سنة الماضية ... كما يفرض على المتصدرين للكفاح الإسلامي أن يراجعوا بكل أمانة وإخلاص مخزون الإنتاج الإسلامي ( الفكري والحركي ) خلال الفترة المنصرمة بكل ما فيه من حسنات وسيئات ..", "١ - في المناهج والأساليب : إن الأساليب التي اعتمدها الاتجاه الإسلامي طوال السنوات الماضية كانت تفتقر دائماً إلى الكشف والتطوير لتكون في مستوى القضية الإسلامية وفي مستوى الأحداث والظروف التي تحيط بها. ثم إن ملاحظة الفوارق الطبيعية المتعددة بين قطر وقطر وبيئة وأخرى مهم جداً في عملية التطوير هذه .. فما يقاس على الدعوة في بيئة لا يمكن أن يقاس عليها في كل بيئة .. وما يعتمد من مناهج وأساليب في مكان وزمان معينين لا يمكن أن يعتمد جملة وتفصيلاً في كل زمان ومكان .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0013.png"}, {"n": 14, "paras": ["٢ - في التخطيط والتنظيم : وإذا كان الاتجاه الإسلامي بحاجة إلى تطوير أساليبه ومناهجه فإنه أحوج ما يكون كذلك إلى ملاحظة قيمة التخطيط وأثره في بلوغ القضية الإسلامية والحركة الإسلامية أهدافها وغاياتها . وإذا عنينا بالتخطيط والتنظيم نظرية الحركة الإسلامية وأسلوبها في تغيير واقع إنساني قائم بآخر منشود ، بكل ما يقتضيه ذلك من فهم شامل ودقيق للواقع القائم ، وتقدير واع للقوى والاتجاهات التي تعيش فيه .. ثم من تصور عميق للواقع الإسلامي المنشود ، ومدى ما يحتاجه من كفايات وإمكانات .. فإنما نريد بذلك أن نشير إلى أن الإخفاق الذي يُمنى به الاتجاه الاسلامي ، والنكسات التي كانت تصاب بها الحركة الإسلامية ، ناجم بصورة خاصة عن التخبط في طرائق العمل وإهمال جانب التخطيط .. وإذا أردنا أن نكون صرحاء في معالجة قضايانا ، والوقوف طويلاً عند أخطائنا ، حرصاً على الاستفادة من التجارب في تحديد الحاضر والمستقبل ، فيمكننا القول بأن ( السطحية ) في تحديد الإهداف ووضع التصاميم وتقدير الأبعاد هي إحدى العلل التي ينبغي معالجتها . فإذا أمكن - افتراضاً - اعتبار السطحية ( توكلاً ) في بيئات بدائية فطرية ، فلا يمكن اعتبارها إلا ( تواكلاً ) في مجتمعات متحضرة متمدنة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0014.png"}, {"n": 15, "paras": ["وإذا كانت الحركات الحزبية حريصة على تضمين مخططاتها باستمرار عصارة دراساتها وتجاربها، فإن حرص الحركة الإسلامية ينبغي أن يكون أشد وهي دعوة الحق والهدى والنور .. وأود في سياق الكلام عن أهمية التخطيط أن أشير ولو بإيجاز إلى ( السطحية ) التي تعاني منها الحركة في نطاق التصور والتخطيط .. أمامنا الآن سؤالان تشكل الإجابة عليهما جزءاً هاماً من تصورنا وتقديرنا لطبيعة العمل الإسلامي وأهدافه وأبعاده . السؤال الأول : هل الدعوة إلى الإسلام عملية ترقيع جزئي أم هي حركة هدم وبناء ، هدم الجاهلية بكل صورها وأشكالها وبناء المجتمع الإسلامي بجميع مقوماته وخصائصه ؟ فإذا كانت الثانية فهل تقوى مناهجنا على القيام بمثل هذه المسؤولية الضخمة الجبارة..؟ السؤال الثاني : إذا كانت دعوتنا تهدف إلى استئناف حياة إسلامية صحيحة في كل آفاقها وأبعادها .. فكيف نفسر مطالبتنا غيرنا من الحكام والحكومات - أحياناً - بتحقيق رغباتنا في الحكم ونحن غير مؤمنين أصلاً بجدوى المطالبة لا من قريب ولا من بعيد ؟ ان حرص الحركة - كل حركة - أن تتولى بنفسها تنفيذ برامجها وتحقيق أهدافها منطق سليم ينبغي أن تصدر عنه الحركة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0015.png"}, {"n": 16, "paras": ["الإسلامية وتتبناه .. وليس من الإخلاص والتجرد في شيء زهدها في تحمل تبعات الحكم والتنفيذ .. وان العالم والتاريخ لا يعرفان حركة من الحركات العقائدية قدمت عصارة نضالها وكفاحها لغير المؤمنين بأهدافها ، الملتفين معها على دروب النضال والكفاح .. إن الثورة الفرنسية - مثلا - كانت أمنية من الأماني التي عمل لها ( روسو - وفولتير - ومنتسكيو .. ) والانقلاب الشيوعي كان ثمرة المخطط الذي وضعه ( ماركس ولينين ) .. والنازية الألمانية لم تظهر إلا في أرض غزاها ( هيجل - وفيخته - وغوته - ونيتشه ) .", "٣ - في التصور والأفكار : وحاجة الاتجاه الإسلامي إلى ( وحدة المحتوى الفكري ) لا يقل ضرورة عن حاجاته الأخرى الضرورية . وأعني بوحدة المحتوى الفكري ( القواعد الفقهية ) التي تحكم مواقف الحركة وتحدد آراءها وتصوراتها في كل شأن من الشؤون ( العقائدية - الاجتماعية - الاقتصادية - السياسية ) . وأود أن ألفت الانتباه - هنا - إلى ضرورة التمييز بين ( تخمة ) المكتبة الإسلامية بالكتابات والتأليف الإسلامية ( وفقر ) الحركة الإسلامية للأصول المتبناة كأساس تشريعي للنظم الإسلامية .. ثم إنني لا أريد أن يفهم من قولي - هذا - الدعوة إلى الحد من أفق التفكير .. فعلى الصعيد الفردي يبقى باب الاجتهاد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0016.png"}, {"n": 17, "paras": ["مفتوحاً على مصراعيه للباحثين من أهل الاختصاص ، أما على الصعيد الحركي فإن تبني الدعوة الإسلامية لوحدة مفاهيم شرعية أمر ضروري ينبغي تحقيقه . إن كثيراً من القضايا والأمور مما تتعرض له الحركة الإسلامية خلال سيرها فيه آراء وأقوال متعددة .. والتبني خير سبيل للخروج بالدعوة من قلق الخلاف وغموضه إلى وضوح الفكر ووحدته ..", "٤ - في التقييم والتقدير : ومن أسوأ ما أصيب به الاتجاه الإسلامي استخفاف أصحابه وعدم تقديرهم لأثقال المعارك التي يخوضونها فكرياً وسياسياً .. ولعلي لا أجد لهذه الظاهرة إلا أحد سببين : أولاً : اما تقدير الاتجاه الإسلامي ( الزائد ) لقوته وإمكاناته مما يجعله مستهيناً بأعدائه وخصومه .. وهذا ما انهزمت بسببه كتائب المسلمين في حنين: (ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم من الله شيئاً وضاقت عليكم الأرض بما رحبت ، ثم وليتم مدبرين ..) ثانياً : أو أنه شطحة من شطحات التواكل الذي لا يقيم للإعداد المادي وزناً . وهذا ما أنكرته الآية الكريمة بصريح دعوتها إلى الأخذ به والاستزادة منه: ( وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم ) . ومن الخطأ القول بأن الحركة الإسلامية قليلة الإمكانات إذا قيست بسواها من الحركات .. فالحركة الإسلامية فضلاً عن كونها"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0017.png"}, {"n": 18, "paras": ["الاتجاه الأقرب إلى فطرة الجماهير ، وفضلا عن كون مجالات عملها أوسع بكثير من مجالات غيرها .. فإن إمكاناتها الذاتية لا بأس بها قطعاً. ولكن افتقارها إلى التخطيط والتنسيق يضيق مجال الانتفاع بهذه الطاقات وقد يعمل مع الأيام على ضياعها .. لقد أضحى من المحال بقاء الحركة الإسلامية على ما هي عليه ، فالإسلام اليوم يتعرض في كل مكان لوحدة مصير .. وكل تأخير أو تقصير في بقاء الحركة على هذا الشكل سيكون حتماً على حساب الإسلام نفسه ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0018.png"}, {"n": 19, "paras": ["المحنة في حياة الدعوة والداعية", ". مدرسة المحنة . صور من محن الأولين . المحنة بين الأمس واليوم . كيف نواجه المحن", "- ١٧ - الدعوة ( ٢ )"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0019.png"}, {"n": 20, "paras": ["تكاد تكون المحنة من الظواهر الملازمة للحركة الإسلامية قديماً وحديثاً .. فالإسلام دعوة تمرد .. تمرد على مظاهر الحياة الجاهلية في كل صورها وأشكالها .. تمرد على العادات الجاهلية .. تمرد على الأفكار الجاهلية .. وتمرد على النظم والتشاريع الجاهلية . وهذه الخاصة التي يمتاز بها الإسلام ، جعلت الحركة الإسلامية أكثر تعرضاً للمحن ، وبالتالي جعلت المحنة لديها ذات مفهوم خاص لا يشاركها فيه سواها من الحركات الحزبية والسياسية ..", "المحنة تربية وتمحيص ، فالمحنة من أهم عوامل التكوين والاختيار في الإسلام .. وقد لا يكون للتكوين النظري قيمة ما لم تشترك فيه عوامل الشدة والبلاء .. وتفضيل النفس البشرية السلامة وعزوفها عن الخطر يستلزم في كثير من الأحيان تعريضها للصعاب والمكاره حتى تكتسب مناعة وقوة ، تمكنها من الصمود في وجه العوادي والنائبات .. والإيمان .. الإيمان نفسه بحاجة إلى المحنة لسبر غوره وإدراك مداه .. فالإيمان القوي الراسخ هو الذي يصمد في ساعة العسر .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0020.png"}, {"n": 21, "paras": ["أما الإيمان السقيم العليل فسرعان ما تكشفه المحن وتصدعه .. وصدق الله تعالى حيث يقول : ﴿ ومن الناس من يقول آمنا بالله .. فإذا أوذي في الله جعل فتنة الناس كعذاب الله .. ولئن جاء نصر من ربك ليقولن انا كنا معكم . أوليس الله بأعلم بما في صدور العالمين . وليعلمن الله الذين آمنوا وليعلمن المنافقين ﴾ . لذلك .. كان لا بد لكل دعوى من دليل .. فالإيمان دعوى بحاجة إلى دليل .. والثبات في وقت الشدة مظهر من مظاهر هذا الإيمان ودليل وجوده ورسوخه : ﴿ أحسب الناس أن يتركوا أن يقولوا آمنا وهم لا يفتنون . ولقد فتنا الذين من قبلهم فليعلمن الله الذين صدقوا وليعلمن الكاذبين ﴾ .", "صور من محن الأولين : هكذا قضت سنة الله .. أن يكون الحق في صراع أبدي مع الباطل .. وكلما بزغ نور للحق تنادت عناكب الليل لطمسه : ﴿ وأنه لما قام عبد الله يدعوه كادوا يكونون عليه لبداً . قل إنما أدعو ربي ولا أشرك به أحداً ﴾ .. ﴿ يريدون ليطفئوا نور الله بأفواههم والله متم نوره ولو كره الكافرون ﴾ . ومنذ الخليقة الأولى.. والنبوة الأولى.. منذ ولد الخير ووجد الشر .. والصراع عنيف ومخيف بينهما .. والحقيقة التي تتكرر باستمرار وتبدو بوضوح هي أن الحق دائماً في انتصار وأن الباطل دائماً في انتحار : ﴿ ولقد سبقت كلمتنا لعبادنا المرسلين انهم لهم المنصورون وان جندنا لهم الغالبون ﴾ ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0021.png"}, {"n": 22, "paras": ["المحنة في حياة ابراهيم :", "لم تكن المحنة التي تعرض لها خليل الرحمن إلا إحدى حلقات الصراع ، الممتدة عبر القرون ، الضاربة في أعماق التاريخ .. والتي تؤكد على الزمن غلبة أهل الحق وهزيمة أهل الباطل ..", "نشأ إبراهيم عليه السلام في مجتمع جاهلي ، كافر بكل القيم ، متطاول على نواميس الله .. وأبت الفطرة السليمة مجاراة التيار والانسياق مع الرأي العام ، والرضى والتسليم بالأمر الواقع .. وصمم إبراهيم على التصدي للجاهلية ومقاومتها مهما كلف الأمر ..", "وتبدأ المحنة في حياة هذا الفرد ، الأعزل من كل سلاح .. فرد يمتطي صهوة الحق وحيداً .. ويعلن على الملأ إيمانه بالله وكفره بما يعبدون من دونه .. ( قال أفرأيتم ما كنتم تعبدون من دون الله أنتم وآباؤكم الأقدمون ، فإنهم عدو لي إلا رب العالمين ) .", "ويجدر بالداعية - كل داعية - أن يقف هنا ملياً .. يستشعر عظمة الإيمان الذي اعتمر به قلب إبراهيم .. إنه وحيد ليس وراءه جماعة ولا أنصار .. وأعزل لا يملك قوة ولا سلاحاً .. ومنبوذ حق من ذوي القرابة والوالدين .. ولكن أنى للحق أن ينحني للباطل ، أو يتراجع أمام التهديد والوعيد ..", "وتشتد المحنة على إبراهيم .. ويلقى في النار .. ويرضى بقضاء الله ويفرح بلقائه . ومن الأفق الأعلى ، كان النبي المحتسب والرسول الممتحن يصغي إلى نداء الله ، وهو في حمأة اللهب"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0022.png"}, {"n": 23, "paras": ["المستعر : ﴿ يا نار كوني برداً وسلاماً على إبراهيم . وأرادوا به كيداً فجعلناهم الأخسرين ، ونجيناه ولوطاً إلى الأرض التي باركنا فيها للعالمين ﴾ . وتمضي قصة المحنة التي تعرض لها أبو الأنبياء ترسم لأهل الحق صوراً شتى من صور الرجولة والبطولة ، حتى ختم الله له بأن جعله من رسله المصطفين : ﴿ ومن يرغب عن ملة إبراهيم إلا من سفه نفسه . . ولقد اصطفيناه في الدنيا وإنه في الآخرة لمن الصالحين ﴾ .", "المحنة في حياة موسى : وحياة موسى عليه السلام لم تكن غير سلسلة من المآسي والآلام . بل إن المحنة رافقت موسى رضيعاً تتقاذفه الأمواج ويلفه الظلام وشبت معه فتى يانعاً هارباً من بطش فرعون . وزاد حياته محنة تعرضه لنقمة فرعون من جهة ، ولإيذاء قومه وسفههم من جهة أخرى . وظلم ذوي القربى أشد مضاضة على المرء من وقع الحسام المهند فكان على موسى أن يرد ضربات فرعون بيد، ويتقي مكائد قومه باليد الأخرى . وهذا لعمري أشد صنوف المحن وأفظع ألوان البلاء . فالدعوات قد تتمكن من مجابهة أخطر المحن الخارجية إذا كان صفها الداخلي قوياً متراصاً .. فكيف إذا كان متصدعاً منهاراً ؟ وموسى عليه السلام كان هذا الإنسان الذي تولى قيادة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0023.png"}, {"n": 24, "paras": ["شعب أعطى المقاد على خضوع بما ترادف عليه من جور الفراعنة ، وما تتابع عليه من ظلم الطغاة .. حتى هان عليه الهوان ، وألف الذل والاستسلام .. وكان الرسول المكلف بدعوة فرعون إلى عبادة الله وهو في أوج سطوته وقمة طغيانه : ﴿ إن فرعون علا في الأرض وجعل أهلها شيعاً يستضعف طائفة منهم يذبح أبناءهم ويستحيي نساءهم إنه كان من المفسدين ﴾ . ويمضي موسى في طريقه حاملاً كل التبعات .. معتمداً على الله وحده .. واثقاً من نصره وتأييده .. وفي فترة من فترات الضعف البشري يُحس موسى بالوجل والخوف يختلجان في صدره وهو في قلب المعركة يجابه فرعون وسحرته وزبانيته .. ولكن السماء سرعان ما تتداركه بالمدد ، وتقذف في قلبه الإيمان والطمأنينة : ﴿ فأوجس في نفسه خيفة موسى ، قلنا لا تخف إنك أنت الأعلى ، وألق ما في يمينك تلقف ما صنعوا ، إن ما صنعوا كيد ساحر ولا يفلح الساحر حيث أتى ﴾ .. لكم تدافعت الخطوب وتتابعت لتسد على موسى الطريق ، وتغلق دونه المنافذ والدروب .. ولكن سرعان ما كانت تنكشف أمام العزيمة والإيمان . ويمضي الزحف المقدس يشق طريقه عبر الحياة بثقة وتصميم .. لكم حاول قارون أن يفتن الناس بماله ، ويصرفهم عن موسى ودعوته .. لكم حاول شراء الضمائر ورمي موسى بشتى التهم والأراجيف .. ولكن الله كان يكشف ما يُضمر .. ويخرج موسى من هذه التجارب أصلب عوداً وأشد صموداً ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0024.png"}, {"n": 25, "paras": ["ويختم القرآن قصة موسى وفرعون فيقول : ﴿ لقد جاء آل فرعون النذر .. كذبوا بآياتنا كلها فأخذناهم أخذ عزيز مقتدر . أكفاركم خير من أولئكم أم لكم براءة في الزبر . أم يقولون نحن جميع منتصر . سيهزم الجمع ويولون الدبر . بل الساعة موعدهم والساعة أدهى وأمر .. ﴾ .", "المحنة في حياة عيسى : مما لا ريب فيه أن عيسى عليه السلام كان يتمتع بطاقة ضخمة من الصبر والاحتمال .. فالظروف القاسية ، والمكائد العديدة ، والمحن المتتابعة التي قا ساها ، كانت كلها تشير إلى عظمة الشخصية التي تحلى بها عيسى بن مريم .. ومما زاد في قسوة الظروف التي أحاطت به وبنشأته ، أنه واجه في ماضي مولده ألوان الشكوك .. كما واجه في حاضر دعوته ضروب العنت والتمرد .. ويكفي لكي نقدر مدى ما وصل إليه العنت والتمرد أن نعرف أن الخوارق والمعجزات التي بلغت على يدي عيسى حداً كبيراً لم يكن لها ذلك الأثر المنتظر في استمالة النفوس وتأليف القلوب .. ولكن عيسى عليه السلام لم ينثن أو يتراجع أو يحدث نفسه بشيء من هذا .. كان يؤمن بأنه رسول .. وأن عليه البلاغ المبين. وكان طيب النفس حليماً ، لا تخرجه سفاهة المعارضين إلى استعمال العنف واتباع غير سبيل المؤمنين .. مر يوماً وتلامذته بقرية فدعا أهلها للهدى ، وذكرهم بالله والآخرة .. فما كان منهم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0025.png"}, {"n": 26, "paras": ["إلا أن شتموه وعيروه فلم يزد عليه السلام إلا أن قال خيراً وانصرف .. وسأله حواريوه عن أمره مع القوم يقولون له شراً فلا يرد عليهم إلا بالخير ، فقال : « كل ينفق مما عنده » . وإنك لتشعر وأنت تصغي إلى تعاليمه بعظمة الإيمان، ورقة النفس ، وسمو الخلق ، وسعة الصدر وغيرها من الصفات التي تحلت بها شخصيته الفذة .. كان كثيراً ما يقول لحواريه : « طوبى لكم إذا عيروكم ، وطردوكم ، وقالوا عليكم كل كلمة شريرة من أجلي كاذبين .. افرحوا وتهللوا لأن أجركم عظيم في السموات . فإنهم هكذا طردوا الأنبياء قبلكم » (١) « سيخرجونكم من المجامع . بل تأتي ساعة فيها يظن كل من يقتلكم أنه يقدم خدمة لله » (٢) . حاول اليهود أن يُخففوا من أثر دعوته وأن يُخفوا عن الناس أمره .. ولكن أسقط في أيديهم .. فالحق أبلج .. والصبح منير .. وان الله يقذف بالحق على الباطل فيدمغه فإذا هو زاهق .. ولما أعيت الحيلة أهل الباطل .. جاءهم رجل اسمه « يهوذا الاسخريوطي » يدلهم على مخبأ عيسى وصحبه .. وكان عيسى حينذاك قد أدرك ما يبيت له .. وعرف أن عيون اليهود تترصده . وان القوم قد ائتمروا به ليقتلوه.. فأوى إلى بستان", "(١) انجيل متى - الاصحاح الخامس .", "(٢) انجيل يوحنا - الاصحاح الثاني ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0026.png"}, {"n": 27, "paras": ["يقضي فيه ليلته ومعه بعض حوارييه .. وفي الليل كان اليهود قد عثروا على مكنه ، وضربوا نطاقاً حوله بانتظار الساعة الحاسمة ليُطبقوا عليه ، وينفذوا مؤامرتهم الكبرى .. أما عيسى روح الله .. فقد كانت عين الله تحرسه وترعاه فلما هم القوم بما دفعهم إليه حقدهم الأسود .. كان مُحاطاً بعناية الله ، تحجبه عن أعينهم قدرته عز وجل .. ووقع تحت أيديهم رجل شديد الشبه به .. عقد الله لسانه فما استطاع كلاماً .. ولم يدر القوم وهم يحملونه إلى ساحة الصلب أنهم يحملون « يهوذا الاسخريوطي » نفسه والذي أوقعه الله في شر فعله . وقتلوه وهم يحسبون أنهم قتلوا عيسى بن مريم .. ( وما قتلوه وما صلبوه ولكن شبه لهم . وان الذين اختلفوا فيه لفي شك منه . ما لهم به من علم إلا اتباع الظن . وما قتلوه يقيناً بل رفعه الله إليه . وكان الله عزيزاً حكيماً ) ..", "محنة الاسلام في عهد النبوة : والمحنة التي واجهت الإسلام في عهد النبوة لم تكن أقل ضراوة مما تعرضت له الرسالات والرسل من قبل إن لم تزدهم جميعاً .. كان الإسلام ثورة على الجاهلية من أول يوم .. ثورة استهدفت نسف القواعد التي يقوم عليها المجتمع الجاهلي .. فليس من طبيعة الإسلام أن يهادن الأوضاع الخربة ، أو يعمد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0027.png"}, {"n": 28, "paras": ["إلى ترميمها وإصلاحها .. فهو لا يقبل أنصاف الحلول ولا أرباعها . ويرفض المساومة والترقيع .. وإنما يعتمد سياسة الهدم والبناء .. هدم الجاهلية بكل مرافقها ، وبناء الحياة الإسلامية بجميع مقتضياتها . وإذا كانت هذه طبيعة الدعوة التي نهض بها محمد بن عبدالله ﷺ فبديهي أن تستأسد قوى الجاهلية وتستميت في الدفاع عن كيانها المهدد بالنسف والدمار .. حتى بلغ تحدي المشركين وحربهم للاسلام والمسلمين حداً لا يوصف ..", "حرب الأعصاب : تفنن أهل الجاهلية في حرب محمد .. وابتكروا كل جديد لضرب الإسلام .. وحشدوا كل قواهم لعرقلة المسيرة القرآنية .. فعمدوا أولاً إلى أسلوب نفسي خسيس يستهدف تدمير أعصاب الرسول ﷺ والقضاء على روحه المعنوية العالية . وشنوا لذلك حملات عنيفة من السخرية والاستهزاء عرض لها القرآن الكريم في أكثر من موضع .. ﴿ وقالوا لن نؤمن لك حتى تفجر لنا من الأرض ينبوعاً .. أو تكون لك جنة من نخيل وعنب فتفجر الأنهار خلالها تفجيراً .. أو تسقط السماء كما زعمت علينا كسفاً ، أو تأتي بالله والملائكة قبيلا . أو يكون لك بيت من زخرف أو ترقى في السماء ولن نؤمن لرقيك حتى تنزل علينا كتاباً نقرؤه ﴾ ( الإسراء ٩٠ ) . وعندما فشلت هذه الأساليب الخسيسة عمد المشركون إلى"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0028.png"}, {"n": 29, "paras": ["اختلاق الشائعات والتهم على رسول الله، وبثوها في كل الأوساط، ليضعفوا الثقة به وليصدوا عن سبيل الله .. لكم افتروا على من سموه بالأمس صادقاً وأميناً ورموه بما ليس فيه . ولكم سددوا سهامهم إلى نحر الإسلام، وأطلقوا حرابهم إلى صدر الحركة الإسلامية الفتية .. ﴿وقد مكروا مكرهم وعند الله مكرهم وإن كان مكرهم لتزول منه الجبال﴾", "- ( إبراهيم ٤٦ ) . وكانت المحنة على ضراوتها وقسوتها لا تزيد محمداً إلا صلابة وتصميماً .. صلابة في مواجهة التحدي كائناً ما كان نوعه ومداه .. وتصميماً على المضي مهما كانت التضحيات .. قال الوليد بن المغيرة يوماً - وهو زعيم من زعماء الجاهلية وطاغية من طغاتها - : ( يا معشر قريش .. انه قد حضر هذا الموسم . وان وفود العرب ستقدم عليكم فيه .. وقد سمعوا بأمر محمد هذا .. فأجمعوا فيه رأياً واحداً . ولا تختلفوا فيكذب بعضكم بعضاً .. قالوا : نقول كاهن .. قال : لا والله ما هو بكاهن ، لقد رأينا الكهان . فما هو بزمزمتهم ولا سجعهم . قالوا : نقول مجنون . قال : ما هو بمجنون ، لقد رأينا الجنون وعرفناه فما هو بخنقه ولا تخالجه ولا وسوسته .. قالوا : نقول شاعر .. قال : ما هو بشاعر . لقد عرفنا الشعر كله رجزه وهزجه وقريضه ومقبوضه ومبسوطه . فما هو بشاعر . قال الوليد بن المغيرة : إن أقرب القول فيه أن تقولوا هو ساحر .. يقول السحر ، فيفرق به بين المرء وأخيه ، وبين المرء وزوجه ،"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0029.png"}, {"n": 30, "paras": ["وبين المرء وعشيرته . فتفرقوا عنه بذلك ) . وفي الوليد بن المغيرة هذا أنزل الله آيات التهديد والوعيد لتكون له ولأمثاله على مر العصور عبرة .. قال تعالى : ﴿ كلا إنه كان لآياتنا عنيداً .. سأرهقه صعوداً .. إنه فكر وقدر .. فقتل كيف قدر .. ثم قتل كيف قدر .. ثم نظر .. ثم عبس وبسر .. ثم أدبر واستكبر .. فقال ان هذا إلا سحر يؤثر .. إن هذا إلا قول البشر .. سأصليه سقر .. وما أدراك ما سقر .. لا تبقي ولا تذر .. لواحة للبشر .. عليها تسعة عشر ﴾ .", "ثم يعرض القرآن الكريم صوراً شتى من تحدي الجاهلية للحركة الإسلامية في العصر النبوي .. ﴿ أم يقولون شاعر نتربص به ريب المنون .. قل تربصوا فإني معكم من المتربصين .. أم تأمرهم أحلامهم بهذا أم هم قوم طاغون . أم يقولون تقوّله ، بل لا يؤمنون .. فليأتوا بحديث مثله إن كانوا صادقين ﴾ .", "تعرض وإيذاء ومحاولات اغتيال :", "لم يكتف طغاة مكة بما تناولته ألسنتهم من كذب وافتراء على الإسلام وأهله .. بل لقد تجرأوا - مراراً - على النيل من نبي الإسلام نفسه والاعتداء عليه ..", "يئسوا من الحرب النفسية وحرب الأعصاب وحرب الشائعات .. فلجأوا إلى الحرب الحسية ينالون بها من دعاة الإسلام . وفجروا أحقادهم حمماً .. وأضرموا نار العداوة والبغضاء في كل مكان"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0030.png"}, {"n": 31, "paras": ["تشفيًا وانتقاماً ممن صبأ عن دين الآباء والأجداد وكفر بهبل واللات .. ويجتمع سادة قريش يوماً في ( الحجر ) ويذكرون محمداً وتحديه السافر لمقدساتهم .. فقالوا : ما رأينا مثل ما صبرنا عليه من أمر هذا الرجل قط .. سفه أحلامنا وفرق جماعتنا .. وسب آلهتنا .. لقد صبرنا منه على أمر عظيم .. وشتم آباءنا .. وعاب ديننا .. وفرق جماعتنا فبينما هم كذلك إذ مر بهم رسول الله ﷺ .. فوثبوا عليه وثبة رجل واحد . وأحاطوا به من كل جانب وصاحوا به قائلين : أنت الذي تقول كذا وكذا ؟ فيجيبهم نبي الهدى بكل ثقة واعتزاز : « نعم أنا الذي أقول ذلك » يقولها بكل صراحة ويعلنها بملء فيه .. يصدع بها كبرياءهم .. ويصفع طغيانهم .. ولقد أصابه منهم في ذلك اليوم ما أصابه .. وأدركهم أبو بكر الصديق رضي الله عنه وقد كادوا يجهزون عليه .. فانبرى يدافع عنه ويقول . « أتقتلون رجلاً أن يقول ربي الله ؟؟ » . ولما أوقع في أيدي المشركين .. وأعجزتهم الحيلة تداعوا إلى مؤتمر عقدوه في دار الندوة .. وكان المسلمون قد بدأوا بالهجرة إلى المدينة . وظنوا أن الفرصة قد سنحت للخلاص من محمد في غيبة من أصحابه وأتباعه . ولما وضعوا خطتهم ، وحزبوا أمرهم .. كشف الله مكرهم ورد كيدهم : ﴿ وإذا يمكر بك الذين كفروا ليثبتوك أو يقتلوك أو يخرجوك، ويمكرون ويمكر الله والله خير الماكرين ﴾ وفي أعقاب الهجرة إلى المدينة. وانتصار الإسلام على الجاهلية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0031.png"}, {"n": 32, "paras": ["في ( بدر ) .. استأجر - صفوان بن أمية - عمير بن وهب سراً وندبه للخروج إلى المدينة واغتيال محمد ﷺ .. على أن يقضي صفوان له دينه ويكفل عياله .. وقدم عمير إلى المدينة متوشحاً سيفه ، حتى دخل على الرسول وهو في المسجد .. فلما رآه الرسول ﷺ قال له : « أدن يا عمير » فدنا .. ثم قال : أنعموا صباحاً . وكانت تحية أهل الجاهلية بينهم .. فقال الرسول : « قد أكرمنا الله بتحية خير من تحيتك يا عمير .. بالسلام ، تحية أهل الجنة » فقال : أما والله يا محمد إن كنت بها لحديث عهد .. قال الرسول : « فما جاء بك يا عمير » . قال : جئت لهذا الأسير في أيديكم فأحسنوا إليه . قال الرسول : فما بال السيف في عنقك ؟ قال عمير : قبحها الله من سيوف وهل أغنت عنا شيئاً .. قال الرسول : أصدقني . ما الذي جئت له ؟ قال عمير : ما جئت إلا لذلك . قال الرسول : بل قعدت أنت وصفوان بن أمية في الحجر . فذكرتما أصحاب القليب من قريش ثم قلت : لولا دين علي وعيال عندي لخرجت حتى أقتل محمداً . فتحمل لك صفوان بدينك وعيالك على أن تقتلني له . والله حائل بينك وبين ذلك .. » . فقال عمير : أشهد انك رسول الله . قد كنا يا رسول الله نكذبك بما كنت تأتينا به من خبر السماء وما ينزل عليك من الوحي . وهذا أمر لم يحضره إلا أنا وصفوان ، فوالله اني لأعلم أن ما أتاك به إلا الله . فالحمد لله الذي هداني للاسلام وساقني"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0032.png"}, {"n": 33, "paras": ["هذا المساق . ثم شهد شهادة الحق .", "المحنة في حياة الصحابة :", "وفي عهد النبوة تعرض دعاة الاسلام لأبشع صنوف الإيذاء والتعذيب . ذنبهم أنهم آمنوا بالله وكفروا بالطاغوت .. وجريمتهم أنهم استجابوا لنداء الفطرة وارتفعوا فوق الحطام . وهذا وحده كان كافياً لتفجير الأحقاد في نفوس المشركين ويفقدهم صوابهم ويدفعهم إلى التنكيل بالمؤمنين من غير هوادة ولا لين ..", "ولم تقتصر المحنة على نفر دون نفر أو طبقة دون أخرى .. بل لقد بلغت الجميع ، النساء والرجال، الصغار والكبار، العبيد والأحرار. فقال ابن اسحق: (إن المشركين عدوا على كل من أسلم واتبع رسول الله من أصحابه . فوثبت كل قبيلة على من فيها من المسلمين ، فجعلوا يحبسونهم ويعذبونهم بالضرب والجوع والعطش وبرمضاء مكة إذا اشتد الحر .", "محنة بلال :", "كان أمية بن خلف يُخرج بلالاً الحبشي إذا حميت الظهيرة ، فيطرحه على ظهره في بطحاء مكة ، ثم يأمر بالصخرة العظيمة فتوضع على صدره ، ثم يتهدده قائلاً : إنك ستظل هكذا حتى تموت أو تكفر بمحمد أو تعبد اللات والعزى .. وكان بلال رضي الله عنه وأرضاه يردد بكل تصميم وبكل اعتزاز الهتاف"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0033.png"}, {"n": 34, "paras": ["الإسلامي الخالد : أحد أحد .. أحد أحد ..", "محنة آل ياسر : و كان بنو مخزوم يُخرجون ( آل ياسر ) جميعاً - الأم والأب والأولاد - يعذبونهم برمضاء مكة ويحرقون أجسادهم بالحديد المحمى . أما ياسر ( الأب ) فلم يقو على تحمل العذاب لكبر سنه فمات لتوه . وأما سمية ( الأم ) فقد أغلظت القول لأبي جهل فطعنها عدو الله بحربة في أحشائها فكانت أول شهيدة في الإسلام ..", "محنة عثمان بن مظعون : ولما رأى عثمان بن مظعون ما يواجه إخوانه الدعاة من البلاء والعذاب، وهو يغدو ويروح بأمان في جوار (الوليد بن المغيرة) قال: والله إن غدوي ورواحي آمناً بجوار رجل من أهل الشرك لنقص كبير في نفسي . فما كان منه إلا أن مشى إلى الوليد ورد عليه جواره وقال له : لقد أحببت ان لا أستجير بغير الله بعد اليوم .. ثم خاطب المشركين بكلام ازعجهم .. فقام إليه لبيد بن ربيعة فلطم عينه فخضبها . والوليد بن المغيرة قريب يرى ما أصابه .. فقال له : أما والله يا ابن اخي إن كانت عينك عما اصابها لغنية . لقد كنت في ذمة منيعة . فقال عثمان : بلى والله إن عيني الصحيحة لفقيرة إلى ما أصاب اختها في الله ، وإني لفي جوار من هو أعز"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0034.png"}, {"n": 35, "paras": ["منك وأقدر يا أبا عبد شمس . ثم أنشد : فإن تك عيني في رضا الرب نالها يدا ملحد غي وليس بمهتد فقد عوض الرحمن منها ثوابه ومن يرضه الرحمن يا قوم يسعد فإني وإن قلتم غوي مضلل سفيه على دين الرسول محمد أريد بذاك الله والحق ديننا على الرغم من يبغي علينا ويعتدي هكذا مضت عصبة الإيمان في عهد النبوة تشق طريقها إلى الأمام لا تخاف دركاً ولا تخشى . وتقدم في سبيل الله الشهيد تلو الشهيد .. وتمضي الأيام كالحة كعتمة الليل .. وتقبل غيرها بمزيد من المحن والبلاء .. ومواكب الحق تتابع زحفها العتيد على درب الخلود .. تحرر أصحابها من عبودية الدنيا وشهواتها .. فأصبحوا لا يحسون طعم السعادة بغير طاعة الله .. ولا يرون الجهاد إلا طريقاً إلى الشهادة وباباً إلى جنة الله والفوز برضاه .. ﴿ ولا تحسبن الذين قتلوا في سبيل الله أمواتاً بل أحياء عند ربهم يرزقون. فرحين بما آتاهم الله من فضله ، ويستبشرون بالذين لم يلحقوا بهم من خلفهم ألا خوف عليهم ولا هم يحزنون. يستبشرون بنعمة من الله وفضل وأن الله لا يضيع أجر المؤمنين ﴾ .", "- ٣٣ - الدعوة (٣)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0035.png"}, {"n": 36, "paras": ["نموذج من شهداء الاسلام في عصر النبوة : لكم شهدت أيام الإسلام في عصر النبوة من أبطال صناديد شرفوا التاريخ ورصعوا جيد الانسانية بأكاليل الغار والفخار . ويكفي أن نختار منهم ( خبيب بن عدي ) لندرك أي أثر كان للعقيدة في نفوس هؤلاء .. اعتقل خبيب وكان في طريقه من المدينة إلى ( عضل والقارة ) ليقوم بمهام الدعوة التي كلفه بها رسول الله ﷺ . وساقه المجرمون إلى مكة وباعوه « لحجر بن أبي اهاب التميمي » ليقتله بأبيه الذي قتل في غزوة بدر الكبرى . وفي اليوم المحدد لقتله أخرجه المشركون إلى « التنعيم » (١) ليصلبوه .. فقال لهم : إن رأيتم أن تدعوني حتى أركع ركعتين فافعلوا . قالوا : دونك فاركع .. فركع ركعتين أتمهما وأحسنهما، ثم أقبل على القوم . فقال : أما والله لولا أن تظنوا أني إنما طولت جزعاً من الموت لاستكثرت من الصلاة (٢) .. وعندما رُفع خبيب على الخشبة قال له المشركون : ارجع عن الإسلام نخلي سبيلك . فقال : لا والله ما أحب أن أرجع عن الإسلام وان لي ما في الأرض جميعاً .", "- ارجع يا خبيب ..", "- لا أرجع أبداً ..", "(١) مكان شرقي مكة .", "(٢) هو أول من سن هاتين الركعتين عند القتل ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0036.png"}, {"n": 37, "paras": ["- أما واللات لئن لم تفعل لنقتلنك ..", "- إن قتلي في الله لقليل .. وجعلوا وجهه لغير القبلة .. فقال : أما صرفكم وجهي عن القبلة فإن الله يقول : ﴿ فأينما تولوا فثم وجه الله ﴾ ثم قال : ( اللهم إني لا أرى إلا وجه عدو . اللهم إنه ليس ههنا أحد يبلغ رسولك عني السلام ، فبلغه أنت السلام ) .. وكان الرسول ﷺ في هذا الوقت بين صحبه في المدينة . فأخذته غيبة ثم قال : « هذا جبريل يقرئني من خبيب السلام». واقترب من خبيب أربعون رجلاً من المشركين ، بأيديهم الرماح . وقالوا : هذا الذي قتل آباءكم في بدر . فقال خبيب : اللهم إنا قد بلغنا رسالة رسولك .. فأبلغه الغداة ما يصنع بنا . اللهم أحصهم عدداً .. واقتلهم بدداً . ولا تغادر منهم أحداً .. وهنا ألقى معاوية بن أبي سفيان - وكان بين المشركين - بنفسه إلى الأرض فرقاً من دعوة خبيب ، وهرب حكيم بن حزام ، واختفى جبير بن مطعم .. عندما أخذت الرماح تمزق جسده ، استدار إلى الكعبة وقال : الحمد لله الذي جعل وجهي نحو قبلته التي ارتضى لنفسه ونبيه والمؤمنين . ثم استدار إلى القوم وأنشد أبياته الخالدة : لقد جمع الأحزاب حولي وألبوا قبائلهم واستجمعوا كل مجمع وقد جمعوا أبناءهم ونساءهم وقُرِّبت من جذع طويل ممنع"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0037.png"}, {"n": 38, "paras": ["إلى الله أشكو غربتي ثم كربتي وما جمع الأحزاب لي حول مصرعي فذا العرش صبرني على ما يراد بي فقد بضعوا لحمي وقد ياس مطمعي وقد خيروني الكفر والموت دونه وقد ذرفت عيناي من غير مجزع وما بي حذار الموت اني ميت ولكن حذاري جحيم نار ملفع وذلك في ذات الإله وإن يشأ يبارك على أوصال شلو ممزع فلست أبالي حين أقتل مسلماً على أي جنب كان في الله مصرعي", "واستمر أعداء الله يمزقون جسد « خبيب » برماحهم وهو لا يفتر يردد « لا إله إلا الله محمد رسول الله » حتى لفظ نفسه الأخير وفاضت روحه الزكية الطاهرة إلى الملأ الأعلى تشكو إلى الله ظلم الظالمين ..", "المحنة في عصر التابعين : وينقضي عصر الصحابة ويأتي عصر التابعين . ويطالعنا التاريخ بألوان شتى من محن الإسلام .. ففي هذه المرحلة تتكاتف لهدم الإسلام معاول الأبناء والأعداء .. ويتولى السلطة طغاة متجبرون يسومون المؤمنين سوء العذاب ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0038.png"}, {"n": 39, "paras": ["الحجاج بن يوسف : ففي عام ٧٥ هجرية يتولى الحجاج بن يوسف الحكم في العراق. ويشهد هذا البلد الإسلامي في عهده أياماً سوداء .. شأنه شأن كل طاغية مستبد همه إخضاع الناس لقوته وجبروته ، وإقامة سلطانه ولو على الجماجم والأشلاء .. كان الحجاج بلاء على الإسلام والمسلمين . شوّه الإسلام بانتسابه إليه . وأساء إلى الدين بتوليه الحكم باسم الدين . فكم الأفواه .. وجرد سيفه للبطش بكل من يخرج عن طاعته ..", "سعيد بن جبير : ومن سنة الله في خلقه أنه يهيء للطغاة رجالاً لا يهابون الطغيان .. يصنعهم على عينه . ويهبهم الجرأة فيه . وكان سعيد بن جبير أحد هؤلاء الذين خلصوا من حظ أنفسهم ، وهانت عليهم دنياهم ، ونذروا أنفسهم لله .. وعندما صمم الحجاج على قتله والخلاص منه أرسل جنوداً بطلبه فجاءوا به ، وأدخلوه عليه .. سأله الحجاج عن اسمه . قال : سعيد بن جبير . قال الحجاج : بل أنت شقي بن كسير ( تحقيراً وسخرية ) . قال سعيد : بل كانت أمي أعلم باسمي منك . قال الحجاج : شقيت أنت وشقيت أمك . قال سعيد : الغيب يعلمه غيرك ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0039.png"}, {"n": 40, "paras": ["قال الحجاج : لأبدلنك بالدنيا ناراً تلظى . قال سعيد : لو علمت أن ذلك بيدك لاتخذتك إلهاً . قال الحجاج : فما قولك في محمد ؟ قال : نبي الرحمة وإمام الهدى عليه الصلاة والسلام . قال الحجاج : فما بالك لم تضحك ؟ قال سعيد : وكيف يضحك مخلوق من طين والطين تأكله النار . قال الحجاج : فما بالنا نضحك . قال سعيد : لم تستو القلوب . وفكر الحجاج بطريقة أخرى لاستمالته وإذلاله .. فأمر بالذهب والمال واللؤلؤ والياقوت فجمع بين يديه ، ولكن أنى لهذه المغريات أن تجد لها طريقاً إلى قلب شغله حب الله وزهد بالدنيا وما فيها . فقال سعيد : إن كنت جمعت هذا لتفتدي به من فزع يوم القيامة فقد أخطأت . وإن فزعة واحدة تذهل كل مرضعة عما أرضعت . ولا خير في شيء جمع للدنيا إلا ما طاب وزكا . فأمر الحجاج بالموسيقى فصدحت ونفخ في الناي وضرب بالعود . فبكى سعيد . فقال له الحجاج : ما يبكيك، أهو اللهو؟ فقال سعيد : بل هو الحزن .. أما النفخ فذكرني يوماً عظيماً ، يوم ينفخ في الصور . وأما العود فشجرة قطعت في غير حق . وأما الأوتار فإنها امعاء الشياه يبعث بها معك يوم القيامة . فقال الحجاج : ويلك يا سعيد ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0040.png"}, {"n": 41, "paras": ["فقال سعيد : الويل لمن زحزح عن الجنة وأدخل النار . قال الحجاج : اختر يا سعيد أي قتلة تريد أن أقتلك . فقال سعيد : بل اختر لنفسك يا حجاج .. فوالله ما تقتلني قتلة إلا قتلك الله مثلها يوم القيامة .. قال الحجاج : أفتريد أن أعفو عنك ؟ قال سعيد : إن كان العفو فمن الله . واما انت فلا براءة لك ولا عذر . قال الحجاج : اذهبوا به فاقتلوه . فلما خرجوا به من الباب ضحك . فأخبر الحجاج بذلك . فأمر برده ، وقال له : ما أضحكك ؟ قال سعيد : عجبت من جرأتك على الله وحلم الله عنك . قال الحجاج : اقتلوه . فقال سعيد : وجهت وجهي الذي فطر السموات والأرض حنيفاً مسلماً وما أنا من المشركين . قال الحجاج : شدوا به لغير القبلة . قال سعيد : فأينما تولوا فثم وجه الله . قال الحجاج : كبوه لوجهه . قال سعيد : منها خلقناكم وفيها نعيدكم ومنها نخرجكم تارة أخرى . قال الحجاج : اذبحوه . قال سعيد : أما إني أشهد أن لا إله إلا الله وحده لا شريك له . وأن محمداً عبده ورسوله . خذها مني حتى تلقاني يوم القيامة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0041.png"}, {"n": 42, "paras": ["ثم دعا سعيد الله قائلاً : « اللهم لا تسلطه على أحد يقتله بعدي » ثم ذبحوه على النطع - رحمه الله - . وعاش الحجاج بعده خمس عشرة ليلة ثم مات ..", "المحنة بين الأمس واليوم : هكذا تبدت معالم الصراع بين الحق والباطل على مدار التاريخ . إنها صورة واحدة ذات أشكال متعددة .. تتغير فيها الأزمان والأشخاص وتبقى الحقيقة هي هي .. إنه استعلاء الإيمان في كل زمان .. واعتزاز الحق في كل عصر .. نماذج من الرجولة صاغتها عقيدة الإسلام .. إنه الإنتاج الفريد الذي تصدره مدرسة النبوة في كل حين ، لهيب الحياة اكسير الحياة . لقد برهن هذا الدين بما تزاحم في تاريخه الطويل من أبطال ورجال عن جدارته الفذة في خلق البطولة والرجولة : .", "حسن البنا الامام الشهيد : وفي مطلع القرن العشرين كانت الأمة الإسلامية على موعد مع بطل من أبطال الإسلام في العصر الحديث ، ذلكم هو حسن البنا الإمام الشهيد .. ولد حسن البنا في مجتمع يحكمه الأقطاع ، وتتفشى فيه البدع والخرافات .. مجتمع فيه كل خصائص الجاهلية الأولى وعاداتها وتقاليدها . مجتمع أنهكه الاستعمار البريطاني وحطم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0042.png"}, {"n": 43, "paras": ["قواه المعنوية والمادية.. وأعلنها حسن البنا صيحة مدوية، أيقظت النائمين، ونبهت الغافلين، وحركت مشاعر المؤمنين .. وترددت أصداء هذه الصيحة في كل مكان .. واستجاب لها المئات من كل جنس .. وتمخض بها الزمان عن حركة إسلامية أصبحت بعد حين ملء عين العالم وسمعه وبصره .. وكان حسن البنا - مع هذا - دائم التحسب لما يخبئه الزمن من بلاء ومحن .. فكان يهيىء الدعاة من أول الطريق لمواجهة كل الفروض .. كان يُسرّ لهم في أحاديثه الخاصة والعامة ويقول : « إن الدنيا ستتألب عليكم . وستحاربكم في ارزاقكم . وإن السجون ستفتح أبوابها لإيوائكم واستضافتكم » . وخطبهم يوماً فقال : « لتبلونّ في اموالكم وانفسكم ولتسمعنّ من الذين أوتوا الكتاب من قبلكم ومن الذين أشركوا أذى كثيراً . وان تصبروا وتتقوا فإن ذلك من عزم الأمور » . وهذه سنة الله تبارك وتعالى في اصحاب الدعوات والمؤمنين بها والعاملين لها . أن يبتليهم في أنفسهم وأرزاقهم وأولادهم وبالإيذاء والكيد والافتراء والكذب والاعتداء من منافسيهم وخصومهم والذين لا يعرفون حقيقة دعوتهم : ( فلن تجد لسنة الله تبديلاً ولن تجد لسنة الله تحويلاً ) . ما بعث الله نبياً من الأنبياء .. ولا أرسل رسولاً من لدنه إلا بالخير والهداية والصراط المستقيم . ليُخرج الناس من الظلمات إلى النور بإذن ربهم إلى صراط العزيز الحميد .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0043.png"}, {"n": 44, "paras": ["لهذا جاء نوح .. وبهذا بعث إبراهيم .. ولهذا دعا موسى .. وفي سبيله أرسل عيسى .. وبهذه الحقائق هتف محمد صلوات الله وسلامه عليهم أجمعين .. تلك سنة الله التي لا تختلف : ﴿ وكذلك جعلنا لكل نبي عدواً من المجرمين وكفى بربك هادياً ونصيراً ﴾ . وفي جلسة من جلسات المباسطة قال حسن البنا لإخوانه : « لقد جاءني سيدنا عمر في الرؤيا ينبئني بأعلى صوته : ستقتل يا حسن .. فنهضت وحمدت الله ثم نمت ثانية . فجاءني الهاتف قائلاً : ستقتل يا حسن . ثم قمت وتهجدت إلى الفجر » .. وفعلا .. لم يكد اعداء الإسلام يشعرون بقوة الحركة الإسلامية وخطرها على وجودهم حتى راحوا يصلونها بنار مكرهم وحقدهم . وفي الثاني عشر من شباط عام ١٩٤٩ كان اعوان الملك فاروق ينفذون بأمر ( الانجليز ) جريمتهم البشعة النكراء . وقتل حسن البنا في وضح النهار وفي اكبر شارع من شوارع القاهرة برصاص الطغاة والمستعمرين . ومات حسن البنا في وقت كانت الأمة الإسلامية أحوج ما تكون فيه إليه وإلى امثاله .", "أصحاب العقيدة يدفعون الثمن : وتشتد المحنة في حياة الدعوة .. وتؤول قيادة الأمة إلى حكام طغاة يسومون المؤمنين سوء العذاب يقتلون رجالهم .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0044.png"}, {"n": 45, "paras": ["ويرملون نساءهم .. وينزلون بهم كل منكر .. وحق على دعوة الإسلام أن تدفع الثمن .. وتدفعه بسخاء دماء وضحايا وشهداء ..", "وما كان لعصبة أن تنكص وقد وعت المسؤولية قبل حملها .. وقدرت التبعات قبل التصدي لها ..", "لقد مكر بالإسلام أبناؤه وأعداؤه .. وعبئت للنيل منه قوى الشرق والغرب .. وجند لذلك رجال وأموال وألسن وأقلام وكتب وإذاعات ..", "فرواد الجاهلية لا يخشون غير الإسلام على زعاماتهم .. ويدركون ان انتصار الحركة الإسلامية يعني انكشاف أمرهم ، وانفضاح مكرهم ، وبالتالي زوالهم عن مسرح الخداع والتضليل إلى الأبد ..", "على طريق ( البنا ) تلاحقت مواكب الشهداء .. ومشت قوافل المجاهدين .. وتتابع الزحف العتيد يصدع بالحق عروش الطغاة ويزلزل صروح الظالمين .. ويلقي في قلوب الذين كفروا الرعب .", "على نفس الطريق مضى العالم الفقيه صاحب ( التشريع الجنائي في الإسلام ) (١) مستعلياً بإيمانه وفياً لإسلامه ..", "(١) الشهيد عبد القادر عودة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0045.png"}, {"n": 46, "paras": ["وعلى نفس الطريق مضى رائد الفكر الإسلامي الحديث وصاحب ( الظلال والمعالم ) (١) وفي الكون صدى قصيدته العصماء زغاريد بهجة وأغاني أعراس للشهيد الجديد .. أخي إن ذرفت علي الدموع وبللت قبري بها في خشوع فأوقد لهم من رفاتي الشموع وسيروا بها نحو مجد تليد أخي إن مت نلق أحبابنا فروضات ربي أعدت لنا واطيارها رفرفت حولنا فطوبى لنا في ديار الخلود أخي ستبيد جيوش الظلام ويشرق في الكون فجر جديد فأطلق لروحك اشواقها تر الفجر يرمقنا من بعيد إنه طريق واحد تتزاحم فيه خطى الشهداء . وإنها امنية واحدة ترددها قلوب المؤمنين « الموت في سبيل الله اسمى امانينا » .", "(١) الشهيد سيد قطب ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0046.png"}, {"n": 47, "paras": ["كيف نواجه المحن ؟ : إن الحركة الإسلامية إذ تواجه اليوم ما تواجه من تحديات وضغوط .. وهي إذ تكابد من تكابد من محن وبلاء .. ينبغي ان تستوي على يابسة ، وتستقيم على صخر . وبالتالي ينبغي ان تنطلق على هدى ، فلا تتحكم في سيرها الانفعالات او تميد بها العواطف والطفرات ..", "إن الحركة الإسلامية مدعوة لمواجهة هذه الحرب السافرة على الإسلام واهله بالصياغة الحسنة لشبابها ورجالها، وبالإعداد الكامل ، ثم بالتخطيط الواعي لكل خطوة من خطاها ..", "والحركة الإسلامية في العصر الحديث ينبغي ان تغرس في نفوس عناصرها ودعاتها روح البذل والتضحية ، بأن تضعهم بين الحين والحين امام مسؤوليات ومهات تعودهم على الزمن الجرأة والتضحية والإقدام .. وتستأصل من نفوسهم عوامل الضعف والخوف والانهزام ..", "إن الحركة الإسلامية مدعوة لتضع في تقديرها وحسابها في مجالات التربية والتكوين ثقل المسؤولية وضخامة التبعة التي تنتظرها وتنتظر افرادها. فتسلك بهم كل ما من شأنه ان يعدهم لحياة المجاهدة والمرابطة والكفاح .. وتنأى عما يخلد بهم إلى الأرض ويعودهم حياة الدعة والخنوع .", "إن الإسلام في هذه المرحلة بحاجة إلى العناصر المتحركة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0047.png"}, {"n": 48, "paras": ["الجريئة الناضجة .. اما العناصر الخاملة البليدة فإنها ليست في مستوى المعركة التي يخوضها الإسلام اليوم .. فليتقدم لحمل المسؤوليات اندادها .. وليبرز إلى المعركة اكفاؤها .. وصدق رسول الله ﷺ حيث يقول : « رحم الله امرءاً عرف حده فوقف عنده .. » ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0048.png"}, {"n": 49, "paras": ["المنعطفات الكبرى في حياة الدعاة", "• الزواج - المنعطف الأول", "• الثراء - المنعطف الثاني"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0049.png"}, {"n": 50, "paras": ["على دروب الحياة عقبات كثيرة ومنعطفات خطيرة تعترض سبيل الدعاة إلى الله وتتهدد مصير العاملين للاسلام .. لكن الإعداد السليم والتوجيه القويم ودوام التحذير والتذكير من شأنه ان يكسب الأفراد مناعة تقيهم غوائل الانحراف والتردي ، وتعدهم على الزمن لمواجهة مفاتن الدنيا ومغرياتها . والواقع .. ان اكثر الدعاة في هذا الزمن تنقصهم المناعة النفسية القوية تجاه الإغواء والإغراء .. فالأفكار والمفاهيم تبقى شعارات ونظريات فارغة ما لم تعد اصحابها والمؤمنين بها إعداداً عملياً حسياً يتناسب مع كل ما ينتظرهم في غدهم وفي مستقبل دعوتهم من مفاجآت .. وما لم تتجسد في حياة الدعاة قيم الدعوة ومثلها . ويصبح الإسلام لديهم مقياس كل حكم ، ومفتاح كل قضية ، ومصدر كل تصور فلن يطول بهم الزمن حتى يميل بهم الهوى وتعبث بهم النزوات .. ومما يزيد المشكلة حدة أن دعاة الإسلام يعيشون في ( مجتمع جاهلي ) لا يمت إلى جوهر الدين بصلة .. مجتمع تحلل من كل القيم والمثل .. وتعطلت فيه حواس الخير.. مجتمع ازدحمت فيه عوامل الإفساد ، حتى اصبح التهتك والاباحية عنوان التقدم والتحضر ، وغدا التورع والتدين رمز الرجعية والتأخر .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0050.png"}, {"n": 51, "paras": ["فإذا لم يكن دعاة الإسلام على جانب كبير من عمق العقيدة وسمو الخلق وقوة الإيمان .. وإذا لم يكونوا شديدي المحاسبة لأنفسهم .. دائمي المراقبة لربهم .. متورعين عن الشبهات .. مقبلين على الطاعات . حريصين على النوافل والعبادات، فسيصابون حتماً بلوثات هذا المجتمع . وسينالهم نصيب كبير من شذوذه وانحرافه .", "وفي هذه العجالة سأتناول بالبحث أخطر منعطفين في حياة الدعاة ، وكيف يمكن تجاوزهما بأمان وسلام بإذن الله ..", "المرأة .. المنعطف الأول : تلعب المرأة في حياة الدعاة - بل وفي حياة الناس أجمعين- دوراً بالغ الأثر .. فهي إما أن تكون مصدر نعمة أو مبعث نقمة .", "وفي حياة ( الدعوة ) صور عديدة لكلا الحالتين .. فمن الدعاة من حسن بعد الزواج إسلامهم ، واستقام خطوهم ، وكثر إنتاجهم . ومنهم من تردت بعد الزواج حياتهم ، فساء إسلامهم وفسدت أخلاقهم ثم انطوى ذكرهم عن مسرح الدعوة ووجودها.", "ولا شك أن لكل نتيجة من هذه النتائج أسبابها ومسبباتها، وكما يقول المثل : ( البعرة تدل على البعير ) .. فالذين فشلوا في زواجهم ، هم الذين لم يتقيدوا ( بإسلامية ) الزواج وشرائطه من أول الطريق .. فأعمتهم المظاهر عن الجواهر ، وشغلتهم القشور", "- ٤٩ - الدعوة (٤)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0051.png"}, {"n": 52, "paras": ["عن اللباب .. فوقعوا في شر فعلتهم وندموا، ولكن بعد فوات الأوان . وصيانة للحياة الزوجية من مثل هذه الانتكاسات ، وضع الإسلام القواعد والأسس الكفيلة بتحقيق إسلامية البيت الزوجي وسعادة أفراده وصلاح ذريته . وإليكم أهم هذه القواعد والأسس :", "سلامة القصد : حرص الإسلام على ان يكون القصد الأول من الزواج : استكمال الدين ، مصداقاً لقول الرسول ﷺ : « من رزقه الله امرأة صالحة فقد أعانه على شطر دينه ، فليتق الله الشطر الباقي » (١) وفي رواية للبيهقي قال: قال رسول الله ﷺ : « إذا تزوج العبد استكمل نصف الدين فليتق الله في النصف الباقي». وحرص الإسلام كذلك على ان يكون الزواج عاملاً أساسياً في تحصين النفس وتزكيتها ودفعها في طريق الطاعة والتعفف . فعن عبد الله بن مسعود رضي الله عنه قال: قال رسول الله ﷺ : « يا معشر الشباب .. من استطاع منكم الباءة فليتزوج ، ومن لم يستطع فعليه بالصوم فإنه له وجاء » (٢) . يقول افلاطون : إن الإنسان في قلق دائم، وضجر مستمر،", "(١) رواه الطبراني في الأوسط وقال الحاكم صحيح الإسناد .", "(٢) رواه البخاري ومسلم ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0052.png"}, {"n": 53, "paras": ["أو ينضم ثانية إلى جزئه المفصول وشطره المعزول .. فإذا انضم أحد الشطرين إلى الآخر بالزواج كان زواجاً مباركاً ميموناً .. وقال الرسول ﷺ : « ثلاثة حق على الله عونهم : المجاهد في سبيل الله ، والمكاتب الذي يريد الأداء ، والناكح الذي يريد العفاف » (١) . وكذلك حرص الاسلام على ان يكون القصد من الزواج: إنشاء البيت المسلم، ليكون ( اللبنة الصالحة ) وحجر الأساس في بناء المجتمع الإسلامي .. والقرآن الكريم يعتبر هذا أمنية غالية من أماني المؤمنين حيث يصفهم بقوله : ﴿ والذين يقولون ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماماً ﴾. اما إذا كانت رغائب (الجنس) مقاصد المتزوجين.. فستصبح الحياة الجنسية لديهم عبادة ، ويصبحون هم بالتالي لها عبيداً ..", "حسن الاختيار : ولقد أكد الإسلام أول ما أكد على حسن اختيار شريكة الحياة ورفيقة العمر . واعتبر حسن الاختيار من عوامل تحقيق ( إسلامية ) الحياة الزوجية ، ومن تباشير الوفاق والأنس بين الزوجين ، فقال الرسول ﷺ : « تخيروا لنطفكم فإن العرق نزاع ، وفي رواية دساس » . ونحن وإن سلمنا بصعوبة وجود ( الفتاة المسلمة ) في حاضرنا", "(١) رواه الترمذي وقال : حديث حسن صحيح ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0053.png"}, {"n": 54, "paras": ["الاجتماعي ، غير أن حسن الاختيار سيحقق الأمثل فالأمثل . وقد لا نعدم وجود القابليات والاستعدادات الطيبة إن عدمنا وجود العناصر النسائية المطلوبة . والإسلام أكد على توفر الخلق والدين كشرط أساسي لحسن الاختيار . وحذر من مغبة السعي وراء الجمال والمال والنسب . وبين أن جمال الخُلُق أبقى من جمال الخَلْق .. وأن غنى النفس أثمن من غنى المال . فقال عليه الصلاة والسلام : « لا تزوجوا النساء لحسنهن فعسى حسنهن أن يرديهن. ولا تزوجوهن لأموالهن فعسى أموالهن أن تطغيهن .. ولكن تزوجوهن على الدين. ولأمة خرماء خرقاء ذات دين أفضل » (١) . وحبذا لو يتوفر في المرأة جمال القلب والقالب . فهي عندئذ خير النساء لقول الرسول ﷺ : « خير نسائكم من إذا نظر إليها زوجها سرته . وإذا أمرها أطاعته . وإذا غاب عنها حفظته في نفسه وماله » (٢) . فليحذر الإخوة الذين يفتشون عن الأشكال قبل الخصال . وعن الأموال دون الخلال .. ليمتثلوا أوامر الإسلام، وليكافحوا رغائب الشيطان في نفوسهم ، وليستجيبوا داعي الله فيهم : ﴿ وأنكحوا الأيامى منكم والصالحين من عبادكم وإمائكم إن", "(١) رواه ابن ماجه .", "(٢) أخرجه النسائي من حديث أبي هريرة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0054.png"}, {"n": 55, "paras": ["يكونوا فقراء يغنهم الله من فضله ﴾ . ثم ليعتبروا بقول الرسول ﷺ : « من تزوج امرأة لعزها لم يزده الله إلا ذلاً . ومن تزوجها لمالها لم يزده الله إلا فقراً . ومن تزوجها لحسبها لم يزده الله إلا دناءة . ومن تزوج امرأة لم يرد بها إلا ان يغض بصره ، ويحصن فرجه ، أو يصل رحمه ، بارك الله له فيها وبارك لها فيه » (١) .", "لا تفريط ولا إفراط : وحذر الإسلام كذلك من عاقبة الانسياق وراء الشهوة والإسراف في العلاقات الجنسية . ليحافظ بذلك على شعلة العقول من أن تطفئها رياح الشهوات ، وصيانة للنفوس من أن تستعبدها الغرائز والنزوات . فقال الرسول ﷺ : « النساء حبائل الشيطان ، ولولا الشهوة لما كان للنساء من سلطنة على الرجال » . وصدق إبراهيم بن أدهم حيث يقول : ( من تعودوا أفخاذ النساء لم يجيء منهم شيء ) أي لا يرجى منهم الخير .. ويكفي ان يعرف الأزواج مدى ما يسببه العمل الجنسي من اختلال عميق في كافة وظائف الجسم حتى يعدلوا عن الإسراف ويحرصوا على التوسط والاقتصاد . يقول الدكتور (ج. مايلان): إن نبضات القلب تتسارع حتى تكاد تبلغ ١٥٠ نبضة في الدقيقة الواحدة . والضغط الشرياني يسجل هو الآخر ارتفاعاً هائلاً قد يصل إلى الحد الأعلى . أما التنفس فانه يضاعف سرعته هو", "(١) رواه الطبراني في الأوسط ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0055.png"}, {"n": 56, "paras": ["الآخر .. والدورة الدموية الدماغية لا تسلم كذلك من هذا التغيير الطاريء . فالدماغ يتلقى كمية من الدم أكبر ، ويجد نفسه في حالة احتقان شديد . ولنضف إلى ما تقدم ان حدقة العين تتسع . والجلد يفرز العرق واللعاب ، وإفرازات المعدة والهرمونات تزداد غزارة . ويتابع الدكتور (مايلان) حديثه فيقول : ( ينبغي للغريزة الجنسية ان تتخذ صفة مثالية كلما تقدم الإنسان بالعمر . على المرء ان ينصرف في كبره إلى الأعمال الفكرية التي تصرف الذهن عن كل تفكير جنسي ، وهذا ما يثبت صحته رجال انصرفوا إلى الفكر فعاشوا فيما يشبه التبتل . والقابليات الفكرية هي آخر ما يضعف عند الإنسان . فمقدور المرء حتى سن متقدمة جداً ان يظل مستمتعاً بهذه الملذات العقلية المهدئة ) .", "والواقع أن الإسلام نهى عن الإسراف في كل أمر وإن كان حلالاً طيباً. والإفراط في أي شيء مضر. وخير الأمور أوسطها. وعلى سبيل العلم والمعرفة نذكر هنا بأن ( زرادشت ) حدد المدة بين الجماع بتسعة أيام .. وحددها ( سقراط ) بعشرة . أما ( لوثر ) مؤسس المذهب البروتستانتي فقد نصح بمرتين في الأسبوع الواحد ..", "شخصية الزوج هي الأساس : وحذر الإسلام الأزواج من التمادي في مجاراة المرأة فيما تهوى حفاظاً على شخصية الرجل وقوامته من الانهيار والانحسار. وفي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0056.png"}, {"n": 57, "paras": ["ذلك الخراب كل الخراب للبيت الزوجي ولمن فيه .. ويتحدث الإمام الغزالي عن هذا المعنى في كتاب الاحياء فيقول : (ونفس المرأة على مثال نفسك . إن أرسلت عنانها قليلاً جمحت بك طويلاً . وإن أرخيت عذارها فترأ جذبتك ذراعاً. وإن كبحتها وشددت يدك عليها في محل الشدة ملكتها .. )", "فشخصية الرجل تلعب دوراً كبيراً في الحياة الزوجية . وما لم يكن الرجل في حياة زوجته كل شيء .. تجد فيه المثل الأعلى والقدوة الحسنة ، وتحس منه الحزم والحنان.. فإن عقد الزوجية سيصاب حتماً بالتفكك .", "وقد يعتقد بعض الأزواج أن لا بأس من التساهل في مطلع الحياة الزوجية. فإذا بهم يقعون ضحية جهلهم هذا مدى الحياة. والحق يقال ان الأيام الأولى هي التي ترسم مستقبل البيت الزوجي كله . ومن واجب الأزواج أن يكونوا أكثر تحسباً واحتياطاً في هذه المرحلة من غيرها ..", "على الزوج ألا يتمادى في اتباع هوى زوجته إلى حد يُفسد خلقها ، ويُسقط بالكلية هيبته عندها .. وإنما عليه أن يكون حكيماً يزن الأمور بميزان الإسلام ويضعها في مواضعها . ومما يروى عن الحسن بن علي أنه قال: « والله ما أصبح رجل يطيع امرأته فيما تهوى إلا كبه الله في النار » . وقال عمر بن الخطاب رضي الله عنه : « خالفوا النساء فإن في خلافهن البركة » ، وقال"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0057.png"}, {"n": 58, "paras": ["رسول الله ﷺ : « تعس عبد الزوجة » (١) . وخلاصة القول أن الزواج من أخطر المنعطفات التي تمر في حياة الدعاة .. وخسارة كبرى أن يسقط هؤلاء عند التجربة الأولى .. بل إن من واجبهم أن يقدموا بين يدي إسلامهم ودعوتهم وقائع نموذجية للحياة الموفقة . وهذا من شأنه أن يكسب الحركة الإسلامية والقضية الإسلامية أبرز خصائصها وهي الواقعية .. والحقيقة أن مشكلة الفشل في حياة الدعاة الزوجية ، باتت من المشكلات الرئيسية لكثرة وقوعها وتزايد خطرها ، لأنها لا تفتأ تفقد الدعوة حيناً بعد حين زهرة شبابها وخيرة رجالها . وإذا كانت الدعوة تستنفد عزيز طاقاتها في تكوين أفرادها، فإن من واجبها أن تكون أكثر حرصاً على صيانة إنتاجها من التلف والبوار .. وإن كان المهم أن نبني ، فمن الأهم أن نحافظ على هذا البناء ونصونه من غوائل الأيام ..", "الدنيا .. المنعطف الثاني : قلنا فيما تقدم ان حياة الدعاة حافلة بشتى العقبات مليئة بعديد المشكلات .. وما لم تكن الاستعدادات الوقائية لدى الدعاة في مستوى يجعلهم قادرين على تخطي مختلف الظروف بسلام وأمان ، فان العاقبة قد تكون غير مرضية ومفجعة ..", "(١) رواه البخاري من حديث أبي هريرة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0058.png"}, {"n": 59, "paras": ["ومن عظمة هذا الدين أن نظرته أحاطت بكل الظروف التي يمر بها الانسان، وتتعرض لها النفس البشرية فبينت أسبابها وعالجت مسبباتها ..", "نظرة الاسلام للدنيا : فالاسلام اعتبر الدنيا مركز التجارب والفحوص البشرية . فدعا الناس لعمارتها والانتفاع بخيراتها وثمراتها ، ولكن من غير تفريط ولا إفراط .. فهو من جانب حض على العمل فيها والكسب منها ، ومن جانب آخر حذر من أن تصبح غاية ما ترقى اليه النفس ، ونهاية ما تدركه الآمال . فقرر أن الدنيا دار فانية ستمضي فيها البشرية ما قدر لها من عمر ، ثم تتركها إلى الآخرة حيث السعادة والهناء أو التعاسة والشقاء . وجاءت النذر القرآنية تقول : ﴿ يا قوم إنما هذه الحياة الدنيا متاع. وإن الآخرة هي دار القرار ﴾ فلا تغرنكم الحياة الدنيا ولا يغرنكم بالله الغرور ﴾ .", "عوامل الانحراف : وظني أن عوامل الانحراف في حياة الدعاة لا تتعدى سببين رئيسيين : أولهما : افتقار الدعوة إلى الأجواء الإسلامية النظيفة التي تساعدها"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0059.png"}, {"n": 60, "paras": ["على صياغة أفرادها صياغة قويمة متينة بعيدة عن المؤثرات الخارجية والأجواء المفروضة .", "وثانيهما : إهمال الحركة الإسلامية للمناهج التطبيقية في التكوين .. مما جعل الدراسات الإسلامية نظرية في أكثر الأحيان وجعل القصد منها لا يتعدى الثقافة والمتعة والاطلاع . فكثيراً ما كنا نجد في حياة الدعوة خطباء مفوهين، ودعاة لامعين وهم أحرص الناس على حياة . يا واعظ الناس قد أصبحت متهماً إذ عبت منهم أموراً أنت تأتيها أصبحت تنصحهم بالوعظ مجتهداً والموبقات لعمري أنت جانيها تعيب دنيا وناساً راغبين لها وأنت أكثر الناس رغبة فيها وقد نرى أفراداً مخلصين وإخواناً مندفعين لا تكاد أيديهم تصل إلى شيء من متاع الحياة حتى يخروا صاغرين .. وكثيرون هم الذين حلقوا في آفاق الدعوة، وبلغوا منازل القيادة، ثم سقطوا إلى الأرض صرعى المغريات والمفاتن، ورضوا بالحياة الدنيا من الآخرة .. ﴿فأما من طغى وآثر الحياة الدنيا فإن الجحيم هي المأوى . وأما من خاف مقام ربه ونهى النفس عن الهوى فإن الجنة هي المأوى﴾ ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0060.png"}, {"n": 61, "paras": ["نهج الإسلام في التكوين : ولقد نهج الإسلام في تكوين الشخصية الإنسانية طريقين ليصل بها إلى ذروة الكمال البشري .. فهو لامس أول ما لامس مكامن الحس والشعور والتصور والتفكير عند الإنسان.. لتلفته إلى حقائق الأمور وجواهر الأشياء وليكون تعلقه بها وسعيه دائماً وأبداً وراءها ..", "أولاً : بين له مقام الدنيا من الآخرة، ومدى صغارها وتفاهتها عند الله . حفاظاً عليه من فتنتها وغوايتها: ﴿ قل متاع الدنيا قليل والآخرة خير لمن اتقى ﴾. ومن لفتات الرسول ﷺ إلى حقيقة الدنيا، أنه مر وأصحابه يوماً بشاة ميتة فقال لهم : « أرأيتم هذه هانت على أهلها ؟ قالوا : ومن هوانها ألقوها يا رسول الله . وقال : للدنيا أهون على الله من هذه على أهلها(١) » . وقال أبو هريرة رضي الله عنه : قال رسول الله ﷺ : « يا أبا هريرة ألا أريك الدنيا جميعها بما فيها؟ فقلت بلى يا رسول الله. فأخذ بيدي وأتى بي وادياً من أودية المدينة ، فإذا مزبلة فيها رؤوس الناس وعذراتهم وخرقهم وعظامهم . ثم قال: يا أبا هريرة هذه الرؤوس كانت تحرص كحرصكم ، وتأمل كأملكم ، ثم هي اليوم عظام بلا جلد ، ثم هي صائرة رماداً .. وهذه العذرات هي", "(١) رواه أحمد بإسناد لا بأس به ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0061.png"}, {"n": 62, "paras": ["ألوان أطعمتهم اكتسبوها ثم قذفوها في بطونهم فأصبحت والناس يتحاشونها. وهذه الخرق البالية كانت رياشهم ولباسهم فأصبحت والرياح تصفقها . وهذه العظام عظام دوابهم التي كانوا ينتجعون عليها أطراف البلاد . فمن كان باكياً على الدنيا فليبك .. قال : فما برحنا حتى اشتد بكاؤنا ) . ثانياً : حذر الإسلام من أن تصبح الدنيا مبلغ التنافس بين الناس، فقال الرسول ﷺ : « والله ما الفقر أخشى عليكم، ولكني أخشى ان تبسط الدنيا عليكم كما بسطت على من كان قبلكم فتنافسوها كما تنافسوها ، فتهلككم كما أهلكتهم (١) » . ولقد بين الرسول ﷺ أن الحرص على الدنيا يورث الطمع فيها والانشغال بها وتكريس الحياة لها ، فقال : « من أصبح والدنيا أكبر همه فليس من الله في شيء ، وألزم الله قلبه اربع خصال : هماً لا ينقطع عنه ابداً .. وشغلا لا يتفرغ منه ابداً .. وفقراً لا يبلغ غناه ابداً .. وأملاً لا يبلغ منتهاه ابداً (٢) » . . ثالثاً : وحذر الإسلام من ان يطغى حب الدنيا على القلوب فيشغلها عن التزود لآخرتها . فحض على الزهد بها وتخليص النفس من اسرها ، فقال ﷺ : « من احب الدنيا وسر بها ذهب خوف الآخرة من قلبه » ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0062.png"}, {"n": 63, "paras": ["وفلسفة الزهد في الإسلام لا تحول بين المرء وبين السعي والعمل والإنتاج وعمارة الدنيا كما يفهم بعض الناس . وإنما غايتها صيانة النفس من عبودية الحياة مع صريح الدعوة إلى السعي والعمل . ولقد سئل الرسول ﷺ عن حقيقة الزهد فقال : « اما انه ما هو بتحريم الحلال ولا اضاعة المال، ولكن الزهد في الدنيا ان تكون بما في يد الله اغنى منك بما في يدك » . وسئل الامام احمد بن حنبل ، هل يكون المرء زاهداً ومعه الف دينار . قال : نعم . قيل وما آية ذلك . قال : آيته انه إذا زادت لا يفرح وإذا نقصت لا يحزن .. والدعاة اليوم في خطر شديد من ان تستدرجهم دنياهم وتنحط بهم شهواتهم ، فيبدأون بالصغائر ثم يقعون في الكبائر .. وهذه الدنيا التي اخذت زخرفها وازينت واكتملت مفاتنها وتعددت، لا ينبغي التساهل معها والخلود اليها، فمن تساهل فيها قرضت إيمانه وافسدت اسلامه ، وصدق محمد بن عبد الله ﷺ حيث يقول محذراً : « لتأتينكم بعدي دنيا تأكل ايمانكم كما تأكل النار الحطب » . فليتق الدعاة صواعق السماء ونذر العذاب، وهم يخوضون الغمرات ويواجهون المنعطفات . « اولئك الذين اشتروا الحياة الدنيا بالآخرة فلا يخفف عنهم العذاب ولا هم ينصرون » .", "رابعاً : حض الاسلام على ان يكون الهدف من عمارة الدنيا والعمل"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0063.png"}, {"n": 64, "paras": ["فيها واستخراج كنوزها واكتشاف مجهولها وتسخير أفلاكها ، إقامة الخير وتحقيق العدل واتباع الحق، وليس في ميزان الإسلام فضل لمن ضل هذا الطريق بالغ ما بلغ من العلم والمعرفة والقوة ، لأنه سيكون سبباً في خراب الدنيا ودمارها . واللفتة القرآنية تلامس صميم هذا المعنى حيث تقول : ﴿ من كان يريد الحياة الدنيا وزينتها نوف إليهم أعمالهم فيها وهم فيها لا يبخسون ، أولئك الذين ليس لهم في الآخرة إلا النار وحبط ما صنعوا فيها وباطل ما كانوا يعملون ﴾ .", "التربية العملية في الاسلام : والإسلام لم يكتف بصياغة النظريات في تكوين الأفراد ، وإنما سلك بهؤلاء السبيل التطبيقي العملي ، والمناهج التربوية التجريبية . ومن يراقب عن كثب نماذج التكوين التطبيقي في عهد النبوة، سيقف على كثير من اللفتات والطرائق العملية في التكوين والتربية ، فالرسول ﷺ لم يكتف من المسلمين بما أصابوه في دار الأرقم من فقه وتوجيه، وإنما خرج إلى المجتمع الجاهلي يتحدى بهم أفكار الناس ومعتقداتهم ، ويخوض مع الجاهلية حرباً سافرة هدفها الأول والأخير : إعلان العبودية لله في الأرض، والخضوع لسلطانه والانقياد لأمره . ولقد هانت الدنيا في أعين أولئك .. فكانت بكل ما فيها من مغريات ومفاتن لا ترقى إلى مواطىء أقدامهم . حق وصفهم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0064.png"}, {"n": 65, "paras": ["أعداؤهم : بأنهم قوم الموت أحب إلى أحدهم من الحياة، والتواضع أحب إلى أحدهم من الرفعة ، ليس لأحد منهم في الدنيا رغبة ولا نهمة ، إنما جلوسهم على التراب وأكلهم على ركبهم .. كان مصعب بن عمير وحيد أمه صاحبة الثراء والجاه .. وكانت كل فتاة في مكة تتمناه زوجاً لها ورفيقاً لعمرها .. وعندما أسلم هددته أمه بحرمانه من ثروتها ، فلم يبال . ثم أقسمت أن لا تذوق طعاماً قط حتى يترك الإسلام . فلم يزد أن قال بكل إيمان وتصميم : « والله يا أماه لو كانت لك مائة نفس خرجت نفساً نفساً ما تركت دين محمد » . ولقد حدث الذين كانوا يعرفونه في جاهليته أنهم شاهدوه بعد الإسلام يسير في طريق مكة وليس عليه إلا أثمال بالية لا تكاد تستر جسده . وكانت الهجرة حلقة أخرى من حلقات التكوين العملي في المسلمين ، دعوا فيها إلى التخلي عن كل ما يملكون ، وترك البلد الذي فيه يعيشون ، وفي هذا ما فيه من تعطل الأعمال وبوار التجارة ومفارقة الأهل والعشيرة .. ولقد استجاب المؤمنون لنداء الهجرة وأهدروا في سبيل الإسلام كل مصالحهم وضحوا بأعز ما لديهم .. ويروى أن صهيباً الرومي حين خرج مهاجراً ، تصدى له كفار قريش في الطريق وقالوا له : لقد أتيتنا صعلوكاً حقيراً فكثر مالك عندنا وبلغت الذي بلغت ، ثم تريد أن تخرج بمالك ونفسك . والله ما يكون ذلك .. فقال لهم صهيب : أرأيتم إن جعلت لكم مالي أتخلون سبيلي ؟ قالوا : نعم . فقال : فإني"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0065.png"}, {"n": 66, "paras": ["جعلت لكم مالي .. ولما بلغ ذلك رسول الله قال: « ربح صهيب ربح صهيب » . هكذا تجسدت مبادىء الإسلام في حياة الدعاة .. كان سلوكهم اليومي وتصرفهم الخاص والعام واقعاً حركياً للنظرية الإسلامية . وهذا ما مكنهم من مجاوزة جميع المنعطفات ومواجهة كل العقبات بنجاح . والحركة الإسلامية في هذا الزمن بأمس الحاجة إلى ان تجتاز بدعاتها مناهج عملية تطبيقية، من شأنها ان تستخلص من نفوسهم عوامل الضعف والوهن ، وتعدهم لمواجهة مختلف الاحتمالات والفرص .. ﴿ والذين جاهدوا فينا لنهدينهم سبلنا وإن الله لمع المحسنين .. ﴾ ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0066.png"}, {"n": 67, "paras": ["الداعية بين الفهم والتطبيق", ". الفهم الصحيح . التفاعل والتطبيق . علم وعمل . بين السر والعلانية", "الدعوة (٥)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0067.png"}, {"n": 68, "paras": ["في رأيي أن مسؤولية الدعاة تجاه أنفسهم أضخم بكثير من مسؤولياتهم تجاه المجتمع .. وخطورة التقصير فيما للدعاة على أنفسهم من واجبات يفوق خطورة التقصير فيما للمجتمع من حقوق .. فالدعاة ينبغي أن يكونوا قدوة حسنة للمجتمع الذي يعيشون فيه . تبدو في حياتهم آثار الرسالة التي يدعون الناس إليها .. وترتسم في خطاهم ملامح المبادىء التي يحملونها.. وبذلك يحس كل من حولهم ويشعر بالوجود الحركي لهذا الدين وبالتحرك العضوي له . وفي هذا ما فيه من أثر بالغ في مجالات الدعوة والتبليغ . ولقد صفع القرآن الكريم أولئك الذين يعظون الناس ولا يتعظون ، وينهونهم ولا ينتهون فقال تعالى : ﴿ أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتاب أفلا تعقلون ﴾ ﴿ يا أيها الذين آمنوا لم تقولون ما لا تفعلون ، كبر مقتاً عند الله أن تقولوا ما لا تفعلون ﴾ . ومن هنا كان على الداعية أن يبدأ بنفسه أولاً ..", "الفهم الصحيح : يبدأ بفهم الإسلام ، فهماً صحيحاً عميقاً.. من أصوله ومنابعه"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0068.png"}, {"n": 69, "paras": ["الأولى .. من القرآن الكريم والسنة المطهرة ومن السيرة النبوية المطهرة .. ثم مما تذخر به المكتبة الإسلامية الحديثة من مؤلفات قيمة ثمينة ، حتى يتكون لديه تصور صحيح عن هذا الدين . عن أحكامه وتشريعاته .. عن خصائصه وميزاته .. عن عقائده وعباداته .. وعن أهدافه وغاياته في النفس والمجتمع والدولة .. وعلى الداعية أن يكون مطلعاً على حياة النبوة والأنبياء ، من خلال المواقف والأحداث، والصبر والثبات ، والبذل والجهاد .. من خلال السلوك والمعاملة والخلق والعبادة .", "وأن يوجه اهتمامه بصورة خاصة إلى القرآن : ربيع قلبه ، ونور بصيرته ، ومنهج حياته .. وأن يكون تلقيه لآيات الله الله وتأثره بها كمن يهبط عليه الوحي لأول مرة .. فيدرك أنه المقصود بكل خطاب .. وأنه المعني في كل أمر .. وهذا ما يحقق التفاعل معه والتأثر به والاندماج في أجوائه والإفادة منه .", "وإنما تستوي قلوب الدعاة وتثبت أقدامهم وتستقيم حياتهم بقدر ما يتسع اطلاعهم على هذا القرآن ويعمق فهمهم له .. وبقدر تفاعلهم مع الدين وتأثرهم به . وصدق رسول الله ﷺ حيث يقول : «من يرد الله به خيراً يفقهه في الدين » وقوله ﷺ : « الناس معادن ، خيارهم في الجاهلية خيارهم في الإسلام إن فقهوا » .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0069.png"}, {"n": 70, "paras": ["والنفوس من الإسلام كالتربة من المطر .. منها ما تنتفع به وتنفع .. ومنها ما تنتفع به ولا تنفع .. ولقد ضرب الرسول ﷺ في ذلك مثلاً : « مثل ما بعثني الله به من الهدى والعلم ، كمثل الغيث الكثير أصاب أرضاً ، فكان منها ( نقية ) قبلت الماء فأنبتت الكلأ والعشب الكثير .. وكانت منها ( أجادب ) أمسكت الماء ، فنفع الله بها الناس فشربوا وسقوا وزرعوا.. وأصاب منها طائفة أخرى ، إنما هي ( قيعان ) لا تمسك ماء ولا تنبت كلأ .. فذلك مثل من فقه في دين الله ونفعه ما بعثني به فعلم وعلم .. ومثل من لم يرفع بذلك رأساً ، ولم يقبل هدى الله الذي أرسلت به .. » .", "وحري بالدعاة أن يبادروا إلى تعلم الإسلام شباباً مبكرين، قبل أن تمتصهم المشاغل وتضيق بهم الأوقات.. ورضي الله عن المهلب حيث يوصي أولاده فيقول : « تعلموا قبل أن تسودوا حتى لا تشغلكم السيادة عن العلم .. » .", "التفاعل والتطبيق :", "وإذا كان الدعاة بحاجة إلى الفهم السليم عن الإسلام والتصور الكامل له فهم إلى التفاعل معه أحوج . انهم بحاجة إلى التطبيق العملي لمبادئه وأفكاره وسلوكه ، لتكون حياتهم ترجماناً مبيداً لمنطوق الإسلام ، وصورة كريمة لمعطياته .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0070.png"}, {"n": 71, "paras": ["إن على الدعاة أن يترسموا خطى الدعوة في كل شأن من شؤونهم .. في أقوالهم وأفعالهم في حياتهم الخاصة والعامة .. في أنفسهم كأفراد وفي بيوتهم كأزواج وآباء ، وفي مجتمعاتهم كعمال أو أرباب عمل أو موظفين .. وهذا ما يؤكد عليه علي بن أبي طالب كرم الله وجهه بقوله : « من نصب نفسه للناس إماماً فليبدأ بتعليم نفسه قبل تعليم غيره . وليكن تهذيبه بسيرته قبل تهذيبه بلسانه ، ومعلم نفسه ومهذبها أحق بالاجلال من معلم الناس ومهذبهم » .", "وهل يجني الذين يقولون ما لا يفعلون .. ويعظون ولا يتعظون ويرشدون ولا يسترشدون إلا سخرية العباد وسخط رب العباد. يخسرون دينهم ودنياهم وذلك هو الخسران المبين . قال الشعبي : ( يطلع يوم القيامة قوم من أهل الجنة على قوم من أهل النار فيقولون لهم : ما أدخلكم النار، وإنما أدخلنا الجنة بفضل تأديبكم وتعليمكم ؟ فيقولون : انا كنا نأمر بالخير ولا نفعله ، وننهي عن الشر ونفعله ) ..", "ومن هنا كان من واجب الدعاة أن يتشددوا بالحساب على أنفسهم ، ويأخذوا ذواتهم بالعزائم ، حتى تستقيم على طاعة الله عز وجل . وروي ان الله تعالى قال لعيسى عليه السلام : « يا ابن مريم عظ نفسك فان اتعظت فعظ الناس والا فاستحي مني»."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0071.png"}, {"n": 72, "paras": ["بين السر والعلانية : وليكن الداعية أحرص على اصلاح سره منه على اصلاح جهره .. وليكن اهتمامه بنظافة باطنه اكثر من اهتمامه بنظافة ظاهره ، وحبذا لو تحقق الاثنان .", "على الداعية ان يكون صريحاً مع نفسه فلا يخادعها ، ومع الناس فلا يرائيهم ولا ينافقهم .. وليسمع كل داعية ما يقوله ابن السماك في هذا المعنى: ( كم من مذكر بالله ناس لله .. وكم من مخوف بالله جريء على الله .. وكم من مقرب إلى الله بعيد عن الله .. وكم من داع إلى الله فار من الله .. وكم من تال لكتاب الله منسلخ عن آيات الله ) .", "فالداعية ينبغي أن يخشى الله لا الناس .. ويخلص له في سره وجهره .. فلا يكون في ظاهره ملاكاً وفي باطنه شيطاناً . وليحذر أن يكون ممن عنهم الله بقوله : ﴿ يستخفون من الناس ولا يستخفون من الله وهو معهم﴾ وليعلم أن الله قريب منه مطلع عليه يعرف سره ونجواه : ﴿ ما يكون من نجوى ثلاثة إلا هو رابعهم ؛ ولا خمسة إلا هو سادسهم ، ولا أدنى من ذلك ولا أكثر إلا هو معهم أينما كانوا ، ثم ينبئهم بما عملوا يوم القيامة ، ان الله بكل شيء عليم ﴾ .", "ورحم الله رابعة حيث كانت تردد .. إذا ما قال لي ربي أما استحيت تعصيني"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0072.png"}, {"n": 73, "paras": ["وتخفي الذنب من خلقي وبالعصيان تأتيني فما قولي له لما يحاسبني ويقصيني وصفوة القول في هذا، أن مسؤولية الدعاة تجاه المجتمع يجب ألا تشغلهم عن مسؤوليتهم تجاه أنفسهم، وانشغالهم باصلاح الناس ينبغي أن لا يصرفهم عن اصلاح حالهم . وواجبهم أن يؤدوا المسؤولية حقها، في أنفسهم وفي مجتمعهم .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0073.png"}, {"n": 74, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0074.png"}, {"n": 75, "paras": ["القيادة بين التوجيه والتنظيم", ". أهمية التنظيم . القيادة مصدر التنظيم . تعريف القيادة . الصفات القيادية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0075.png"}, {"n": 76, "paras": ["في اعتقادي أن الدعوة الإسلامية في هذا الزمن تشكو فيما تشكو منه فقراً في التنظيم .. ولا أحسبني مبالغاً إذا قلت أن عناية الحركة الإسلامية في تهيئة دعاة موجهين وخطباء مرشدين يفوق عنايتها في تكوين قادة منظمين . وحتى هذه النسبة الضئيلة في مجالات التكوين التنظيمي فغالباً ما تسوقها الصدف وقلما يأتي بها القصد والتصميم ..", "وحتى المراكز ( القيادية ) في حياة الدعوة فقد بات لا يرشح لها إلا أصحاب الكفايات ( العلمية والتوجيهية ) دونما نظر إلى القدرات التنظيمية .. فلا يكاد يبرع أخ في (الخطابة ) أو ينال آخر ( مؤهلاً علمياً ) حتى يرى نفسه محمولاً لتسلم مسؤولية من المسؤوليات التنظيمية قد لا يكون لها أهلاً . وهذا ما كان يؤدي في غالب الأحيان إلى اخفاقه في كثير من المهمات، وبالتالي إلى خسارة الأخ نفسه بسبب من ردود الفعل النفسية التي تصيبه من جراء فشله المتلاحق .", "والمؤسف أن هذه الحوادث على تتابعها وتكرار وقوعها قليلاً ما كانت تدفع إلى التفكير والعمل على معالجتها ووضع حد لها .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0076.png"}, {"n": 77, "paras": ["أهمية التنظيم : ويمكننا القول بأن (التنظيم) من أقوى عوامل نجاح الحركات. فكم من حركات سياسية وحزبية نجحت بفضل التخطيط الواعي والتنظيم الدقيق ، وأخرى فشلت بسبب الفوضى والارتجال .. وطبيعة الإسلام نفسها تأبى أي شكل من أشكال الفوضى وأي نوع من أنواع الارتجال .. وليس في الدنيا منهج عني بتنظيم دقائق الحياة الإنسانية حتى اليومية والخاصة منها عناية الإسلام. إن الحركة الإسلامية تعاني من ضعف الإمكانيات التنظيمية في اجهزتها المختلفة ، مما يسبب في كثير من الاحيان استنفاد الجهود وضياع الاوقات من غير طائل .. ولذلك كان من اهم موضوعات التنظيم ما يتعلق بالقيادة وخصائصها وصفاتها ..", "ما هي القيادة : فالقيادة - كل قيادة - هي فن معاملة الطبيعة البشرية والتأثير في السلوك البشري وتوجيهه نحو هدف معين وبطريقة تضمن بها طاعته وثقته واحترامه .. ويتوقف نجاح ( القائد ) في مهمته هذه على مدى ما يتصف به من مزايا وخصائص ، علماً بأن هنالك بعض الصفات الفطرية التي قد تساعد على تنمية الامكانيات القيادية ولكن إلى حد معين وبقدر معلوم .. ولا بد من استكمال ( الشخصية القيادية ) من"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0077.png"}, {"n": 78, "paras": ["قدرات اخرى فكرية وروحية وجسمية وتنظيمية واخلاقية وشخصية .. ومركز (القائد) في الحركة - كل حركة - مركز حساس. وما لم تتوفر في شخصيته الصفات القيادية اللازمة فسيبقى المركز القيادي مزعزعاً مضطرباً بالغاً ما بلغ القائد من الثقافة الفكرية او القدرة الخطابية . لأن منطق الحركة غير منطق الكلام .. والدعوة جهاز حركي متكامل لا يمكن ان يتحكم في ضبط حركاته وتقدير خطاه وتوجيه سيره وانفعالاته إلا منطق التنظيم والتخطيط والانضباط ..", "الصفاء النفسي والعبق الروحي : ان من اهم ما ينبغي ان يتمتع به القائد المسلم صفاء النفس وعبق الروح .. وعليه ان يستشعر ثقل الأمانة التي يحملها ، وانه اولى الناس بتأديتها والتفاعل معها .. كما ينبغي ألا تصرفه مسؤولياته القيادية وواجباته العامة مهما كثرت وتضخمت عن الاهتمام بنفسه ، والانشغال بعيوبه ، وتمحيص ذنوبه .. ولا يخدعنه ما يقوم به من اعمال متلاحقات فقد تفقد هذه الأعمال عنصر (الاخلاص ) وتصبح عند الله رماداً تذروه الرياح .. فالله لا يقبل إلا ما زكا وطاب .. وصدق الله العظيم حيث يقول : ﴿ وقدمنا إلى ما عملوا من عمل فجعلناه هباء منثوراً ﴾ . عليه أن يكون دائم المراقبة لله .. دائم التفكير بالموت والقبر والجنة والنار .. حسن العبادة .. كثير التنقل .. محافظاً على"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0078.png"}, {"n": 79, "paras": ["قيام الليل: ﴿ان ناشئة الليل هي أشد وطأ وأقوم قيلا﴾ . الصحة البدنية والقوة الجسدية : وعلى القائد أن لا يهمل شأن صحته وجسمه.. فالمؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وتكاليف الدعوة وأعباء المسؤولية لا يقوى على النهوض بها ضعاف الأجسام سقام الأبدان. إن مركز القيادة مركز التفكير الدائب والعمل المتواصل والجهاد المستمر. وهذه القدرات مرتبطة ارتباطاً عصبياً بمراكزها العضوية من الجسم .. وما لم تكن الأعضاء والحواس والأجهزة كلها بحالة سليمة ونشيطة فستفقد القدرة على امداد الانسان بحاجاته ومتطلباته الحيوية الصحية . القدرات العقلية والأغذية الفكرية : والعقل - كذلك - بحاجة إلى المواد الغذائية التي تحقق نموه ونضجه واتزانه . والأغذية الفكرية بالنسبة للقائد يجب أن تكون منوعة .. فلا يقولن قائل اني اكتفي بالثقافة الإسلامية من دون سائر الثقافات.. وإذا كان هذا المنطق مقبولاً في الماضي فانه مرفوض اليوم، وقد اختلطت الصيحات وتباينت الآراء والمفاهيم وتعددت الثقافات .. وما لم يكن القائد على مستوى حسن من الثقافة والاطلاع ، مواكباً الحياة السياسية واحداثها اليومية ، فقد لا يتمكن من مواجهة المسؤولية ومغالبة التحديات وقيادة الركب قيادة رشيدة واعية ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0079.png"}, {"n": 80, "paras": ["صفات لازمة للقيادة :", "١ - معرفة الدعوة : لمعرفة القائد لدعوته تماماً يلزم أن يكون ملماً إلماماً جيداً بشؤونها الفكرية والتوجيهية والتنظيمية، مواكباً لنشاطها مطلعاً على أعمالها وتصرفاتها . وضمان نجاح القيادة إنما يكون في تلاحمها مع القاعدة وعدم انفصالها عن الموكب المتحرك أو انعزالها في صومعة .. بل ان المسؤولية القيادية تتطلب من صاحبها الاتصال الدائم بالجنود والتعرف على آرائهم ، ومشكلاتهم ، وفي ذلك ما فيه من اطلاع ودراسة تجريبية مفيدة للجانبين .", "٢ - معرفة النفس : ومن واجب القائد أن يعرف مواطن القوة والضعف في نفسه .. والقائد الذي لا يعرف قدراته وامكاناته ، لا يمكن أن يكون قائداً ناجحاً . بل ربما جر على دعوته الكوارث والاضرار .. ولذلك يجب : أ - أن يتعرف إلى نقاط الضعف لديه ويعمل على تقويتها. ب - أن يكتشف مواطن القوة عنده ويسعى لدفعها وتنميتها . ج - أن يحرص على تنمية الثقافة العامة ، والاطلاع على مختلف الموضوعات والآراء والأفكار السياسية والاجتماعية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0080.png"}, {"n": 81, "paras": ["والاقتصادية الخ .. د - ان يعنى بدراسة شخصيات القادة المسلمين وغيرهم، والتعرف على طرق وأساليب قياداتهم ، وأسباب وعوامل نجاحهم أو فشلهم .", "٣ - الرعاية الساهرة : وقيام القائد بملاحظة الأفراد وتعرفه عليهم جيداً، واطلاعه على أحوالهم وأوضاعهم الخاصة والعامة ، ومشاركتهم أفراحهم وأتراحهم ، والعمل على حل مشكلاتهم ، كل هذا مما يساعده على ضبطهم وكسب ثقتهم ، وبالتالي على حسن الاستفادة من طاقاتهم .", "٤ - القدوة الحسنة : والأفراد ينظرون دائماً ويتطلعون إلى قادتهم كأمثلة حسنة يقتدون بها ويحذون حذوها . فسلوك القائد ونشاطه وحيويته وأخلاقه وأقواله وأعماله ذات أثر فعلي على الجماعة بأكملها فالرسول ﷺ كان نعم القدوة لصحابته : ﴿ لقد كان لكم في رسول الله اسوة حسنة﴾ وصحابته رضوان الله عليهم كانوا أئمة صالحين وهداة مهتدين وصفهم رسول الله ﷺ بقوله : « صحابتي كالنجوم بأيهم اقتديتم اهتديتم » .", "٥ - النظر الثاقب : وقدرة القائد على إحراء تقدير سريع وسليم لأي موقف ،"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0081.png"}, {"n": 82, "paras": ["والوصول إلى قرار حاسم في شق الأحوال والظروف ، من شأنه أن يكسبه ثقة الأفراد وتقديرهم . أما التردد والغموض والحيرة والارتباك فمن شأنه أن يخلق الفوضى ويضعف الثقة ويفقد الانضباط .. وصدق رسول الله ﷺ حيث يقول: «ان الله يحب البصر الناقد عند ورود الشبهات والعقل الكامل عند هجوم الشهوات » .", "٦ - الارادة القوية : وقوة الارادة ركن من أركان الشخصية القيادية بها تذلل الصعاب وبها تحل المشكلات ، وبها تجتاز العقبات .. وقادة الاسلام أحوج ما يكونون في هذا العصر إلى إرادات فولاذية تهزأ بالمحن والخطوب ..", "٧ - الجاذبية الفطرية : وهي صفة طبيعية إن وجدت في القائد استطاع أن يجذب القلوب بدون تكلف .. وهذا العنصر من أقوى العناصر التي تتكون منها الشخصية القيادية .", "٨ - التفاؤل : ويعتبر التفاؤل من الأمور الجوهرية اللازمة للشخصية القيادية. ولذا يجدر بالقائد أن يكون دائماً في تفاؤل ، متطلعاً أبداً بأمل وانشراح . دون أن يصرفه ذلك عن التحسب قد لما تخبئه الأيام من مفاجآت ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0082.png"}, {"n": 83, "paras": ["إن اليأس عامل خطير من عوامل الانهيار والدمار في حياة الأفراد والجماعات.. ولا يجوز أن يسمى (اليأس) حكمة (والأمل) خفة وتهوراً.. كما لا يجوز أن يخضع الأمل لجوامح العاطفة وطفراتها، وانما ينبغي أن يتلازم مع العقل والتقدير. والقيادة - طليعة الركب - ورأس القافلة - وتأثيرها على الصف بليغ وعميق.. فان هي تخاذلت ويئست عرضت الصف للتخاذل واليأس، وان هي صمدت أمام الملمات وثبتت في وجه التحديات أشاعت في نفوس الأفراد والجنود روح الأمل والاقدام. فكيف - والاسلام اليوم - يخوض معركة مصير في الداخل والخارج وعلى كافة المستويات ومختلف الجبهات.. فلا يجوز بحال الفرار من الزحف والتولي عنه، وانما ينبغي الصمود والاصرار، الصمود في المعركة، والاصرار على مجاهدة الباطل بكل مقومات الجهاد : ( حق لا تكون فتنة ويكون الدين كله لله ) . ومواقف النبوة الخالدة مراكز ثقل في ماضينا الإسلامي، ومواطن تأس واعتبار في حاضرنا الحركي، يجب الوقوف عندها طويلا.. لقد واجه الرسول ﷺ في دعوته حملات منظمة من الاضطهاد والأذى والتشكيك.. استعمل فيها الحاقدون على الإسلام أضرى أنواع الأذى والتنكيل.. كل ذلك من غير أن تلين للرسول ﷺ وصحبه قناة.. بل ان النبي القائد ليرى بعين ( الأمل) نصر الله وهو يواجه حشود الأعداء تضرب حصارها حول المدينة تتربص بالاسلام والمسلمين. فيحملها بشرى وطمأنينة للمؤمنين بين يدي الدعوة (٦) - ٨١ -"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0083.png"}, {"n": 84, "paras": ["هذا الموقف الرهيب ، حق ليقول ( المنافقون ) والذين في قلوبهم مرض : ( يعدنا محمد كنوز كسرى وقيصر وأحدنا لا يستطيع التبرز من شدة الخوف ) .. أما المؤمنون الواثقون بنصر الله ، فقد كان لهم موقف آخر حكاه القرآن الكريم بكل اعتزاز وتقدير : ( ولما رأى المؤمنون الاحزاب قالوا : هذا ما وعدنا الله ورسوله . وصدق الله ورسوله . وما زادهم إلا إيماناً وتسليماً . من المؤمنين رجال صدقوا ما عاهدوا الله عليه ، فمنهم من قضى نحبه ومنهم من ينتظر ، وما بدلوا تبديلاً .. ) إن الاسلام وهو يواجه اليوم التحدي العارم .. تحدي الشعوبية باسم القومية .. وتحدي الطائفية باسم الوطنية .. وتحدي الالحاد باسم الاشتراكية والعدالة الاجتماعية .. وتحدي الاستعمار باسم العلم والمدنية .. إن الاسلام في موقفه العصيب هذا يجب أن يستنفر الهمم ويستقطب الجهود ويبعث على الثقة والأمل : ( وما النصر إلا من عند الله ) ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0084.png"}, {"n": 85, "paras": ["العلاقة التنظيمية بين الدعوة والداعية", "١ - الطاعة", "• لمن تكون الطاعة ؟", "• متى يجب العصيان ؟", "• عودوا أنفسكم الطاعة .", "٢ - المسؤولية", "• الشعور الذاتي بالمسؤولية .", "• التكليف الحركي ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0085.png"}, {"n": 86, "paras": ["إذا كانت الحركة الإسلامية في العصر الحديث قد أعطت الجوانب الفكرية والتوجيهية والروحية قسطاً وافراً من عنايتها واهتمامها .. فإن الجانب ( التنظيمي ) لم يحظ منها إلا بالقليل من الملاحظة والاهتمام ، بالرغم من أنه بمثابة العمود الفقري فيها .", "وإذا كانت هنالك من أسباب يعود اليها فضل تماسك الدعوة وتلاحمها في غيبة ( الارتباط التنظيمي المحكم ) فإنما يعود إلى ( العقيدة ) أولا ثم إلى (الاخوة) التي لا تزال حق اليوم الآصرة الوحيدة التي تشد المؤمنين إلى بعضهم وتربطهم بدعوتهم ..", "وليس المقصود بضرورة اقامة علاقات تنظيمية بين الدعوة والداعية الاستغناء بالتالي عن الروابط ( العقيدية والاخوية) وانما ينبغي أن تكون لكل علاقة حدود لا تتعداها ، وإلا اختل توازن كل شيء، وتعرضت الحركة لكثير من الأزمات والتناقضات والفوضى في كل جهاز من أجهزتها ، بل وفي كل خطوة من خطواتها .. ن العلاقة بين الدعوة والداعية ينبغي أن تكون واضحة من أول يوم .. يعرف الفرد فيها واجباته .. علاقته بالدعوة .. دوره في الحركة .. مسؤوليته في العمل .. وما شابه ذلك من أمور تحدد شكل ارتباطه ومتطلباته وخصائصه .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0086.png"}, {"n": 87, "paras": ["وسأعرض هنا لبعض القواعد الأساسية التي ينبغي أن تقوم عليها العلاقات التنظيمية بين الدعوة والداعية ..", "١ - الطاعة :", "إن الطاعة من العوامل الأساسية التي تحتاجها العلاقات التنظيمية في كل حركة من الحركات .. والحركة - كل حركة - لا يمكن أن تبلغ المستوى التنظيمي المطلوب ما لم يكن عنصر الطاعة قد بلغ لديها ذروة القوة والكمال ..", "ومفهوم الطاعة في الإسلام يستمد من أصول الدين العقيدية والتشريعية قوته ومداه .. فطاعة الأخ المسلم للقيادة يؤكد امتثاله لأمر الله .. ( فالقيادة ) في الإسلام هي السلطة التنفيذية التي تتولى تطبيق أحكام الإسلام .. أو تسعى وتمهد لاستئناف حياة إسلامية تطبق فيها هذه الأحكام - كما هو شأن الحركة الإسلامية في المرحلة الحاضرة - .. وهذا بدون شك أمر من أمور الله . وبذلك تصبح طاعة الأخ المسلم لها من طاعة الله، وعصيانها من عصيان الله .. ولذلك حض القرآن الكريم على ذلك بقوله: ﴿ يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم ﴾ وعبر الرسول ﷺ عن ذلك بقوله : « من أطاعني فقد أطاع الله . ومن عصاني فقد عصى الله . ومن يطع الأمير فقد أطاعني . ومن يعص الأمير فقد عصاني (١) )", "(١) حديث متفق عليه ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0087.png"}, {"n": 88, "paras": ["لمن تكون الطاعة ؟ وعلى الأخ المسلم أن يعد نفسه لامتثال وطاعة ( القيادة ) كائناً من كان القائد، طالما أن قيادته شرعية.. وليس من خصائص الطاعة في الإسلام ان تكون لشخص دون شخص . كما ينبغي ألا تخضع للأهواء والاذواق الشخصية . ويكفي دلالة على هذا قول الرسول ﷺ : « اسمعوا واطيعوا وان استعمل عليكم عبد حبشي كأن رأسه زبيبة (١) ». وهذا خالد بن الوليد رضي الله عنه عندما جاءه كتاب عزله من قيادة الجيش وتولية أبي عبيدة بن الجراح مكانه. امتثل الأمر وقال : « والله لو أمر علي أمير المؤمنين امرأة لسمعت واطعت ».", "متى يجب العصيان ؟ وإذا كان الإسلام قد أوجب على الأخ المسلم طاعة قيادته بالحق . فقد أحله من ذلك في غيره .. بل وأوجب عليه عصيانها. فقال الرسول ﷺ : « على المرء المسلم السمع والطاعة فيما أحب وكره إلا أن يؤمر بمعصية . فإذا أمر بمعصية فلا سمع ولا طاعة (٢) » . وعن علي رضي الله عنه قال : بعث رسول الله ﷺ سرية واستعمل عليها رجلاً من الانصار.. وأمرهم أن يسمعوا ويطيعوا..", "(١) رواه البخاري .", "(٢) حديث متفق عليه ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0088.png"}, {"n": 89, "paras": ["فاغضبوه في شيء .. فقال اجمعوا لي حطبا . فجمعوا له ثم قال: أوقدوا نارا .. فأوقدوا .. ثم قال ، ألم يأمركم رسول الله ﷺ أن تسمعوا لي وتطيعوا ؟ فقالوا : بلى . قال : فادخلوها . فنظر بعضهم إلى بعض وقالوا: انما فررنا إلى رسول الله ﷺ من النار، فكانوا كذلك حتى سكن غضبه . فأطفئت النار. فلما رجعوا. ذكروا ذلك لرسول الله ﷺ فقال : « لو دخلوها ما خرجوا منها ابداً .. وقال : لا طاعة في معصية الله، انما الطاعة في المعروف ».", "عودوا انفسكم الطاعة : وعلى الأخ المسلم أن يعود نفسه ويخضعها لطاعة وامتثال أمر القيادة . وأن لا يدع مجالاً لالقاءات الشيطان ووسوسات الكبر في نفسه . فالنفوس العاتية يتعسر قيادها ويصعب مقادها .. والكبر مرض عضال يقصم الظهور .. وباب إلى النفس يدخل منه الشيطان .. والطاعة والتواضع يأباها المتكبرون وتشق على نفوس المكابرين .", "وهذا (جبلة بن الأيهم ) تأبى عليه نفسه العاتية أن يخضع لحكم عمر أمير المؤمنين رضي الله عنه .. فيترك الإسلام ويتنصر، ويفضل الضلالة على الهدى . قال ابو عمر الشيباني: « لما أسلم جبلة بن الأيهم الغساني، وكان من ملوك آل « جفنة » كتب إلى عمر يستأذنه في القدوم عليه ، فأذن له عمر . فخرج إليه في خمسمائة من اهل بيته . فسر عمر"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0089.png"}, {"n": 90, "paras": ["وأمر الناس باستقباله، فلما انتهى إلى عمر رحب به وألطفه وأدنى مجلسه . ثم اراد عمر الحج فخرج معه جبلة . فبينما هو يطوف بالبيت إذ وطيء أزاره رجل من بني (فزارة ) فانحل . فرفع جبلة يده فهشم انف الفزاري . فاستعدى عليه عمر . فبعث إلى جبلة فأتاه .. فقال : ما هذا ؟ قال : نعم يا أمير المؤمنين. إنه تعمد حل ازاري ولولا حرمة الكعبة لضربت بين عينيه بالسيف . فقال له عمر : قد أقررت . فإما ترضي الرجل وإما أن أقيده منك . قال جبلة : وماذا تصنع بي ؟ قال عمر : آمر بهشم أنفك كما فعلت . قال جبلة وكيف ذاك يا أمير المؤمنين وهو سوقة وأنا ملك؟ قال عمر : إن الإسلام جمعك وإياه .. فلست تفضله بشي إلا بالتقى والعافية . قال جبلة : قد ظننت يا أمير المؤمنين أنني أكون في الإسلام أعز مني في الجاهلية .. قال عمر : دع عنك هذا ، فانك إن لم ترض الرجل اقدته منك .. قال جبلة : إذاً اتنصر : قال عمر : إن تنصرت ضربت عنقك. لأنك قد أسلمت فإن ارتددت قتلتك ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0090.png"}, {"n": 91, "paras": ["فلما رأى جبلة الصدق من عمر قال : أنا أنظر في هذا ليلتي هذه . حتى إذا نام الناس خرج جبلة بخيله ورواحله إلى الشام هارباً ، ومنها إلى القسطنطينية وتنصر (١) .", "٢ - المسؤولية : والمسؤولية في الإسلام ذات شقين اثنين.. مسؤولية (خاصة) تتصل بخاصة النفس وما يترتب حيالها من تبعات وتكاليف فردية .. ومسؤولية (عامة) تتجاوز النفس إلى الناس والمجتمع والعالم وما يترتب عليها كذلك في هذا النطاق من أعباء ومهمات.. وانطلاقاً من هذا التصور لنطاق ( المسؤولية ) وآفاقها نود أن نناقش مع الأخوة الدعاة مسؤولياتهم الكبرى .. مسؤولياتهم الخاصة .. ومسؤولياتهم العامة .. مسؤولياتهم كأفراد . ومسؤوليتهم كجماعة .. وبالتالي مسؤوليتهم الذاتية ومسؤوليتهم الحركية .. فهم أولا ( أمناء ) على أنفسهم ينبغي أن يعدوها على الزمن لتكون في مستوى ما ينتظرها من أعباء : ﴿ ونفس وما سواها فألهمها فجورها وتقواها. قد أفلح من زكاها وقد خاب من دساها﴾ وهم كذلك ( أوصياء ) على هذا المجتمع برسالة الاستخلاف والتكليف التي ائتمنوا عليها : ﴿ وكذلك لتكونوا شهداء على الناس ويكون الرسول عليكم شهيداً ﴾، من بات ولم يهتم بأمر", "(١) الاغاني وفتوح البلدان ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0091.png"}, {"n": 92, "paras": ["المسلمين فليس منهم » . وانها لمسؤوليات ضخمة وكبيرة تنوء بحملها الجبال، وهي لذلك تتطلب كبير الجهد وغالي التضحية ..", "الشعور الذاتي بالمسؤولية : وحتى يبلغ الداعية في إعداده مستوى المعركة التي تواجه الاسلام في الداخل والخارج . ينبغي أن يكون في ( ايمانه ) اثبت من الرواسي وفي ( فهمه ) أعمق من اللجج .. وفي (صبره) أقوى من الشدائد .", "كما ينبغي أن يتولد لديه شعور ( ذاتي ) بمسؤولية العمل للاسلام ، واستعداد كامل لتلبية حاجات هذه المسؤولية من النفس والجهد .. فهو لا ينتظر (التكليف الحركي) لينهض بالاعباء والمسؤوليات .. وانما يتوالد في ( أعماقه ) شعور فطري بالمسؤولية ويجري في عروقه احساس رباني بالتكليف ..", "يشعر بأنه مسؤول عن ( هذا الإسلام ) ولو لم يكن عضواً في جماعة أو جندياً في حركة .. وحسبه أن يكون مسلماً ليتحرك في ذاته الشعور بالواجب تجاه هذا الدين الذي ينتسب اليه .. والحركة الإسلامية في هذه الأيام بمسيس الحاجة إلى العناصر التي تتقد شعوراً وإحساساً بواجباتها الإسلامية .. العناصر التي يغلي فيها الشعور بالمسؤولية غلياناً .. العناصر التي لا يهدأ تفكيرها بهذا الدين وبالعمل له ساعة من ليل أو ساعة من نهار .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0092.png"}, {"n": 93, "paras": ["هكذا كان شعور الرعيل الأول من المسلمين بمسؤولياتهم تجاه الإسلام .. كان شغلهم الشاغل في كل الظروف وفي كل الأحوال .. كان محور حياتهم وتفكيرهم ساعة العسر واليسر .. قال زيد ابن ثابت : بعثني رسول الله ﷺ يوم ( احد ) أطلب سعد ابن الربيع . فقال لي : « ان رأيته فاقرئه مني السلام ، وقل له ، يقول لك رسول الله كيف تجدك ؟ قال : فجعلت أطوف بين القتلى فاتيته وهو بآخر رمق ، وفيه سبعون ضربة ، ما بين طعنة رمح ، وضربة سيف ، ورمية سهم .. فقلت : يا سعد ، إن رسول الله يقرأ عليك السلام ويقول لك أخبرني كيف تجدك ؟ فقال سعد : على رسول السلام . قل له : يا رسول الله ، أجد ريح الجنة.. وقل لقومي الأنصار : لا عذر لكم عند الله إن خلص إلى رسول الله وفيكم عين تطرف .. وفاضت نفسه من وقته » .", "التكليف الحركي : وإذا تجاوزنا نطاق الشعور الذاتي إلى نطاق ( التكليف الحركي ) لأمكننا القول بأن التكليف الحركي لا يصبح ذا أثر فعال في حياة الأخ إذا انعدم فيه الشعور الذاتي .. فالعناصر التي لا يحركها الاحساس الفطري الذاتي والهتاف العلوي الرباني لا يمكن أن يؤثر فيها التكليف الحركي والدفع البشري. واتكال الدعوة على مثل هذا الصنف من الناس من شأنه أن يعرضها باستمرار للانتكاس والارتكاس .. وبالتالي يبدد كثيراً من طاقاتها في الهواء ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0093.png"}, {"n": 94, "paras": ["وإذا كان الشعور الذاتي بمسؤولية الجهاد الإسلامي من خصائص ( الشخصية الإسلامية ) ومن الصفات الأساسية التي ينبغي أن يتحلى بها الأخ الداعية . فان الالتزام الدقيق بالتكليف الحركي", "- كذلك - عنصر أساسي «أصيل في جوهر العلاقات التنظيمية بين الدعوة والداعية» .", "فالداعية - كل داعية - ينبغي أن يكون متكيفاً مع كل ما يناط به من أعمال ، مستعداً لتنفيذ كل ما يكلف به من مهمات ، في حدود الطاعة التي سبق ذكرها .", "وتحضرني في هذا المقام حادثة إن دلت على شيء فانما تدل على مستوى الانضباط التنظيمي الذي وصلت اليه الحركة الإسلامية في عهد النبوة وبالتالي حسن الالتزام بالتكليف الحركي :", "قال جابر بن عبد الله الانصاري: خرجنا مع رسول الله ﷺ في ( غزوة ذات الرقاع ) . فنزل رسول الله منزلا فقال : « من رجل يكلؤنا - يحرسنا - ليلتنا هذه؟) فقام رجل من المهاجرين ورجل من الانصار هما : ( عمار بن ياسر ، وعباد بن بشر ) .. فلما خرجا إلى فم الشعب قال الانصاري للمهاجري : أي الليل تحب أن أكفيكه ؟ أوله أم آخره ؟ قال المهاجري ، بل اكفني أوله . قال : فاضطجع المهاجري فنام . وقام الانصاري يصلي وأتى احد المشركين ، فلما رأى الرجل يصلي رماه بسهم فوقع فيه . فنزعه عباد وثبت قائماً . ثم رماه بسهم آخر فنزعه وثبت قائماً . ثم عاد بالثالث فنزعه ، ثم ركع وسجد ثم أيقظ صاحبه ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0094.png"}, {"n": 95, "paras": ["فقال : اجلس فقد أصبت . قال : فوثب عمار بن ياسر . فلما رآهما المشرك عرف ان قد علما بوجوده فهرب. ولما رأى المهاجري ما بالانصاري من الدماء قال: سبحان الله، أفلا أهببتني أول ما رماك ؟ فقال الأنصاري : « كنت في سورة أقرؤها فلم أحب أن أقطعها حتى أنفذها . فلما تابع علي الرمي ركعت وأيقظتك . وايم والله لولا أن أضيع ثغراً أمرني رسول الله بحفظه لقطع نفسي قبل ان أقطعها أو أنفذها (١)». والداعية - كل داعية - على ثغر من ثغور الإسلام.. وأمام مسؤولية من المسؤوليات. فينبغي أن لا يؤتى من قبله.. ويجدر به أن يصمد في موقفه ذاك حتى يلقى الله وهو على مثل حاله فينال بذلك ثواب المرابطين وأجر المجاهدين . فمن العرباض بن سارية رضي الله عنه ، قال : قال رسول الله صلى الله عليه : « كل عمل ينقطع عن صاحبه إذا مات، إلا المرابط في سبيل الله، فانه ينمي له عمله ، ويجري عليه رزقه إلى يوم القيامة (٢)».", "(١) ابن هشام .", "(٢) رواه الطبراني في الكبير باسنادين ، رواة احدهما ثقات ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0095.png"}, {"n": 96, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0096.png"}, {"n": 97, "paras": ["الطبيعة الحركية", ". ظواهر خطيرة ● . مركز التفاعل ● . كيف يتم التفاعل ● . التلقي للتنفيذ ● . العقل مركز القيادة ●"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0097.png"}, {"n": 98, "paras": ["إن ضعف الطبيعة الحركية لدى الجمهرة الكبرى من دعاة الإسلام ظاهرة شائعة في حياة الدعوة وبالتالي خطيرة على حاضرها ومستقبلها .. فهي تغلق دونها أبواب الانطلاق والتمكين، وتحول بينها وبين الاستفادة من كثير من الظروف والسوانح ، وتطبعها بطابع الرتابة والجمود .. وتفقدها أبرز خصائصها، وهي الحيوية والحركية والانقلابية ..", "وإن مبادىء الإسلام الفكرية والتوجيهية تملك امكانيات التلقيح والتأثير فيما لو حملتها نفوس متوثبة ونهضت بها همم متحركة عالية .", "والمجتمع - نعم هذا المجتمع - الذي كثيراً ما نتهمه بما فيه وبما ليس فيه ، تهرباً من تكاليف العمل والجهاد، وتبريراً لتقصيرنا في مجالات البذل والعطاء ، إلى درجة أننا خدعنا أنفسنا إلى حد بعيد ، وتسرب الشك واليأس إلى نفوس الكثيرين من دعاتنا أو كاد ، وصدق فينا قول القائل : « كاد استماع الوهم يملأ أذني وهماً».. أقول ان هذا المجتمع لا تزال فيه قابليات واستعدادات حسنة للتفاعل مع هذه الدعوة فيما لو تحركت الهمم وتحفزت العزائم .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0098.png"}, {"n": 99, "paras": ["وأنا مع كل هذا لا أنكر أن العمل الإسلامي يواجه في هذا العصر خصومات وتحديات فوق ما يتصور الكثيرون.. ولكنني أنكر أن يؤدي هذا العمل إلى تخاذل أهل الحق والمعركة الفاصلة لم تبدأ بعد ؟ كما أنني أنكر ان يكون هذا باعثاً على الفرار من الميدان في ساعة العسر حيث يلزم الكر دون الفر ، ومواجهة التحدي بتحد أقوى وأشد : ﴿ الذين قال لهم الناس: ان الناس قد جمعوا لكم فاخشوهم، فزادهم إيماناً وقالوا : حسبنا الله ونعم الوكيل ، فانقلبوا بنعمة من الله وفضل ، لم يمسهم سوء ، واتبعوا رضوان الله والله ذو فضل عظيم ﴾..", "وأود أن أشير هنا إلى أن المحن والشدائد يجب أن تبعث في النفوس معاني الاصرار على الحق والثبات دونه .. كما ينبغي أن تدفع إلى مراجعة الاخطاء وتعبئة القوى على ضوء الاستفادة من التجارب والأحداث ..", "ولعل في إصرار نوح عليه السلام على دعوة قومه ، وحرصه على هدايتهم تسعمائة وخمسين عاماً وما لقي خلالها من أذى واضطهاد، من شأنه أن يشحذ الهمم فلا تكل ، ويحفز النفوس فلا تمل: ﴿ حتى إذا استيئس الرسل وظنوا أنهم قد كذبوا جاءهم نصرنا فنجي من نشاء ولا يرد بأسنا عن القوم المجرمين . لقد كان في قصصهم عبرة لأولي الألباب ﴾ .", "إن المعركة التي يخوضها الإسلام في هذا الزمن تتطلب عناصر ذات نمط معين .. عناصر تعيش للإسلام وللإسلام .. عناصر", "الدعوة (٧) - ٩٧ -"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0099.png"}, {"n": 100, "paras": ["ديدنها هذا الدين وهذا الدين وحده . فلنخجلن من أنفسنا.. ولنغارن على الإسلام دين الحق ودعوة الحق ، حين لا نكون من حمله على مستوى المسؤولية في الوقت الذي نرى استماتة أهل الباطل ، وتضحية أهل الضلال ، وبذل الأفاكين في سبيل إفكهم وضلالاتهم : ﴿ أولئك يدعون إلى النار ، والله يدعو إلى الجنة والمغفرة بإذنه ، ويبين آياته للناس لعلهم يتذكرون ﴾ . إن الذين لا تغلي دماؤهم ، وتلتهب نفوسهم ، وتهتز مشاعرهم بالاسلام في كل لحظة من لحظات حياتهم ، لا يمكن أن يعقد عليهم الأمل ، ويناط بهم الرجاء، ويتحقق على أيديهم انتصار الإسلام. ولنقف هنا قليلاً نستخلص بواعث العقم وضآلة الأثمار في حياة الدعاة والعاملين ..", "القلب مركز التفاعل : وفي اعتقادي أن القلب هو مركز الثقل ، الذي يتم فيه تفاعل الداعية مع كل ما يرده من توجيهات وتشريعات .. وحتى الأفكار ، فان للقلب شأن في استساغتها ومشاركة للعقل في تذوقها : ﴿ أفلم يسيروا في الأرض فتكون لهم قلوب يعقلون بها ، أو آذان يسمعون بها ، فانها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور ﴾ . والإيمان هو ثمرة هذا التفاعل . وهو بالتالي وقود الحركة والحيوية والإثمار .. وما لم تستمر عملية التفاعل هذه فإن الحركة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0100.png"}, {"n": 101, "paras": ["والحيوية ستنعدمان تباعاً إلى أن تصاب الطبيعة التنفيذية بالشلل والعقم نهائياً .. ولذلك كان القلب بحاجة إلى عناية فائقة ونصيب من الاهتمام كبير .. وأول خصائص القلب أنه ذو حساسية مرهفة ، فكما أنه قابل للاشراق والضياء والصفاء ، فهو قابل للاظلام والذبول والصدأ .. من هنا كان من واجب الداعية أن يعنى بقلبه فلا يهمله .. والعناية بالقلب يجب ألا تفتر ساعة من ليل أو نهار ، حفاظاً على إشراقه وبهائه ونقائه ، مصداقاً لقول الرسول ﷺ : « إن للقلوب صدأ وجلاؤها الاستغفار » .", "ودعاة الإسلام أولى من سواهم بالاهتمام بقلوبهم ،لأنهم أكثر تعرضاً لمكائد الشيطان ، وقلوبهم أشد حاجة إلى الإشراق وهي جهاز الإرسال ومركز الإشعاع لديهم .. وفي حديث عن عائشة رضي الله عنها قالت .. قال رسول الله ﷺ : « الإنسان عيناه هاد . وأذناه قمع .. ولسانه ترجمان .. ويداه جناحاه.. ورجلاه بريد .. والقلب منه ملك .. فإذا طاب الملك طابت جنوده » .", "والعناية بالقلب ينبغي أن تكون مستمرة دائمة استعداداً لكل طارىء خبيث أو وافد مضل .. لأن الشيطان يسري من ابن آدم مسرى الدماء .. ولا يجلو القلوب كاخلاص العبادة وعلى الاخص ناشئة الليل .. وعمق التبصر والتدبر لآيات الله وخاصة عند الصباح ( إن قرآن الفجر كان مشهوداً ) والبكاء والتبتل في"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0101.png"}, {"n": 102, "paras": ["محراب الله .. ودوام التفكر بالموت والاستعداد له . وصدق رسول الله ﷺ حيث يقول : « لولا أن الشياطين يحومون على قلوب بني آدم لنظروا إلى ملكوت السموات » . والقلوب كذلك عرضة للقسوة واللين .. فالطاعة تكسبها ليناً وارهاقاً ، والمعصية تزيدها قسوة وجفافاً : ﴿ طال عليهم الامد فقست قلوبهم فهي كالحجارة ، أو أشد قسوة ﴾ ﴿ بل ران على قلوبهم ما كادوا يكسبون ﴾ .. ورحم الله ابن المبارك إذ يقول : رأيت الذنوب تميت القلوب وقد يورث الذل إدمانها وترك الذنوب حياة القلوب وخير لنفسك عصيانها ولقد بين لنا الداعية الأول ﷺ كيف يتم تفاعل القلوب مع ما يفد اليها من خير أو شر فقال : « تعرض الفتن على القلوب كالحصير عوداً عوداً .. فأي قلب أشربها نكت فيها نكتة سوداء .. وأي قلب أنكرها نكت فيها نكتة بيضاء . حتى تصير على قلبين : على أبيض مثل الصفاء فلا تضره فتنة ما دامت السموات والأرض . والآخر أسود مرباداً لا يعرف معروفاً ولا ينكر منكرا .. » فعلى الداعية أن يترصد قلبه باستمرار .. يراقب حركاته ويسجل تصرفاته .. ولا يتساهل حتى مع الوسوسة الخافتة والشعور الخفي .. ولا يقولن أنها من التوافه الصغيرة .. فالصغير الحقير إذا كثر واستمر أنذر بخطر كبير .. وصدق رسول الله ﷺ حيث يقول : « إياكم ومحقرات الذنوب ، فانهن يجتمعن"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0102.png"}, {"n": 103, "paras": ["على الرجل حق يهلكنه » وإلى هذا المعنى أشار الشاعر بقوله : لا تحقرن صغيرة إن الجبال من الحصى وقال آخر : لا تحقرن صغيراً في مخاصمة إن البعوضة تدمي مقلة الأسد فقلب الداعية ينبغي أن يكون كالمرآة الصافية تنعكس عليه مبادىء الإسلام . ينفعل بها وتنفعل به .. ليسوقها بعدئذ إلى الأعضاء والجوارح مجموعة رفيعة من الصفات الكريمة والاخلاق الفاضلة . وبذلك لا يبقى الإسلام بالنسبة للداعية مجرد نظريات وانما يأخذ صوره العملية الحسية في حياته وواقعه . وإن مما يساعد الداعية على التفاعل مع الإسلام وقوفه أمام مبادئه وأحكامه وتشريعاته موقف المقصود بالخطاب المعني بالأمر، وهذا من شأنه أن يكسب التلقي فاعلية التأثير المباشر والتفاعل السريع .. وبذلك تصبح علاقة الداعية بالاسلام علاقة جندية وقيادة وأمر وتنفيذ .. والحقيقة أن تلقي الداعية لآيات الله ومبادىء الإسلام على هذا النحو وبهذه الكيفية من شأنه أن يكسب حياته طعماً جديداً يجد حلاوته في كل معنى من معاني الإسلام .. العقل مركز القيادة : وان مما يبعث الداعية - كذلك - على التفاعل مع دعوته وانفعاله بها ، وبالتالي انطلاقه في شتى المجالات والميادين ،"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0103.png"}, {"n": 104, "paras": ["نضوج فكره وعمق فهمه وسعة ثقافته. لأن فاقد الشيء لا يعطيه .. وكثيراً ما يحدث أن يتخاذل ضعفاء الثقافة من أهل الحق أمام المثقفين من أهل الباطل .. وكما أن الإنسان يتفاعل مع القلب فيما يرده من خير أو شر، فالقلب كذلك يتفاعل مع العقل فيما يحمله من مفاهيم وأفكار .. ولفتات القرآن العقلية إلى مشاهد الكون والحياة تؤكد قيمة التفكير والتصور في السلوك الإنساني .. ولذلك أسقط الإسلام الحساب عن المجنون والمعتوه وفاقد العقل .. وعناية الداعية بقلبه دون عقله ستجرده - بدون شك - من أقوى أسلحته وأبعثها على انطلاقه وانفعاله ، كما ان عنايته بعقله دون قلبه ستفقده اهم عوامل الاستقرار والاطمئنان والثبات . وشخصية الداعية لا يمكن أن تبلغ درجة الكمال ما لم يتحقق صلاح القلب والعقل معاً .. وكما ان على الداعية أن يهتم ( بالعبادة والمراقبة وذكر الموت والذكر سواها من الرياضات الروحية ). فان عليه كذلك أن يهتم ( بالتفقه والمطالعة والخطابة والكتابة وغيرها من النشاطات الفكرية ) . والامتلاء الفكري من شأنه أن يجعل الداعية جهاز إرسال لا يتوقف .. أما الذين يحسون بخوائهم الفكري فانهم يتحاشون المجتمعات والناس ويتهربون من المسؤوليات .. وبالتالي تموت فيهم الطبيعة الحركية وينعدم الاثمار والعطاء .. وحاجة الداعية إلى السلاح الفكري في العصر الحديث حاجة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0104.png"}, {"n": 105, "paras": ["ملحة لا يمكن الاستغناء عنها أو اهمالها .. فالاسلام اليوم يعيش في وسط يموج بالاتجاهات والمذاهب الفكرية والفلسفية .. ويجدر بالدعاة أن يكونوا موضوعيين ومنطقيين .. وليس من مصلحة الإسلام في شيء مواجهات التحديات الفكرية بالعواطف الفارغة من الكلام والخطب .. بل ان من الواجب مقارعة الحجة بالحجة ومقارنة الفكر بالفكر: « فأما الزبد فيذهب جفاء وأما ما ينفع الناس فيمكث في الأرض » . وعلى الداعية أن يرجع إلى القرآن الكريم والسيرة النبوية يتحسس فيهما الأساليب العقلية البليغة التي كان يواجه بها الإسلام خصومه الجدليين . وصفوة القول أن الداعية يجب أن يكون في إعداده وتكوينه على مستوى ما تتطلبه الحركة اليوم .. قوة في الروح ، ومتانة في الفكر .. وسمواً في الخلق .. وبذلك يمكن أن يتحقق التفاعل بين الدعوة وبين الناس ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0105.png"}, {"n": 106, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0106.png"}, {"n": 107, "paras": ["شخصية الداعية وَكَيْفَ تُبْنَى؟", "• حصنوا جبهات المقاومة", "• الشخصية الاسلامية", "• العقلية الاسلامية", "• النفسية الاسلامية", "• لا تفريط ولا افراط", "• حقيقة التجرد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0107.png"}, {"n": 108, "paras": ["دعاة الاسلام في خطر ..", "لا أعني أنهم في خطر من عدوهم .. ومن مكائد خصومهم ومن مؤامرات الحاقدين عليهم وعلى الإسلام .. فهذه أخطار قد تهون - على ضراوتها وشدتها - أمام أخطار النفس وانحرافاتها .. فالداعية بخير ما بريء من عيوب نفسه وأمراضها بالغ ما بلغت قوة الأعداء والخصوم . ومن هنا نفهم وصية عمر ابن الخطاب رضي الله عنه للمسلمين حيث يقول : « كونوا أشد احتراساً من المعاصي منكم من عدوكم ، فإن ذنوب الجيش أخوف عليهم من عدوهم . وإنما ينصر المسلمون بمعصية عدوهم الله . واعلموا أن عليكم في سيركم حفظة من الله، فلا تعملوا بساخط الله وأنتم في سبيل الله » .", "أقول هذا لأنني أدرك أن درب الدعاة في هذا العصر درب محفوفة بالإغواء والإغراء .. لقد هدمت جاهلية القرن العشرين كل معنى من معاني الفضيلة والخير والكرامة .. وأسفرت عن وجه كالح شاحب ترتسم فيه وتتوافر أسباب الغواية والفتنة والشذوذ.. وأزكمت مادية هذا العصر الأنوف حق أصبح الإنسان"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0108.png"}, {"n": 109, "paras": ["لا يفكر إلا بها ، ولا يعيش إلا لها ، ولا يحكم على الأشياء إلا من خلالها . أعمت بصره وبصيرته ، وأماتت حسه وشعوره : ﴿ فَمَثَلُهُ كَمَثَلِ الْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ۚ ذَٰلِكَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآيَاتِنَا ﴾ . هذه التركة المثقلة بالأعباء والمهمات كان على دعاة الإسلام ان يواجهوا مسؤولية حملها بالعدة الكاملة من إيمانهم وأخلاقهم وأفكارهم ، وبكل ما يملكون من أسباب القوة والمنعة العقيدية والخلقية .", "حصنوا جبهات المقاومة : لذلك كان أخطر ما يواجه الدعاة في هذا الزمن ، تصدع جبهات المقاومة في نفوسهم ، وتسليمهم أحياناً بما يسمى (بالأمر الواقع ) والرضى بالترقيع في إسلامهم ، والقبول بأنصاف الحلول من مبادئهم وأهدافهم .. وكثيراً ما كانت سياسة التراخي والتساهل هذه تستدرج البعض إلى مخالفة المسلمات الأساسية والخروج عن دائرة التصور والتفكير والسلوك الإسلامي . وإذا سلمنا بضخامة الأعباء وكبر المسؤوليات التي تنتظر الدعاة في حاضرهم ومستقبلهم .. وما هم معرضون له من محن وفتن ، أصبح من أهم ما ينبغي أن يحرصوا عليه ويبادروا إليه هو توفير عوامل ( الصيانة ) لنفوسهم وعقولهم ، ليقووا على مغالبة ما يعترض سبيلهم من عقبات ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0109.png"}, {"n": 110, "paras": ["الشخصية الاسلامية :", "إن الاهتمام بتكوين الشخصية الإسلامية يجب ان يسبق أي عمل آخر .. فالشخصية الإسلامية حجر الزاوية في بناء الحركة الإسلامية . وكما أن الحركة الإسلامية لا يمكن أن تنهض بدورها الكبير في قيادة الأمة بغير الدعاة والعاملين ، كذلك فإن هؤلاء الدعاة لا يمكن أن يقوموا بالدور الخطير ما لم تكتمل شخصيتهم الإسلامية اكتمالاً طبيعياً سليماً .. فلنناقش إذن العناصر التي تتكون منها الشخصية الإسلامية :", "١ - العقلية الاسلامية :", "إن العقلية الإسلامية إحدى مقومات الشخصية الإسلامية .. وهي بالتالي ملكة التفكير والتصور الإسلامي الصحيح للكون والإنسان والحياة ، فالأفكار والأحكام والمحسوسات والمغيبات يجب ان تخضع كلها لتقييم إسلامي صحيح . وبهذا تكون العقلية الإسلامية قاعدة فكرية تعكس مفاهيم الإسلام وأحكامه في كل شأن من الشؤون .", "فالعقلية الإسلامية هي ( العقلية ) التي تنظر إلى الأشياء - كل الأشياء - من خلال الإسلام .. وتحكم على الأمور - كل الأمور - بمنظار الإسلام ، فيكون الإسلام بالنسبة إليها مقياس كل قضية ، وحل كل مشكلة ، وزمام كل أمر .. ولعل أهم الأسباب التي تؤدي بالدعاة إلى الانحراف - أحياناً - اضطراب"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0110.png"}, {"n": 111, "paras": ["فهمهم وتصورهم للإسلام كفكرة ، وللعمل الاسلامي كنهج وأسلوب . ولتكوين العقلية الإسلامية لا بد من توفر العوامل التالية : أولاً : الفهم الصحيح للكتاب والسنة الذي من شأنه أن يقيم في ذهن الداعية الخطوط الأساسية للحياة الإنسانية كما يريدها الإسلام .. ثانياً : الإدراك الكامل لأهداف الفكر الإسلامي من حيث هو ضابط مسلكي وأخلاقي ، دافع للعمل ، جاعل سلوك الإنسان متقيداً ومتكيفاً بحسبه في الحياة الدنيا ونحو الآخرة . وأنه ليس مجرد نظريات ومثاليات مجردة .. وهذا ما يجعل المفهوم الإسلامي واقعياً وإيجابياً ، وذا مفعول عميق وقوي في بناء الشخصية الإسلامية . ثالثاً : الاستيعاب الكامل والكافي لجوانب التصور الإسلامي دونما انحصار في جانب من الجوانب .. فكثيراً ما يؤدي التفريط الجانبي الى ظواهر وانحرافات خطيرة . فالعقل ينمو نمواً طبيعياً ما دام يتناول من الأبحاث والثقافات ما يكفل له غذاء وفيراً ومتنوعاً .. ويقف عن النمو والإنتاج ، بل قد يتأخر ويسف عن التفكير إذا أهمل أو قدم له الضحل الخفيف من القراءات والمطالعات .. يقول الدكتور صبري القباني في كتابه الأول من سلسلة ( طبيبك معك ) : إن الدماغ يستطيب تنوع الأبحاث. فينسجم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0111.png"}, {"n": 112, "paras": ["ويستعيد استساغة الفكر .. والتفكير ذو النمط الواحد يكده ويجهده . مثله في ذلك مثل الأذن تمج النغم الواحد المتواتر .. ومثل عضلات القدم التي يرهقها هبوط المنحدر السحيق ، كما يضنيها صعود المرتقى الطويل .. لذلك يجب ان نقدم لأدمغتنا دراسات منوعة لتحتفظ بجدتها ونشاطها .", "من هنا نلاحظ أن الذين ينصرفون إلى المطالعات ( الروحية أو الأدبية ) فحسب يصابون بالانعزالية والانطوائية .. كذلك الذين يعكفون على البحوث العلمية المجردة ولا يقدمون للعقل أغذيته الأخرى الضرورية قد يقعون فريسة عوارض عصبية ونفسية جامحة .", "وحق يتحقق للعقل اتزانه وعمقه يجب أن ينفتح على كل ما في الحياة من معرفة وعلم وثقافة .. يأخذ منها بقدر .. ويدع منها بقدر وفي حدود ما يستسيغه التصور الإسلامي السليم .. والعقلية الإسلامية لا يمكن أن تكون إسلامية صافية ما لم تطل على العالم من نافذة الإسلام .. تفكر وتقدر، تستحسن وتستقبح، توازن وتقارن، كل ذلك على ضوء الإسلام ووفقي أصوله وقواعده.", "النفسية الاسلامية :", "والنفسية الإسلامية ثاني مقومات ( الشخصية الإسلامية ) ، بل هي الانعكاس الحسي لتفاعل الفكرة الإسلامية وأثرها في حياة الفرد .. فميول الإنسان وغرائزه مربوطة ارتباطاً وثيقاً بمفاهيمه وتصوراته الفكرية .. ومن هنا كانت النفسية الإسلامية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0112.png"}, {"n": 113, "paras": ["هي الكيفية التي يمارس الداعية على ضوئها غرائزه وميوله وحاجاته العضوية .", "وقد يكون من أهم ما تجب العناية به ووضع المناهج له ، تحويل المفاهيم والأفكار الإسلامية إلى سلوك وخلق أي إلى نفسية إسلامية . وهذا ما يفرض إحكام الربط بين العقلية والنفسية أي بين التفكير والتطبيق .. لقد ندد الإسلام بانفصال ( جزئي الشخصية ) عن بعضهما البعض فقال تعالى : ﴿ يا أيها الذين آمنوا لم تقولون ما لا تفعلون ؟ ﴾ .", "وحتى تستقيم النفس على قواعد الإسلام التوجيهية والتشريعية، فلا يطغيها ترخص ، أو يشقيها تكلف .. ينبغي أن يراعي في ترويضها العوامل التالية :", "لا تفريط ولا إفراط : حرص الإسلام من أول يوم على رد النفس البشرية إلى فطرتها.. وفق منهج دقيق متناسق يحفظ للروح والعقل والبدن حقوقهم من غير تفريط ولا إفراط .", "وعلى هذا الأساس ينبغي ان تروض النفس .. فتنشأ نشأة طبيعية . وتنمو نمواً فطرياً لا إسراف فيه ولا إسفاف .. ومثل الذين يسرفون في حقوق أرواحهم كمثل الذين يسرفون في حقوق أبدانهم سواء بسواء .. أولئك لا يمكن أن تستقيم شخصيتهم وتتزن وفق مقاييس الإسلام وأصوله ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0113.png"}, {"n": 114, "paras": ["وقد روي أن رسول الله ﷺ زار عبد الله بن العاص وكانت امرأته تلطف رسول الله ﷺ . فقال : « كيف أنت يا أم عبد الله ؟ قالت : كيف أكون وعبد الله بن عمرو رجل قد تخلى عن الدنيا . قال لها : كيف ذلك ؟ قالت : حرم فلا ينام ، ولا يفطر ولا يطعم اللحم ، ولا يؤدي إلى أهله حقهم . قال : فأين هو ؟ قالت : خرج ويوشك ان يرجع الساعة . قال : فإذا رجع فاحبسيه علي .. فخرج الرسول ﷺ وجاء عبد الله بن عمرو .. وأوشك رسول الله في الرجعة . فقال : يا عبد الله بن عمرو .. ما هذا الذي بلغني عنك ، انك لا تنام ؟ قال : أردت بذلك الأمن من الفزع الأكبر . وقال : بلغني انك لا تفطر . قال : أردت بذلك ما هو خير منه في الجنة . وقال : بلغني أنك لا تؤدي إلى أهلك حقهن. قال : أردت بذلك نساء خيراً منهن .. فقال الرسول ﷺ : يا عبد الله بن عمرو ، إن لك في رسول الله أسوة حسنة . ورسول الله يصوم ويفطر، ويأكل اللحم، ويؤدي إلى أهله حقوقهم . يا عبد الله ، إن لله عليك حقاً ، وإن لبدنك عليك حقاً ، وإن لأهلك عليك حقاً » .", "فالداعية الموفق هو الذي يتابع قلبه بما يصلحه ويزكيه وينقيه ، ولا يغفل عن مراقبة نفسه ولا يقصر في محاسبتها .. عملاً بقول المصطفى ﷺ : « الكيس من دان نفسه وعمل لما بعد الموت، والعاجز من أتبع نفسه هواها وتمنى على الله الأماني». وإلى ذلك أشار عمر بن الخطاب رضي الله عنه بقوله : (حاسبوا"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0114.png"}, {"n": 115, "paras": ["أنفسكم قبل أن تحاسبوا . وزنوها قبل أن توزنوا ، وتهيأوا للعرض الأكبر ) . وهو إلى جانب ذلك لا يبخل على بدنه بما أحل له من طيبات المأكل والمشرب والملبس . حسبه في ذلك قول الله تعالى: ﴿ قل من حرم زينة الله التي أخرج لعباده والطيبات من الرزق﴾. ﴿قل إنما حرم ربي الفواحش ما ظهر منها وما بطن والإثم والبغي بغير الحق ﴾ .", "صحيح أن النفس أمارة بالسوء .. وأنها بحاجة إلى ترويض وإحجام حتى يسلس قيادها ويسهل مقادها . ولكن كما أن لنا عليها واجبات ، فإن لها علينا حقوقاً .. ومن طالبها بواجباتها سألته حقوقها ، ومن حرمها حقها جمحت به وأردته .. وهذا ما ينطق به مدلول الآية الكريمة : ﴿ لا يكلف الله نفساً إلا وسعها لها ما كسبت وعليها ما اكتسبت ﴾ . ويقول الأستاذ الشهيد سيد قطب في تفسير هذه الآية : « هي العقيدة التي تعترف بالإنسان إنساناً ، لا حيواناً ، ولا ملكاً ، ولا شيطاناً.. تعترف به كما هو بكل ما فيه من ضعف وكل ما فيه من قوة .. وتأخذه وحدة مؤلفة من جسد ذي نوازع ، وعقل ذي تقدير ، وروح ذي أشواق .. وتفرض عليه من التكاليف ما يطيق . وتراعي في التنسيق بين التكليف والطاقة بلا مشقة ولا إعنات » .", "هذا وقد حذر الرسول ﷺ من كل تفريط ونهى عن كل", "- ١١٣ - الدعوة (٨)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0115.png"}, {"n": 116, "paras": ["إفراط . فعن عائشة رضي الله عنها ، أن النبي ﷺ دخل عليها وعندها امرأة . قال : من هذه ؟ قالت : هذه فلانة تذكر من صلاتها .. قال : مه ، عليكم بما تطيقون . فوالله لا يمل الله حتى تملوا .. ومه : كلمة نهي وزجر .. ومعنى ( لا يمل الله ) لا يقطع ثوابه عنكم حتى تملوا فتتركوا . فينبغي لكم أن تأخذوا ما تطيقون الدوام عليه ليدوم ثوابه وفضله عليكم .", "وعن أبي هريرة رضي الله عنه عن النبي ﷺ قال : « إن الدين يسر ، ولن يشاد الدين أحد إلا غلبه . فسددوا وقاربوا، وأبشروا واستعينوا بالغدوة (١) والروحة (٢) وشيء من الدلجة (٣) » .", "ويقول الإمام النووي في تفسير هذا الحديث : ( وهذه استعارة وتمثيل ، ومعناه : استعينوا على طاعة الله عز وجل بالأعمال في وقت نشاطكم وفراغ قلوبكم ، بحيث تستلذون العبادة ولا تسأمون ، وتبلغون مقصودكم . كما أن المسافر الحاذق يسير في هذه الأوقات ويستريح هو ودابته في غيرها فيصل المقصود بغير تعب ، والله أعلم ) .", "(١) الغدوة : سير النهار .", "(٢) الروحة : سير آخر النهار .", "(٣) الدلجة : آخر الليل ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0116.png"}, {"n": 117, "paras": ["ويقول الرسول ﷺ : « إن المنبتَّ لا أرضاً قطع ولا ظهراً أبقى » . والنفس يشق عليها تقمص طبيعة ليست فيها ، وممارسة خصال ليست منها .. وهي إن صبرت على هذا التكلف بادىء الأمر فستمله في النهاية . والعاقل من سما بنفسه دونما ملل منها.. وسعى مع الأيام على تعويدها حمل المزيد من التكاليف والأعباء من غير إعياء لها .. وبذلك يبلغ بها ما يريده منها ..", "حقيقة التجرد : ونفس الداعية لا يمكن أن تستكمل خصالها الإسلامية وخصائصها الربانية ما لم تتجرد لله ، وتتحرر من كل ما يستبد بها أو يطغيها .. فإن كان المال فلتزهد فيه .. وإن كانت الشهوة فلتتحرر منها . ليكن الغنى بالنفس لا بالفلس .. ولتكن العزة بالله لا بالجاه .. ولتكن المرأة وسيلة إحصان وطاعة لا عامل انحلال وميوعة ... وروي أن رسول الله ﷺ سئل يوماً عن أزهد الناس في الدنيا فقال : « من لم ينس المقابر والبلى ، وآثر ما يبقى على ما يفنى ، وعد نفسه مع الموتى » . وقال ﷺ : « الزهد في الدنيا مفتاح الرغبة في الآخرة » . وورد عن ابن السماك قوله : ( الزاهد ، الذي إن أصاب"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0117.png"}, {"n": 118, "paras": ["الدنيا لم يفرح . وإن أصابته الدنيا لم يحزن . يضحك في الملأ ويبكي في الخلاء ) .", "هذه بعض الملامح الخاطفة لمعالم الشخصية الإسلامية وخصائصها وصفاتها قد تحتاج إلى مزيد من التفصيل والتبسيط . وحسبي أن يكون فيها ما يحقق بعض الرجاء .. والله ولي التوفيق ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0118.png"}, {"n": 119, "paras": ["الداعية وأسلوب الدعوة", "• الأسلوب الحسن .", "• بين الشدة واللين", "• ماذا نريد ؟"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0119.png"}, {"n": 120, "paras": ["هناك عوامل تساعد على إنجاح الداعية إلى حد كبير في مجالات الدعوة ، وتحقق له الخصب والإثمار ، وتمنحه القدرة على التأثير والتفاعل والإيغال بأفكاره في كل وسط وعلى كل صعيد . والأسلوب الحسن هو أحد العوامل الحساسة الهامة التي توفر على الداعية الوقت والجهد ، وتصل به إلى الغاية المطلوبة بأقل التكاليف وأيسرها .. فالداعية في كل مجال من مجالات الدعوة والتبليغ .. في نطاق الكتابة والخطابة والتحدث والنقاش .. في العمل الشعبي والنقابي والسياسي والطلابي . بحاجة إلى الأسلوب الحسن الذي يصيب الهدف ويبلغ القصد . وقد يكون من أبرز الأمور التي ينبغي توفرها لدى الداعية ليتمتع بالأسلوب الحسن ، تعرفه على الوسط الذي يكون ميداناً لنشاطه وعمله .. يدرس أوضاعه ومشكلاته واتجاهاته وميوله .. كالطبيب تماماً يرقب عوارض المرض وتطوره ومراحله .. ثم يشخص أسبابه وبواعثه ، على علم ومعرفة .. علم بخصائص الداء ومعرفة بأسباب الشفاء . والداعية الناضج كالطبيب الناجح يعرف من أين يبدأ وكيف"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0120.png"}, {"n": 121, "paras": ["يبدأ .. ثم هو لا يبدأ قبل أن تتوفر لديه إمكانيات التمحيص والتشخيص والمعالجة .. حتى لا يكون عمله سلسلة تجارب فاشلة ومحاولات مرتجلة .", "والمجتمع اليوم يموج بعديد المذاهب والاتجاهات .. وكلها تتجاذب الناس بما تطلع عليهم من دعايات منمقة وأساليب مزوقة .", "تخاطبهم من حيث يصغون ويسمعون .. وتأتيهم من حيث يحسون ويشعرون .. تلامس جروحاتهم وتتحسس أمراضهم وتتبنى مشكلاتهم .", "ودعاة الإسلام يجب أن لا يكونوا أقل عناية واهتماماً بأساليب دعوتهم من سواهم .. فلا يخاطبون ( العمال الكادحين بلغة القبوريين ) ولا يناقشون ( الملاحدة الماديين بلسان العاطفيين ) . وإنما يجعلون لكل مقام مقالاً .. مصداقاً لقول الرسول ﷺ « أمرت لأخاطب الناس على قدر عقولهم » .", "إن الإسلام في هذا الزمن بحاجة إلى دعاة يحسنون عرض أفكاره ومبادئه بأسلوب شيق جذاب .. يحببون بالإسلام فلا ينفرون منه ، ويوضحون أفكاره فلا يعقدونها . وكم من أدعياء شوهوا الإسلام بسوء دعوتهم ، وأساؤا إليه وهم يحسبون أنهم يحسنون صنعاً .", "ومن هنا كانت وظيفة الدعاة دقيقة وحساسة وتتطلب كثيراً من اللباقة والحكمة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0121.png"}, {"n": 122, "paras": ["بين الشدة واللين .", "فالنفوس جبلت على حب من أحسن اليها .. وقد تدفعها القسوة والشدة أحياناً إلى المكابرة والإصرار والنفور فتأخذها العزة بالاثم . وليس معنى اللين المداهنة والرياء والنفاق ، وإنما بذل النصح واسداء المعروف بأسلوب دمث مؤثر ، يفتح القلوب ويشرح الصدور وبخاصة إذا كانت الدعوة ( لجماعة المسلمين ) فانه لا ينبغي بحال مخاطبتهم بالتوبيخ والتقريع والعنف .", "ألم تر إلى القرآن الكريم في معرض التوجيه الرباني للأسلوب الحسن الطيب يخاطب ( موسى وهارون ) ويوصيهما بمبادأة الطاغية ( فرعون ) باللين والحسنى : ( اذهبا إلى فرعون إنه طغى فقولا له قولاً ليناً لعله يتذكر أو يخشى ) بل ان اللفتات القرآنية والإشارات النبوية إلى الرفق ومجانبة الغلظة والشدة تؤكد بما لا يحتمل الشك ( فاعلية ) هذا الأسلوب وقيمته التأثيرية .", "يقول الله تعالى في آخر سورة ( النحل ) آمراً نبيه بالتزام الحكمة في دعوة الناس: ﴿ادع إلى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن. إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بالمهتدين﴾ وفسرها ابن كثير بقوله : « أي من احتاج إلى مناظرة وجدال فليكن بالوجه الحسن وبرفق ولين وحسن خطاب » .", "وفي سورة ( آل عمران ) يشير القرآن الكريم إلى فوائد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0122.png"}, {"n": 123, "paras": ["الرفق واللين في كسب الأنصار والمؤيدين وبالتالي انطلاق الدعوة والتفاف القلوب حولها فيقول : ﴿ فبما رحمة من الله لنت لهم . ولو كنت فظاً غليظ القلب لانفضوا من حولك ﴾ وقد ورد في تفسير هذه الآية قول لعبد الله بن عمر جاء فيه : « إني أرى صفة الرسول ﷺ في الكتب المتقدمة .. إنه ليس بفظ ولا غليظ ولا صخاب في الأسواق ، ولا يجزي بالسيئة السيئة ، ولكن يعفو ويصفح » .", "وفي السيرة النبوية نماذج مختلفة للأسلوب الأخاذ النافذ الذي كان يبلغ به رسول الله ﷺ غايته بلباقة وحكمة . فقد روى أبو أمامة أن غلاماً شاباً أتى النبي ﷺ فقال : يا نبي الله ، أتأذن لي في الزنا ؟ فصاح الناس به فقال النبي ﷺ : أدن فدنا حتى جلس بين يديه ، فقال النبي ﷺ : أتحبه لأمك؟ قال : لا ، جعلني الله فداك . قال : كذلك الناس لا يحبونه لأمهاتهم .. أتحبه لابنتك ؟ قال : لا ، جعلني الله فداك . قال : كذلك الناس لا يحبونه لبناتهم .. أتحبه لأختك ؟ - وزاد ابن عوف - أنه ذكر العمة والخالة وهو يقول في كل واحدة : لا، جعلني الله فداك ، فوضع رسول الله يده على صدره وقال : « اللهم طهر قلبه واغفر ذنبه وحصن فرجه » . فلم يكن شيء أبغض اليه منه ، يعني الزنا (١) ..", "(١) رواه أحمد بإسناد جيد ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0123.png"}, {"n": 124, "paras": ["وأسلوب الداعية ينبغي أن يكون متجدداً في حدود ما يسمح به الإسلام .. ومرونة الإسلام تقتضي الدعوة بأسلوب العصر ولغته وبمختلف الوسائل - المشروعة - التي تضمن نقل الإسلام إلى الناس في أبهى صورة وأحسن وجه .. وهذا منطق المرونة في قول الرسول ﷺ : « الحكمة ضالة المؤمن انى وجدها فهو أحق الناس بها » وقوله : « خذوا الحكمة من أي وعاء خرجت » .", "ماذا نريد :", "وقد يكون من خير ما يحقق الأسلوب الحسن لدى الداعية إدراكه الواضح العميق لما يريد .. فتقويم التصور والتشخيص الواضحين للغايات والأهداف يملي على الداعية الأسلوب الذي ينبغي التزامه وتبنيه .", "وإدراك الداعية لما يريد يوفر عليه الوقت والجهد . ويجعل سيره وإنطلاقه على هدى ونور .. فلا يخبط خبط عشواء دونما تقدير للعواقب أو تحسب للنتائج .. وإلى هذا المعنى يشير التوجيه الرباني الكريم فيقول : ﴿ يا أيها الذين آمنو اتقوا الله وقولوا قولاً سديدا . يصلح لكم أعمالكم ويغفر لكم ذنوبكم ومن يطع الله ورسوله فقد فاز فوزاً عظيما ﴾ .", "فيجدر بالداعية أن يعرف ماذا يريد من كل خطوة يخطوها، ومن كل عمل يقوم به ، سواء في مجال الخطابة والكتابة والمناقشة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0124.png"}, {"n": 125, "paras": ["أو في مجال العمل الشعبي والنقابي والطلابي . وصدق الحسن البصري حيث يقول : « العامل على غير علم ، كالسائر على غير طريق . والعامل على غير ما يريد يفسد أكثر مما يصلح » . وفي الحكم :( من سلك طريقاً بغير دليل ضل . ومن تمسك بغير أصل ذل ) ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0125.png"}, {"n": 126, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0126.png"}, {"n": 127, "paras": ["دعاة الإسلام وتفاوت القابليات", ". مراتب التفاوت وأشكاله ● . عوامل التفاوت وأسبابه ●"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0127.png"}, {"n": 128, "paras": ["تتفاوت الاستعدادات والقابليات الحركية لدى العاملين في الحقل الإسلامي تفاوتاً ملحوظاً . ويبدو هذا التفاوت في حياة هؤلاء الخاصة والعامة . كما يتجسد كذلك في صلتهم بالتنظيم وانضباطهم به وفي نشاطهم الاجتماعي ومدى نجاحهم فيه ..", "مراتب هذا التفاوت وأشكاله : ويمكننا تصنيف هذا التفاوت في القابليات إلى ثلاثة أشكال :", "الشكل الأول : وتكون فيه الاستعدادات والقابليات لدى الأخ من أحسن ما يكون فهماً وإيماناً وتفاعلاً وانضباطاً .. والذين يتمتعون بمثل هذا المستوى من الاستعداد - هم بحق - ركيزة الدعوة وقوة الدفع فيها . وتوافرهم في الوجود الحركي من أهم عوامل استقراره وإثماره ..", "الشكل الثاني : وتكون فيه الاستعدادات لدى الأخ بين مد وجزر، وقوة وضعف .. فهو بين اقبال وادبار، وتفاؤل وتشاؤم ، تبعاً لظروفه الخاصة وظروف الحركة العامة .. وهذا الصنف من الناس تجدر"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0128.png"}, {"n": 129, "paras": ["العناية بهم ، من حيث معرفة مشكلاتهم وأسبابها .. فقد تكون مشكلاتهم خارجة عن إراداتهم ، مفروضة على حياتهم ، فينبغي مساعدتهم على حلها والخروج بهم من أجوائها .. وقد تكون ناجمة عن ضعف في تكوينهم الإسلامي ، فيجب اكمال جوانب النقص لديهم .", "الشكل الثالث : وتكون فيه الاستعدادات والقابليات لدى الأخ معدومة فطرياً .. بمعنى أن التكوين العصبي والارادي والقدرات الفكرية والنفسية ليست في مستوى يمكنه من الإنتاج والعطاء . وقد يكون هذا الصنف عبئاً على الحركة في مرحلتها الحاضرة . لأنه يعيش على حسابها ويتغذى بدمها . يأخذ منها ولا يعطي لها . وفي أمثال هؤلاء لا يجوز أن تستهلك الطاقات وتصرف الجهود وتهدر الامكانيات .", "عوامل هذا التفاوت وأسبابه : وبديهي أن يكون لهذا التفاوت عوامل كثيرة لا حصر لها .. منها الفطري ومنها الوراثي ومنها الاكتسابي .. وإذا تجاوزنا العاملين الأولين إلى العامل الأخير الذي يدخل في نطاق القدرة البشرية لأمكننا تحديد الأسباب الرئيسية لنشأته .. وهذا التشخيص يمكننا بالتالي من معالجة ما يمكن معالجته من الضعف والوهن ، وبعث القابليات واستنهاضها وجعل أصحابها في مستوى"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0129.png"}, {"n": 130, "paras": ["المسؤولية وعلى قدر حملها . العامل الأول : ويتعلق بمدى فهم الأخ لإسلامه .. فقد يكون فهمه للإسلام سطحياً ممسوخاً .. وقد لا يكون واضحاً تمام الوضوح .. أو قد يكون فهماً جزئياً غير متكامل .. ولهذا حض الإسلام على استكمال العدة الفكرية بحسن التفقه في الدين ومعرفة أغراضه وغاياته . فقال الرسول ﷺ : « من يرد الله به خيراً يفقهه في الدين » .", "العامل الثاني : ويتعلق بمدى تفاعل الأخ مع مبادىء الإسلام في حياته الخاصة والعامة .. فقد يكون عالماً بالإسلام غير عامل به . يدعو الناس إلى ما يخالفهم اليه .. ويسبقهم إلى ما ينهاهم عنه . وهذا من شأنه أن يعدم في نفسه حوافز الخير ويجعله في دوامة من القلق والشقاء لا يخرج منها حتى تنقطع آخر صلة له بالإسلام .. ولقد ندد القرآن الكريم بهذا الصنف من الناس حين قال: ﴿ أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتاب أفلا تعقلون ﴾ ﴿ يا أيها الذين آمنوا لم تقولون ما لا تفعلون . كبر مقتاً عند الله أن تقولوا ما لا تفعلون ﴾ .", "العامل الثالث : ويتعلق بمدى قرب الأخ من الله وصلته به .. فالداعية لا"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0130.png"}, {"n": 131, "paras": ["يمكن أن تكتمل شخصيته ويستقيم خطوه وتزكو نفسه وينشرح صدره ويكثر إنتاجه ويعم إثماره ، ما لم يتحرر من عبودية غير الله ، ويستشعر قرب الله منه ورقابته عليه .. وهذا لا يمكن أن يتأتى بغير مجاهدة النفس وميولها حتى تعطي المقاد وتسلس القياد .", "العامل الرابع : ويتعلق بمدى تملك الأخ لزمام نفسه وقوامته على أهوائه وغرائزه .. فإذا كانت حياة الأخ مليئة بالمغريات والمفاتن وجب أن يكون محصناً تحصيناً قوياً ، دائم الاستعداد لمقاومة نوازع الشر وإلقاءات الشيطان فيه .. مدركاً بوعي وعمق قول الله تعالى : ﴿ إن الشيطان لكم عدو فاتخذوه عدواً ﴾ ، ذاكراً قول الرسول ﷺ : « إن الشيطان ليسري من ابن آدم مسرى الدماء » .", "- ١٢٩ - الدعوة (٩)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0131.png"}, {"n": 132, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0132.png"}, {"n": 133, "paras": ["بَيْنَ العَقَائِدِيَّةِ وَالحِزْبِيَّةِ", ". بَيْنَ الحِزْبِيَّةِ وَالانسانية . بَيْنَ العَقَائِدِ وَالشخصانية . بَيْنَ التَّجَرُّدِ وَالمساومة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0133.png"}, {"n": 134, "paras": ["في الحقيقة أننا - كحركة إسلامية - بحاجة إلى تغيير مفاهيمنا ونظراتنا في كثير من المسائل والأمور المتعلقة بالعمل الإسلامي. وحركتنا ينبغي أن تتميز في شخصيتها وطبيعة عملها ونوعية أفرادها عن سائر الحركات السياسية والحزبية الحديثة .", "بين الحزبية والانسانية : وفي اعتقادي أن الحركة الإسلامية تأثرت إلى حد بالجو الحزبي الذي تعيشه البلاد العربية في هذه الحقبة من الزمن .. حتى كادت تتلوث طبيعة العمل الإسلامي وأساليبه - في بعض الأحيان - بالروح الحزبية الضيقة التي لا تتفق بحال ونزعة الانفتاح والإنسانية في الإسلام .", "وإذا قلت إن طبيعة العمل الإسلامي غير طبيعة العمل الحزبي، فلأن التصور العقيدي والمبادىء التشريعية والتوجيهية التي يقوم عليها المنهج الإسلامي لا تتفق في شيء مع ما تقوم عليه الحركات الحزبية من تصورات ومبادىء .", "إن للإسلام طبائع خاصة مميزة في - عقيدته - ومبادئه - وأساليبه - وأهدافه - وغاياته - كما أن له مقاييس ثابتة ليس للظروف والأحداث المتحركة من سلطان عليها أو تأثير فيها ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0134.png"}, {"n": 135, "paras": ["فعقائدية الإسلام تفرضها نظرته إلى الكون والإنسان والحياة .. نظرته الإلهية التي تتجلى في الإيمان بوجود خالق لهذا الكون . وما لهذا الاله على الإنسان من حقوق.. وما في شريعته من ضمان لحياة طيبة في الدنيا وفي الآخرة .. ثم ما يترتب على الأخذ بها أو الاعراض عنها من ثواب وعقاب.. ونظرته الإنسانية التي تتجلى في عظيم المنزلة التي رشح الإنسان إليها .. وكريم الوظيفة التي خلق من أجلها .. وجلال الغاية التي يعمل لها ويجاهد في سبيلها .", "فالداعية المسلم يريد الخير لكل الناس .. ويسعى لإسعاد جميع البشر برسالة الاسلام .. لا يتعصب لجنس أو لون ولا لجماعة أو حزب .. وإنما هو روح جديدة تسري في جسم هذه الأمة فتحييه بالحق . ونور وضيء ينير الدروب ويحيي القلوب ويهدي الحيارى سواء السبيل .", "وهو مع هذا وذاك لا يربط بين ( الجهد والجزاء ) أو بين ( العمل والنتيجة ) إلا بمقدار ما يحسه من قبول ورضى الله تبارك وتعالى .. فلا يكون إقباله أو إدباره في مجالات العمل والكفاح ما يستتبعانه من نصر أو هزيمة .. فلا يطربه رضى الناس عنه أو يسخطه غضبهم عليه .. وإنما له في حياة الداعية الأول ﷺ المثل الأعلى والقدوة الحسنة حيث يقول : « اللهم إن لم يكن بك غضب عليّ فلا أبالي » ..", "هذه الطبيعة الإنسانية التي جبل الإسلام بها تتنافى كل المنافاة مع طبائع الحركات الحزبية الأخرى . ومن فضائل هذه الطبيعة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0135.png"}, {"n": 136, "paras": ["إنها تكسب العاملين في الحقل الإسلامي صفات الانفتاح للناس جميعاً .. فهم دعاة خير .. ومنابر هدى .. ومشاعل نور .. يقرعون كل باب .. ويرشدون كل ضال .. وكذلك جعلناكم أمة وسطاً لتكونوا شهداء على الناس ويكون الرسول عليكم شهيداً . والاطار العقائدي الذي يقيد به الإسلام ميدان العمل الإسلامي يعتمد على ناحيتين اثنتين :", "أولهما : وضوح الغاية في أعماق الداعية ، حتى لا يزيغ به هوى ، أو تنحرف له رغبة . فعن ابن عباس رضي الله عنه قال : جاء رجل إلى رسول الله ﷺ فقال : يا رسول الله ، إني أقف الموقف أريد وجه الله وأريد أن يرى موطني . فلم يرد عليه رسول الله ﷺ حتى نزل قوله تعالى : ﴿ فمن كان يرجو لقاء ربه فليعمل عملاً صالحاً ولا يشرك بعبادة ربه أحداً ﴾ .", "وثانيهما : سلامة الوسيلة وضمان مشروعيتها، وموافقتها لروح الإسلام. وبذلك تتحقق صيانة العمل الإسلامي من كل انحراف يمكن أن تتسببه القاعدة الحزبية التي تقول بتبرير الوسائل من أجل الغايات . فإذا كانت طبائع الحركات الحزبية، تعتمد -مثلاً- الطرق الملتوية غير الكريمة في سبيل تحقيق أهدافها، وتستسيغ من أجل"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0136.png"}, {"n": 137, "paras": ["ذلك كل لون من ألوان الخداع والتضليل، فإن الحركة الإسلامية تأبى عليها عقيدتها هذا النوع من الوسائل .", "بين العقائدية والشخصانية : وتبدو عقائدية الإسلام في دعوته إلى التمسك بالمبادىء والمثل ، لا بالأشخاص والزعماء .. وبذلك يصبح العمل الإسلامي في مأمن من الانحرافات الفردية .. فإذا كانت ( الشخصانية ) جرثومة فناء الحركات الحزبية، فإن ( العقائدية ) عامل بقاء الحركة الإسلامية واستمرارها .", "إن العقيدة التي غرسها الإسلام في نفوس أصحابه جعلتهم يخاصمون في الحق أقرب الناس اليهم، ويوادون في الله أبعد الخلق عنهم .. فلا تساهل مع قريب أو حبيب في حد حدود الله أو أمر من أمور الإسلام : ﴿يا أيها الذين آمنوا لا تتخذوا آباءكم وإخوانكم أولياء إن استحبوا الكفر على الإيمان ، ومن يتولهم منكم فأولئك هم الظالمون﴾ فلا طاعة لمخلوق في معصية الخالق ، فهذه أم حبيبة ) زوج الرسول ﷺ تمنع أباها ( المشرك ) من الجلوس على فراش الرسول وتقول له مغاضبة : «انه فراش رسول الله وانك مشرك نجس » .. وهذا مصعب بن عمير يقول لأمه : ( المشركة ) التي أقسمت أن لا تذوق طعاماً حتى يعود إلى دينها ويترك الإسلام : « والله يا أماه لو كانت لك مائه نفس خرجت نفساً نفساً ما تركت دين محمد » . بهذه العقائدية الفذة يقي الإسلام دعوته ودعاته من جميع"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0137.png"}, {"n": 138, "paras": ["المؤثرات العاطفية والشخصية . ففي معركة (بدر) التقى الآباء بالابناء والأخوة .. خالفت بينهم المبادىء ففصلت بينهم السيوف .. كان أبو بكر في صف المسلمين وكان ابنه عبد الرحمن في صف المشركين .. كان عتبة بن ربيعة أول من بارز المسلمين ، وكان ولده أبو حذيفة من أهل السابقة في الإسلام .. وعندما سحبت جثة عتبة لترمى في (القليب) نظر الرسول إلى أبي حذيفة فإذا هو كثيب قد تغير لونه .. فقال له : « يا أبا حذيفة لعلك قد دخلك من شأن أبيك شيء ..» فقال : لا والله يا رسول الله ، ما شككت في أبي ولا في مصرعه. ولكنني كنت أعرف من أبي رأيا وحلماً وفضلاً، فكنت أرجو أن يهديه ذلك إلى الإسلام. فلما رأيت ما أصابه، وذكرت ما مات عليه من الكفر بعد الذي كنت أرجو له أحزنني ذلك .", "بين التجرد والمساومة : وعقائدية الإسلام لها في آفاق (التربية) أعمق الأثر .. فالتجرد لله من كل هوى وغاية شخصية .. والإخلاص له في السر والعلانية .. والثبات على الحق .. تكاد تكون كلها من خصائص العقائدية التي يؤكد عليها الإسلام في جميع مجالاته العبادية والتوجيهية والتشريعية . ولهذا تأبى عقيدة الإسلام على أصحابها أي لون من ألوان المساومة مهما كان الثمن غالياً والعرض سخياً .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0138.png"}, {"n": 139, "paras": ["فهذه قريش تقترح على رسول الله أن يعبد (آلهتها) شهراً لتعبد هي (آلهه) شهراً آخر . فيرد عليهم محمد ﷺ بالقول الفصل من رب العالمين: ﴿قل يا أيها الكافرون. لا أعبد ما تعبدون. ولا أنتم عابدون ما أعبد. ولا أنا عابد ما عبدتم. ولا أنتم عابدون ما أعبد. لكم دينكم ولي دين﴾. وجاء (عتبة بن ربيعة) يوماً إلى رسول الله ﷺ يعرض عليه العروض السخية .. يعرض عليه الملك والمال والسلطان، على أن يترك الأمر الذي بعث به ويتخلى عن الإسلام .. فالتفت اليه الرسول ﷺ مستعلياً بإيمانه معتزاً بدينه قائلاً: « ما جئتكم بما جئتكم به أطلب أموالكم ولا الشرف فيكم ولا الملك عليكم.. ولكن الله بعثني إليكم رسولا. وأنزل عليّ كتاباً .. وأمرني أن أكون لكم بشيراً ونذيراً . فان تقبلوا مني ما جئتكم به فهو حظكم في الدنيا والآخرة .. وإن تردوه عليّ أصبر لأمر الله، حتى يحكم الله بيني وبينكم » ..", "كلمة أخيرة : ولعل سر ما للاسلام من أثر في تأصل عقائديته وعمقها في نفوس أصحابها يعود إلى استشعارهم فضل الله وهم في ذروة النصر وقمة النجاح .. فلا يرون النصر إلا من عند الله .. ولا يحسون بغير فضل الله عليهم. وبذلك تبقى النفوس طيعة متواضعة لا تخرجها عن سمتها الأصيل عاديات الكبر والغرور .. ﴿وإن ربك لذو فضل على الناس ولكن أكثرهم لا يشكرون﴾ ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0139.png"}, {"n": 140, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0140.png"}, {"n": 141, "paras": ["الحركة الإسلامية بين التكامل والتآكل", ". في التربية والتكوين . في المواجهة والعمل الحركي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0141.png"}, {"n": 142, "paras": ["المراقب لما يجري في نطاق العمل للاسلام خلال نصف القرن الماضي ، تبدو له ملامح ظاهرة مخيفة ، وهي ان الاعمال والتجارب التي قامت في هذا النطاق تجريان في دوامة مغلقة من التكامل والتآكل .. والمقصود بالتكامل والتآكل هو أن التجارب التي قامت لا تكاد عناصرها تتكامل حتى تأخذ بالتآكل ، وإنها لا تكاد امكانياتها تتهيأ وتتجمع حتى تأخذ بالانفراط قبل أن تحقق الهدف الرئيسي من وجودها بإقامة المجتمع الإسلامي واستئناف الحياة الإسلامية .. وتبدو ملامح هذه الظاهرة بشكل بارز وملحوظ على صعيد ( المنطقة العربية ) حيث عجزت الحركات الإسلامية عن تحقيق ولو تجربة واحدة في قطر واحد على الأقل .. هذا فضلاً عن أن الحركة في عدد من الأقطار تراجعت تراجعاً مخيفاً أمام التيارات المادية الغازية وأخلت خطوط دفاعها الأولى، الأمر الذي مكن لهذه القوى الجاهلية في بلاد المسلمين ، وسهل لها سبيل الوصول إلى السلطة واغتصابها ، ومن ثم استخدامها وتسخيرها لحرب الإسلام بوجه عام، ولضرب الحركة الإسلامية بوجه خاص .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0142.png"}, {"n": 143, "paras": ["تشخيصات :", "والعاملون في الحقل الإسلامي المسلمون بوجود هذه الظاهرة، متباينون في تقديرهم لأسباب نشوئها واستفحالها .. فمنهم من يعتبرها أمراً طبيعياً ونتيجة محتومة لانحسار الخير وطغيان الشر على العالم ، وبالتالي لحتمية ( الغربة ) التي سيؤول اليها الإسلام في آخر الزمان .. ويستدلون على ذلك بأحاديث للرسول الأعظم ﷺ منها قوله : « يأتي على الناس زمان الصابر فيهم على دينه كالقابض على الجمر (١) » وقوله : « خير القرون قرني ثم الذي يليه ؛ ثم الذي يليه ، والآخرون أراذل (٢) » . ومنهم من يرد الاسباب إلى سوء الأوضاع الاجتماعية والاقتصادية والسياسية التي تعيشها الأمة في أعقاب سقوط الدولة الإسلامية وانتقاض الحكم الإسلامي، وإلى المؤمرات التي تتكاتف فيها القوى العالمية الثلاث : ( الصهيونية والشيوعية والصليبية ) لضرب الاتجاه الإسلامي وعزل الفكرة الإسلامية عن الحياة ، طوراً باثارة النعرات العصبية والقومية ، وطوراً آخر بانشاء الحركات المادية الالحادية والتبشيرية ، وبكل الطرق والأساليب التي من شأنها تشكيك المسلمين بمعتقداتهم وتشريعاتهم . ومنهم من يعزو الأمر إلى قلة الإمكانيات البشرية والفنية .", "(١) حديث حسن رواه الترمذي .", "(٢) حديث حسن رواه الطبراني والحاكم ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0143.png"}, {"n": 144, "paras": ["والمادية التي تمتلكها الحركة الإسلامية المعاصرة ، وانها دون مستوى المواجهة مع الجاهلية العاتية ..", "مناقشات : والحقيقة أن كل ما ورد من آراء في مناقشة أسباب بروز ظاهرة ( التكامل والتآكل ) في نطاق التجارب المعاصرة للعمل الإسلامي، هي من الأسباب ولكنها ليست الأسباب كلها ، بل إنها في الحقيقة ليست الأسباب الرئيسية الجوهرية الكامنة وراء هذه القضية ..", "فالذين يعتبرون ( الظاهرة ) أمراً طبيعياً ونتيجة محتومة لانحسار الخير وطغيان الشر محقون ولكن إلى حد .. فالشر كان موجوداً منذ الخليقة .. ودعوات الرسل والأنبياء جميعاً ليس لها من مبرر لولا وجود الشر وانحراف البشرية وحاجتها إلى الإصلاح والتقويم .. بل إن طغيان الباطل وجنده ينبغي أن يحفز الحق وأهله لمزيد من الإصرار والتمرد والثبات .. ولقد قيل للحق يوماً: (أين كنت في صولة الباطل ؟ قال كنت اجتث جذوره ) .. والواقع أن الباطل لا يذيع ويشيع إلا في غفلة أهل الحق وضعفهم وانعزالهم عن ميادين البذل والجهاد .", "وأصحاب هذا الرأي مخطئون إذا اعتقدوا بأن لا أمل في الإصلاح .. وهم في ذلك خارجون عن دائرة التصور الإسلامي لأن اعتقادهم هذا سيدفعهم بدون شك إلى الانسحاب من المعركة والفرار من الزحف، وبالتالي سيصابون باليأس وسيلقون السلاح،"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0144.png"}, {"n": 145, "paras": ["وليس معنى هذا سوى الاستسلام والانهزام .. إن الإسلام يطالب أتباعه والمؤمنين به أن يعملوا ويبذلوا قصارى جهدهم وصادق جهادهم ليس إلا .. أما النصر فإنه من شأن الله وقدره ، كما إنه في صحائف غيبه وعلمه .. وحري بأهل الحق أن يفرغوا طاقاتهم ويبذلوا ما وسعهم البذل فيما يحقق رضاء الله أولا ، وحق ولو لم يكونوا ضامنين للنصر واثقين منه .. وهذا معنى قوله تعالى : ﴿ إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة ﴾ . وأما الذين يردون الأمر إلى سوء الأوضاع وتردي القيم وطغيان الجاهلية وفساد الزمن ، فنحن نعترف معهم بأن الإسلام يواجه تحديات في غاية القوة والشراسة والخبث .. ولكن هذا ينبغي أن لا يكون ، وليس هو السبب الأساسي الذي أدى إلى وقف المسيرة الإسلامية وتخبطها ، وإلى نشوء ظاهرة التكامل والتآكل في حياتها . وثمة نقطة أخرى تجدر الإشارة اليها - كذلك - وهي أن الأوضاع السيئة التي عليها العالم بصورة عامة والأمة الإسلامية، بصورة خاصة ستزداد يوماً بعد يوم ، ما لم تتدارك الحركة الإسلامية الأمر وتنقذ الموقف. أما أن ننتظر تغير الأوضاع بشكل عفوي وبدون ثمن يبذل. وتضحية تقدم ، فإن ذلك لضلالاما بعده ضلال؟ إن من واجب الحركة الإسلامية أن تفكر - اليوم - بغير العقلية التي كانت تفكر فيها بالأمس .. لأن الأمس وظروفه وأوضاعه لم يعد في واقع اليوم إلا ذكريات مضت ، وهيهات أن"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0145.png"}, {"n": 146, "paras": ["تعود.. إن الأنظمة التي كانت تسمح إلى حد ما بممارسة النشاطات الحزبية المختلفة قد بادت وانقرضت وحلت محلها أنظمة حزبية بوليسية حاقدة على الإسلام وضليعة في التآمر عليه . وعبثاً تنتظر الحركة تغير الحال من غير بذل جهد ودفع ثمن: ( ألا إن سلعة الله غالية ، ألا إن سلعة الله الجنة ).", "وأما الذين يعزون بروز ظاهرة التكامل والتآكل في حياة الدعوة إلى قلة في الإمكانيات وضعف في الطاقات فأنا لست معهم في شيء . فالحركة الإسلامية في الواقع لا تشكو فقراً في الإمكانيات بقدر ما تشكو من عدم الاهتمام بهذه الإمكانيات وتنميتها وتطويرها والاستفادة منها على الزمن .. لقد مرت في تاريخ الحركة الإسلامية المعاصرة فرص وظروف كان في صفوفها من الإمكانيات ما لم يكن عند سواها من الحركات التي سبقتها إلى السلطة وإلى الحكم في أكثر من قطر ؟ ولكن إهمالها لهذه الإمكانيات وعدم الاستفادة منها فيما يتلاءم مع طبيعتها واختصاصاتها وقدراتها، وبالتالي عدم استيعابها فكرياً وتوجيهياً وحركياً ، أدى إلى فقدان بعضها ، وإلى نمو البعض الآخر نمواً وحشياً غير طبيعي فيه كثير من التشويه والانحراف ..", "أين يكمن الداء إذن ؟", "إن الداء يكمن من وجهة نظري - أكثر ما يكن - في (الجسم الحركي) نفسه، وان كنت لا أنكر كذلك أثر الضغوط"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0146.png"}, {"n": 147, "paras": ["الخارجية على الحركة الإسلامية .. إنه يبدو في الفوضى الفكرية بين القادة والافراد .. وفي فقدان الطاعة والنظام في العاملين، وفي فقدان الانقياد في الجنود. كما يبدو في فتور الشعور بالمسؤولية في الجميع ، وفي الخواء الروحي وفي الترخص وعدم أخذ النفس بصرائم الامور .. الصفوف معوجة مضطربة .. والقلوب خاوية حائرة .. والسجدة خامدة جامدة .. لا حرارة فيها ولا شوق(١) ؟ التصور لطبيعة العمل سطحي .. وخطط المواجهة مرتجلة.. والعمل ضعيف متقطع لا استمرار فيه ولا ثبات عليه .. وحتى نكون موضوعيين في مواجهة هذه المعضلة ، لا بد من تحديد مواطن الداء بدقة ومناقشة الموضوع بتفصيل ، أملا في الوصول إلى ما يعيننا على الخروج من هذه الدوامة التي استطار شرها واستفحل أمرها .", "في نطاق التربية والتكوين : إن بناء الشخصية المسلمة هو الخطوة الأولى في نطاق التحضير لبناء الدولة الإسلامية ، كائناً ما كان أسلوب الحركة ومنهجها في العمل .. والشخصية الإسلامية لا يمكن أن تبنى وتتم ولادتها ما لم تسلم من مؤثرات المجتمع الجاهلي ومن ازدواجية التلقي والتوجيه ..", "(١) راجع كتاب : ربانية لا رهبانية الاستاذ أبي الحسن الندوي .", "- ١٤٥ - الدعوة (١٠)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0147.png"}, {"n": 148, "paras": ["وتجدر الإشارة هنا - كذلك - إلى أن المقصود ببناء الشخصية المسلمة هو تكوين طليعة قيادية أو تنظيم حركي طليعي في مستوى ما تتطلبه المواجهة مع جاهلية اليوم .. إن أبرز الصفات التي ينبغي توفرها في الشخصية الإسلامية هي : أولاً : الانخلاع من الجاهلية انخلاعاً كلياً .. سواء في الاحاسيس والمشاعر، أو الافكار والتصورات أو في الأعمال والتصرفات .. ثانياً : الالتزام بالإسلام وأحكامه التزاماً كاملاً .. يجعله محور الحياة، ومنطلق التفكير، وقاعدة التصور، ومصدر الحكم في كل قضية وموضوع .. ثالثاً : اعتبار الجهاد في سبيل اعلاء كلمة الله في الأرض هو الغاية الأساسية من الوجود .. وما يحتم هذا التصور من استعداد كامل للتضحية بكل شيء في سبيل هذه الغاية .. ومن قبيل النقد الذاتي البناء القول بأن المناهج والأساليب المعتمدة دون مستوى القدرة على تكوين شخصية إسلامية هذه ملامحها ومواصفاتها .. والواقع أن كل ما يمكن أن تقدمه هذه المناهج لا يعدو أن يكون قسطاً من الثقافة الإسلامية العامة والتوجيهات الروحية والخلقية، مما يجعلها دون القدرة على صياغة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0148.png"}, {"n": 149, "paras": ["الفرد المسلم الصياغة المنشودة ، التي تؤهله ليكون رجل العقيدة الذي يؤمن بها ويعيشها ، ويضحي بالنفيس والغالي من أجلها .. إن الغاية الأساسية من التربية والتكوين الإسلاميين ، تحقيق التفاعل بين الإسلام وبين الأفراد بحيث يتحقق من هذا التفاعل تجَريدهم من ذواتهم ، تجريدهم من القيم الارضية كلها.. تجريدهم من الاعتزاز بكل ما يعتز به من حطام وأهواء .. ليعتزوا بالحق وحده .. الحق مجرداً من أشخاصهم .. الحق متلبساً بذواتهم ولكنه متميز فيها تميزاً واضحاً ، بحيث تتبع ذواتهم الحق ، ولا تتبع اهواءهم أو مشاعرهم الشخصية ، وذلك بأن يتجردوا الله . يتجردوا له تجرداً خالصاً (۱) .. متطلبات التربية والتكوين : إن للتربية والتكوين الإسلامي متطلبات ينبغي توفرها لنجاح العملية .. وبغير هذه المتطلبات ستفشل كل محاولة في حقل التربية الإسلامية وسوف لا تتحقق ولادة الفرد المسلم الذى يمثل العمود الفقري في العمل الإسلامي برمته .. وفي رأيي أن أهم متطلبات التربية هي : أولاً : المنهج السليم : الذي يحقق إعداد الفرد المسلم والجيل المسلم .. المنهج الذي تتكامل فيه جوانب التربية كلها الفكرية والروحية والأخلاقية والحركية ، مما يحقق التكامل والتوازن في بناء الشخصية", "(۱) راجع كتاب : منهج التربية الاسلامية - لمحمد قطب -"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0149.png"}, {"n": 150, "paras": ["الإسلامية ، ويحول دون طغيان جانب من هذه الجوانب على الآخر حتى لا يؤدي هذا الطغيان إلى تشوه الشخصية وعدم تكاملها ..", "إن المنهج التي تحتاجه الحركة هو نفس المنهج الذي أخرج من متاهات الجاهلية خير أمة أخرجت للناس ، والذي يملك أن يخرج في كل زمان ومكان ، الجيل القائم على الحق ، المجاهد من أجله ، الذي لا يضره من خالفه حتى يأتي أمر الله ..", "وبغير هذا النمط من الناس لا يمكن للحركة الإسلامية أن تواجه الواقع الجاهلي وتحقق النصر عليه .. ( كتب عمر بن الخطاب رضي الله عنه خطاباً إلى عمرو بن العاص ، وقد استبطأ فتح مصر جاء فيه : أما بعد، فقد عجبت لابطائكم عن فتح مصر .. تقاتلونهم منذ سنتين .. وما ذاك إلا لما أحدثتم وأحببتم من الدنيا ما أحب عدوكم .. وان الله تبارك وتعالى لا ينصر قوماً إلا بصدق نياتهم ) وفي وصيته إلى سعد بن معاذ قائد المسلمين إلى فارس يقول : ( أما بعد : فإني أوصيك ومن معك من الأجناد بتقوى الله على كل حال .. فإن تقوى الله أفضل العدة على العدو وأقوى المكيدة في الحرب .. وأوصيك ومن معك من الأجناد بأن تكونوا أشد احتراساً من المعاصي منكم من عدوكم ، فإن ذنوب الجيش أخوف عليهم من عدوهم ، وإنما ينصر المسلمون بمعصية عدوهم الله ... ولولا ذلك لم تكن لنا بهم قوة ، لأن عددنا ليس كعددهم ولا عدتنا كعدتهم فإن استوينا في المعصية كان لهم الفضل علينا"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0150.png"}, {"n": 151, "paras": ["في القوة ، واعلموا أن عليكم في سيركم حفظة من الله يعلمون ما ما تفعلون ، فاستحيوا منهم ولا تعملوا بمعاصي الله وانتم في سبيله .. )", "ثانياً : القدوة الحسنة : .. وهي عامل أساسي وهام في نجاح عملية التربية .. إنه لا يكفي للداعية المربي أن يكون فقيهاً عالماً أو خطيباً لامعاً ، بل لا بد وان يكون فوق هذا ومعه تقياً ورعاً عاملاً بعلمه .. فإذا خالف العمل العلم منع الرشد وحجب الهدى وانعدم الاثر.. ورحم الله مالك بن دينار حيث يقول : ( إن العالم إذا لم يعمل بعلمه زات موعظته عن القلوب كما يزل القطر عن الصفاء ) .", "ثالثاً : البيئة الصالحة : .. ويتوقف نجاح التربية - كذلك - على مدى صلاح البيئة وتوفر العزلة الشعورية التي يتعين تهيئتها للعناصر المراد تربيتها وتكوينها .. وقد يكون أقرب إلى المستحيل نجاح عملية التربية هذه في مجتمعات جاهلية مقطوعة الصلة بالإسلام .. وحل هذه المشكلة مرهون بمدى إمكان عزل الحركة للعناصر الإسلامية ، وتهيئة المناخات والاجواء المناسبة لها وبخاصة أثناء مرحلة التكوين الأولى وقبل ندبها للمهام الحركية العامة . إن فكرة عزل العناصر الإسلامية عن البيئة الجاهلية في مراحل التكوين جديرة بالدراسة والتأمل .. كما أن التفكير والتأمل والبحث عن كيفية تحقيق هذا العزل أجدر .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0151.png"}, {"n": 152, "paras": ["إن عملية تكوين الشخصية الاسلامية لا يمكن أن تكون ناجحة النجاح المرجو المؤمل ما لم تتم في بيئة إسلامية لامكان فيها للمؤثرات الجاهلية .. والواقع الذي تعيشه الحركة الإسلامية اليوم لا يعطيها قوامة التوجيه أو يفردها بالتحكم في حياة الفرد المسلم ، وإنما يجعل هذا الفرد في بيئة مضطربة تتنازعه شتى المؤثرات والضغوط .. فإذا استطاعت الحركة أن تهيء لافرادها الجو الإسلامي ، إن في محيط الاسرة ، أو في نطاق العمل ، وأن تحول بينهم وبين التعايش العقيدي والخلقي مع المجتمع الجاهلي ، فانها بذلك تكون قد وقفت على أول الطريق الذي يضمن لها خلق روح التمرد في نفوس أفرادها ، وإعدادهم ليكونوا نواة الطليعة المباركة وأمل الإسلام العظيم .. ولنا عودة لهذا الموضوع في مكان آخر من هذا الكتاب .", "في العمل الحركي والمواجهة : وأما العامل الثاني الذي يكمن وراء بروز ظاهرة التكامل والتآكل في حياة الحركة الإسلامية المعاصرة فيعود إلى عدم وضوح الطريق وإلى التخبط في ميدان العمل وإلى السير الانفعالي غير المرتكز على رؤيا واضحة وتصور سليم ومتكامل للوسائل وللغايات والاهداف .. ويمكن تحديد أبرز معالم الانحراف في الحسم الحركي فيمايلي:", "١ - عدم وضوح الطريق الأقوم لإقامة الدولة الإسلامية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0152.png"}, {"n": 153, "paras": ["وتحقيق الانقلاب الإسلامي ..", "٢ - عفوية السير وعدم الالتزام حتى بما يوضع من مخططات ، مما كان يعرض في كثير من الاحيان إلى استنفاد الجهود والقوى في معارك جانبية وأعمال جزئية لا تخدم مصلحة الإسلام الحقيقية ..", "٣ - عدم تبني سياسة الأخذ بزمام المبادرة مما كان يجعل انفعال الحركة بالاحداث بطيئاً مما فوت ويفوت عليها كثيراً من الفرص والسوانح النفسية والزمية ..", "٤ - الضياع بين الالتزام بالخط الأصيل للعمل ألا وهو التبليغ ، وبين الانطلاق السياسي ومحاولة الاستفادة من كل الظروف ..", "٥ - عدم تبني أسلوب معين لاستلام الحكم الإسلامي ..", "٦ - المبالغة في الحذر من تبني استخدام القوة ( ابتداء أو انتهاء ) .", "٧ - عدم وضوح التنظيم الأحكم في الكيان الحركي ومن طواهر ذلك بروز الاسئلة التالية : هل القيادة فردية أم جماعية ؟ وهل الشورى ملزمة أم غير ملزمة ؟ وهل العمل سري أم علني ؟ وهل نحن معهد فكري أم تنظيم حركي وإذا كان الآخر فهل نحن في مستواه ؟ هذه الاسئلة وغيرها تحتاج إلى أجوبة، وأجوبة واضحة كيما تخرج الحركة من متاهات التخبط والضياع .. والاجوبة التي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0153.png"}, {"n": 154, "paras": ["تتبناها الحركة في هذا النطاق يجب أن تعتمد على قوة الدليل الشرعي وليس على الأهواء والعواطف ..", "إن من حق الإسلام على الحركة الإسلامية اليوم، وفي كل يوم، أن يكون تصورها لطبيعة العمل الإسلامي وفهمها له موافقاً غاية الموافقة لروح الخطة التي انتهجها أول تجمع حركي في تاريخ الإسلام .. ومن شأن هذا التصور أن يفرض على الحركة السير وفق الخط الأصيل الذي سلكته النبوة في مواجهة الواقع الجاهلي والتحضير لإقامة المجتمع المسلم .. ولم يكن من عواقب اختلاف التصور الحديث لطبيعة العمل الإسلامي وأهدافه إلا ضياع الجهود واستنفاد القوى فيما لا طائل تحته .. كما أدى التفريط في التبعية الحركية للجماعة الإسلامية الأولى وعدم الالتزام الفعلي الدقيق بتوجيهاتها فيما يتعلق بفن المواجهة الإسلامية الفردي والجماعي إلى انعطاف الخطى وبعدها في أكثر الأحيان عن المحور الأساسي والهدف الرئيسي المنشود ..", "لقد مر على الحركة الإسلامية حين من الدهر كانت كثير من الجهود تضيع في قضايا جانبية وشؤون آنية، لا ترتبط لا من قريب ولا من بعيد بالهدف البعيد الذي يفرض أن تفرد له الحركة كل قواها وإمكانياتها ..", "إن معرفة الحركة الإسلامية لأهدافها ولخط سيرها وطبيعته وخصائصه من شأنه أن يحول الخطى - كل الخطى - ويصب القوى", "- كل القوى - في هذا الاتجاه .. كما أن من شأنه أن يصون الجهود"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0154.png"}, {"n": 155, "paras": ["المبذولة من الضياع والهدر ، فضلاً عن أنه الطريق الأقصر لبلوغ الغاية وتحقيق الهدف ..", "إعادة تعبيد الناس لله : إن على الحركة الإسلامية أن تدرك أن مهمتها الرئيسية ينحصر في إعادة تعبيد الناس لربهم كأفراد ومجتمعات .. وهذه المهمة لا يمكن تحقيقها ما لم تقم للاسلام دولة تستمد حكمها وتشريعها منه ، وتعود في كافة شؤونها اليه ، وتسير في كل خطوة من خطاها على هديه القويم وصراطه المستقيم .. إن على الحركة الإسلامية حين تدرك أن مهمتها الأساسية هي إخضاع المجتمع الإنساني لحاكمية الله وعبوديته أن تبقى دفة سيرها محولة في هذا الاتجاه كائناً ما كانت الظروف .. إن قضايا المشاركة في تحرير البلاد تصبح من غير ضمان إسلامية مستقبلها كوأد الجهد تحت التراب . كما تصبح المشاركة في توحيد الشعوب والاقطار على غير الإسلام كتشييد بناء على غير أساس .. وبالتالي كنوع من أنواع التعايش مع الجاهلية .. وبهذا المقياس ستتغير نظرة الحركة إلى أمور كثيرة كانت فيما مضى تعطيها الأولوية من جهدها ووقتها .. إن الإسلام بحاجة ماسة إلى موطىء قدم يقدم فيها للبشرية نموذجاً عملياً للمجتمع المسلم ولما يحققه من عدالة ومساواة وأمن واستقرار ... وان الأفكار والمذاهب والفلسفات المادية التي غزت العالم في العصر الحديث ما كان لها أن تصل إلى ما وصلت"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0155.png"}, {"n": 156, "paras": ["اليه لو لم يكن لها في الأساس موطىء قدم واحدة .", "مجاهدون لا فلاسفة :", "ونقطة أخرى تجدر الإشارة اليها في هذا المقام - كذلك - وهي أن الحركة الإسلامية ينبغي أن تكون ( ثكنة ) لتخريج المجاهدين والأبطال قبل أن تكون معهداً فكرياً لنشر الثقافة والمفاهيم المجردة بين الناس .. إننا بحاجة إلى الوعي والعمق والحكمة مثل ما نحن بحاجة إلى الجرأة والتضحية والاقدام .. وإن طغيان مبدأ تحري السلامة والمبالغة فيه واتخاذه سياسة مضطردة في كل الأحوال والظروف وعلى كل صعيد لن تكون نتائجه إلا قتل روح التضحية في الأفراد وتحويل الحركة الإسلامية إلى مدرسة نظرية أو اتجاه فكري مجرد.", "إن القاعدة التي يجب أن تصدر عنها الحركة في هذا الشأن هي أن تكون مصلحة الإسلام فوق كل اعتبار ، وحيثما تحققت مصلحة الإسلام وجب الاقدام مهما كلف ذلك من تضحيات ..", "إن الأصل الذي يجب أن تعتمده الحركة في تقييم المواقف والمعارك والمواجهات هو الاستيعاب الصحيح لطبيعة المعركة وخصائصها ، وتشخيص أبعادها وإنعكاساتها وردود فعلها ، كل ذلك في ضوء التحسب الكامل للمفاجآت والمضاعفات الطارئة التي قد تقع من غير توقع أو حسبان ..", "ومن التهور والخفة خوض أي معركة - مهما كانت جانبية وصغيرة - من غير تصور صحيح لها وإعداد الكفايات اللازمة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0156.png"}, {"n": 157, "paras": ["لخوضها .. لأن قبول الارتجال في كل قضية سيعود على الارتجال في كل قضية وهو مغامرة بالإسلام وعلى حساب الإسلام وهذا يدخل في حكم ما حذرنا منه ونهينا عنه .. أما إذا توفر الاستعداد الكامل في نطاق القدرة المستطاعة وفي ضوء التصور الصحيح لطبيعة المعركة وحاجاتها ومتطلباتها أصبح خوضها واجبا والهروب منها جبنا وتخاذلاً .. وما كان المؤمنون يوماً جبناء ولا متخاذلين . إن من واجب الحركة الإسلامية كيما تكون على مستوى المسؤولية أن تعيد النظر في منطلقاتها الأساسية .. وفي تنظيماتها الداخلية ، وفي مناهجها التربوية وخط سيرها ، ووسائل عملها واسلوب مواجهتها، أن تعرف ما هو دورها في المجتمع، وماهي مبررات وجودها .. ولا بأس بعد ذلك أن تبدأ ولو من نقطة الصفر .. . إن الحركة الإسلامية في كل مكان .. وإن العاملين في الحقل الإسلامي حيثما كانوا .. مدعوون جميعاً - كل في نطاق استطاعته وقدرته - للإسهام في تطوير العمل الإسلامي المعاصر والخروج به من دوامة التكامل والتآكل ، والبلوغ به المستوى المطلوب وعياً وإعداداً وتنظيماً وتخطيطاً ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0157.png"}, {"n": 158, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0158.png"}, {"n": 159, "paras": ["مظاهر وأسباب تشوه الشخصية الإسلامية الحديثة", "• تعريف الشخصية الاسلامية .", "• تعريف العقلية الاسلامية .", "• تعريف النفسية الاسلامية .", "• ملامح التشوه :", "- ضعف الورع .", "- التأثر بمظاهر الحياة .", "- التراجع أمام الضغوط .", "- الخوف من المجتمع .", "• مناقشة أسباب التشوه .", "- فساد مناهج التربية .", "- فساد مقاصد التربية .", "- فساد المربي ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0159.png"}, {"n": 160, "paras": ["لا أحدثني مبالغاً إذا قلت إن الشخصية الإسلامية الحديثة تختلف اختلافاً كبيراً عن الشخصية الإسلامية التي عاشت في صدر الإسلام ، والتي كان أصحابها في الحقيقة صورة معبرة عن شتى مجالات حياتهم .. وقبل الدخول في مناقشة أسباب التشوه الذي أصاب الشخصية الإسلامية الحديثة ، لا بد من تعريف الشخصية أولا بشكلها التجريدي ، ومن ثم تعريفها بمواصفاتها الإسلامية، وبيان مظاهر التشوه التي أصيبت بها هذه الشخصية في العصر الحاضر ..", "تعريف الشخصية : كل شخصية تتكون من عقلية ونفسية ، ولا علاقة للشكل والزي والقامة في ذلك كما قد يتوهم البعض .. فكم من أناس لهم أجسام ضخمة وقامات مديدة وأشكال حسنة وهم ضعاف الشخصية .. وكم من اناس قصار القامات قبيحي الاشكال هزيلي الاجسام ويتمتعون بشخصيات فذة .. ولا أنكر أن تكون هذه المظاهر ( الجسمية ) إضافات مساعدة لقوة الشخصية بشرط توفر العوامل الاساسية في تكوين الشخصية .. كما توفر ذلك ( لطالوت ) حيث يشير القرآن الكريم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0160.png"}, {"n": 161, "paras": ["إلى ذلك فيقول : ﴿ إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم ، والله يؤتي ملكه من يشاء ، والله واسع عليم ﴾ .", "تعريف الشخصية الاسلامية : وإذا كانت الشخصية تتكون من عقلية ونفسية . فالشخصية الاسلامية بالتالي تتكون من العقلية الاسلامية والنفسية الاسلامية ..", "فماذا نعني أولاً بالعقلية الاسلامية ، ثم ماذا نعني بالنفسية الاسلامية ؟", "نعني بالعقلية الاسلامية ، العقلية التي تفكر وتحلل وتحكم على أساس الإسلام ، وعلى أساس نظرته الكلية للكون والانسان والحياة ..", "العقلية التي تصدر في كل شأن من الشؤون عن الإسلام ، سواء في شؤون العقيدة أم في شؤون التشريع ، أم في شؤون الاخلاق .. وسواء في نطاق التصرفات الخاصة أو في نطاق التصرفات العامة ..", "العقلية التي تفسر الاحداث - كل الاحداث - وتحللها وتحكم عليها من وجهة نظر الإسلام ..", "وأساس العقلية الاسلامية ومنطلقها الأول ، الإيمان بوجود الله وسائر الغيبيات الاخرى ، وبالتالي رد القول بمادية الحياة ، واعتبار حق التشريع والحاكمية لله لا للناس ..", "ونعني بالنفسية الاسلامية ، النفسية التي تقوم بتصريف الغرائز"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0161.png"}, {"n": 162, "paras": ["والميول وفق أحكام الشرع .. النفسية التي تستقي الإسلام وتلتزم بما يفتي به وتتقيد ، فلا يتحكم بها هوى أو تقودها شهوة أو تستبد بها مصلحة ..", "والنفسية الإسلامية، هي بالتالي التجسيد الفعلي والتطبيق العملي والترجمة الحسية للعقلية الإسلامية .. إنها الاثر الفعلي للايمان ، مصداقاً لقوله ﷺ : « ليس الإيمان بالتمني ولا بالتحلي ولكن ما وقر في القلب وصدقه العمل ».", "من هنا يتبين أن الإسلام يكوّن الانسان المسلم ويكون شخصيته الإسلامية بتثبيت العقيدة الإسلامية والشريعة الإسلامية في تفكيره، أي يجعل تفكيره إسلامياً حتى تتكون لديه العقلية الإسلامية ، ثم ببيان حدود الاشباعات والميول وبدفعه إلى الالتزام بها ، وبترويضه على ذلك سواء بالتكاليف العبادية أو بالتربية الروحية حتى تتكون لديه النفسية الإسلامية، وحتى يصبح بعقليته الإسلامية ونفسيته الإسلامية ذا شخصية إسلامية ، أي يصبح إنساناً مسلماً يفقه معنى الحياة ورسالته في الحياة .", "يفهم أن الحياة طريق الآخرة ، وأن ليس للانسان إلا ما سعى ، وأن سعيه سوف يرى .. والآخرة خير وابقى ، وإنها لهي الحيوان لو كانوا يعلمون ..", "يفهم هذا، فيفرغ قلبه من هموم الدنيا وحظوظ النفس ويلزم حب الله والعمل لآخرته .. فلا تكون الدنيا أكبر همه ولا محور تفكيره ولا شغله الشاغل، وإنما يكون أكبر همه ومحور تفكيره."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0162.png"}, {"n": 163, "paras": ["وشغله الشاغل كسب رضاء الله بالتزام أوامره ، وبالنزول عند أحكامه ، وبالجهاد في سبيله .. فهو يدرك أن الدنيا إلى زوال وفناء ولو كانت باقيه لبقيت لمن كانوا قبله ﴿ انما الحياة الدنيا لعب ولهو وزينة وتفاخر بينكم وتكاثر في الأموال والاولاد ، كمثل غيث أعجب الكفار نباته ثم يهيج فتراه مصفراً ، ثم يكون حطاماً وفي الآخرة عذاب شديد ، ومغفرة من الله ورضوان وما الحياة الدنيا إلا متاع الغرور ﴾ الحديد .", "تشوه الشخصية الاسلامية الحديثة :", "والمدقق المقارن بين الشخصية الإسلامية الأولى والشخصية الإسلامية الحديثة يرى مظاهر تشوه واضحة المعالم في الشخصية الإسلامية الحديثة .. وأبرز مظاهر التشوه هذه هي ما يلي :", "★ ضعف الورع بشكل عام : في حين كان صاحب الشخصية الإسلامية الأولى شديد المراقبة لله ، شديد التورع عن محارمه .. وكانت قاعدته في ذلك ، قوله ﷺ : « دع ما يريبك إلى ما لا يريبك »(١) . وقوله : « لا يبلغ العبد أن يكون من المتقين حتى يدع ما لا بأس به حذراً مما به بأس (٣) » .. ويروى عن عبدالله ابن دينار إنه قال : « خرجت مع عمر بن الخطاب رضي الله عنه", "(١) حديث صحيح رواه أحمد والنسائي والطبراني .", "(٢) « « « الترمذي وابن ماحه", "- ١٦١ - الدعوة (١١)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0163.png"}, {"n": 164, "paras": ["إلى مكة ، فعرسنا في بعض الطريق ، فانحدر إليه راع من الجبل فقال له : يا راعي ، بعني شاة من هذا الغنم .. فقال : إنني مملوك .. فقال : قل لسيدك أكلها الذئب . قال : فأين الله ؟ فبكى عمر، ثم غدا إلى المملوك فاشتراه من مولاه فاعتقه وقال : أعتقتك في الدنيا هذه الكلمة ، فأرجو أن تعتقك في الآخرة .. » ★ التأثر بمظاهر الدنيا: في حين كانت الدنيا لا تساوي لدى المسلم الأول جناح بعوضة .. ينظر اليها من خلال قوله تعالى : ﴿ وما هذه الحياة الدنيا إلا لهو ولعب وإن الدار الآخرة لهي الحيوان لو كانوا يعلمون ﴾ . ومن خلال قوله ﷺ « الدنيا دار من لا دار له ، ولها يجمع من لا عقل له » . إن انمساخ قيمة الدنيا في قلوب المسلمين الأولين هو الذي صيرهم أبطالاً وجعلهم عمالقة وجعل الدنيا تخضع لهم ، وجعل خصومهم يتناقلون أخبارهم فيقولون ( رأينا قوماً الموت أحب إلى أحدهم من الحياة ، والتواضع أحب إلى أحدهم من الرفعة ، ليس لأحد منهم في الدنيا رغبة ولا نهمة .. ) ★ الخوف على الحياة والرزق : في حين كان الأولون لا يخافون إلا الله ، يقولون الحق ولا يخشون في الله لومة لائم .. ويمنعهم خوف على حياة ورزق من الصدع بالحق والأمر بالمعروف والنهي عن المنكر .. إن الدعوة إلى الحق ، ومحاربة الباطل ، وإنكار المنكر ، والنصح للناس هي جوهر رسالة المسلم فإذا لم ينهض بها خوفاً من المجتمع كان ضعيف الإيمان بعيداً عن الله ، باداً عما أمر الله في كتابه ( وقل الحق من ربكم فمن شاء فليؤمن"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0164.png"}, {"n": 165, "paras": ["ومن شاء فليكفر ) والعصر إن الإنسان لفي خسر إلا الذين آمنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر وناداً عن أمر الرسول ﷺ « أمرت أن أقول الحق ولو كان مرا » « كنا نسمع أن الرجل يتعلق بالرجل يوم القيامة وهو لا يعرفه ، فيقول له ؟ مالك الي . وما بيني وبينك معرفة ؟ فيقول : كنت تراني على الخطأ وعلى المنكر ولا تنهاني ؟ )", "مناقشة أسباب هذا التشوه : ولتتشوه الشخصية الإسلامية الحديثة أسباب متعددة ، أبرزها أن البيئة التي تجري فيها عملية تكوين الشخصية هذه بيئة غير إسلامية ، ولها مؤثراتها الحتمية على كل من يعيش فيها بقصد وبغير قصد ، ولما كان هذا العامل من العوامل (ال قهرية) التي جرت مناقشتها في مكان ما من هذا الكتاب ، فقد وجدنا أن نتجاوزها إلى سواها من العوامل الواقعة في نطاق ( إمكانية الحركة ) في المرحلة الحاضرة ..", "١ - فساد المناهج : إن المناهج المعتمدة دون القدرة على تكوين الشخصية الإسلامية .. وما يمكن أن تقدمه هذه المناهج لا يعدو أن يكون قسطاً يسيراً من الثقافة الإسلامية الفكرية المجردة، وبهذه لا يمكن بحال أن تحقق صياغة الشخصية الإسلامية المطلوبة .. إن نوعية العلم ونوعية التوجيه يلعبان دوراً أساسياً وحساساً"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0165.png"}, {"n": 166, "paras": ["في نطاق التربية والتكوين .. وسوء الاختيار قد يضر بدل أن ينفع .. وصدق رسول الله ﷺ حيث يقول : « إن من العلم جهلاً (١) » وإلى هذا المعنى أشار عيسى عليه السلام بقوله : « ما أكثر الشجر وليس كله بمثمر، وما أكثر الثمر وليس كله بطيب، وما أكثر العلوم وليس كلها بنافع » ويروى أن إعرابياً جاء إلى الرسول ﷺ وسأله أن يعلمه من غرائب العلم فقال له الرسول ﷺ : « وماذا صنعت في رأس العلم ؟ » فقال : وما رأس العلم ؟ قال ﷺ : « هل عرفت الرب تعالى ؟ » قال : نعم .. قال ؟ « فما صنعت في حقه ؟ » قال : ما شاء الله .. فقال الرسول ﷺ : « هل عرفت الموت ؟» قال : نعم .. قال : « فما أعددت له ؟ » قال : ما شاء الله .. قال ﷺ : « إذهب فاحكم ما هناك ثم تعال نعلمك من غرائب العلم (٢) » وسئل ﷺ : أي الأعمال أفضل ؟ فقال : « العلم بالله عز وجل » فقيل : أي العلم تريد ؟ فقال : « العلم بالله سبحانه » فقيل له : نسأل عن العمل وتجيب عن العلم ؟ فقال عليه السلام : « إن قليل العمل ينفع مع العلم بالله، وإن كثير العمل لا ينفع مع الجهل بالله » .", "يقول الإمام الغزالي في الأحياء « العلم بالله نور الأبصار من الظلم ، وقوة الأبدان من الضعف ، يبلغ به العبد منازل الابرار", "(١) رواه ابو داود .", "(٢) رواه ابن السني وابو نعيم في كتاب الرياضة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0166.png"}, {"n": 167, "paras": ["والدرجات العلى ، التفكر فيه يعدل بالصيام .. ومدارسته بالقيام .. به يطاع الله عز وجل وبه يعبد ، وبه يوحد وبه يمجد ، وبه يتورع ، وبه توصل الأرحام ، وبه يعرف الحلال والحرام ، وهو إمام والعمل تابعه ، يلهمه السعداء ويحرمه الأشقياء ».", "٢ - فساد المقاصد : إن سلامة المقاصد من أبرز عوامل نجاح وأثمار التربية .. فإذا قصد من تعلم الإسلام المباهاة والمفاخرة وحصول الاعجاب من الناس ، انعدمت الفائدة المرجوة ، وأصبح العلم وزراً على صاحبه .. وقد استعاذ الرسول ﷺ : « من علم لا ينفع وقلب لا يخشع ودعاء لا يسمع (١) » وقال ﷺ : ( إذا أتى علي يوم لا ازداد فيه علماً يقربني إلى الله عز وجل فلا بورك في طلوع شمس ذلك اليوم » وقال : « من طلب العلم ليجاري به العلماء ويماري به السفهاء ويصرف به وجوه الناس اليه أدخله الله النار (٢) » . وقال : « من تعلم علماً لغير الله ، او اراد به غير الله فليتبوأ مقعده من النار (٣) » .", "٣ - فساد المربي : والعامل الثالث الكامن وراء تشوه الشخصية الإسلامية", "(١) من حديث رواه مسلم والترمذي والنسائي .", "(٢) رواه الترمذي ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0167.png"}, {"n": 168, "paras": ["هو ضمور القدوة الحسنة وفساد المربي نفسه .. إن من الخطأ الشائع في نطاق التربية والتعليم ان يظن ان في إمكان اي إنسان اوتي نصيباً من العلم والثقافة الإسلامية واوتي مقدرة على الكلام والتحدث ان يكون مربياً ناجحاً ، وان يعهد اليه بتربية الآخرين .. ان لنجاح التربية متطلبات يجب توفرها في شخصية المربي . فالعلم لوحده لا يكفي ، والقدرات الكلامية لوحدها لا تكفي .. لأن المربي يجب ان يكون اولاً وآخراً القدوة الحسنة لمن يقوم على تربيتهم .. وصدق علي بن ابي طالب حيث يقول : « من نصب نفسه إماماً فليبدأ بتعليم نفسه قبل تعليم غيره ، وليكن تهذيبه بسيرته قبل تهذيبه بلسانه ، ومعلم نفسه ومهذبها احق بالإجلال من معلم الناس ومهذبهم » . فالمربي هو الذي يعرف كيف يعطي حاجة تلامذته من التوجيه كما ونوعاً ، يعظهم من حيث يسمعون ويتعلمون .. يتابعهم بالموعظة الحسنة والكلمة المؤثرة .. مهمته فيهم ليست مهمة ( تسميع ) لما يحفظون ، او ( تفسير ) لما يجهلون ، وإنما مهمة غرس الخير في نفوسهم وصياغتهم على الإسلام تماماً كما يصيغ ( الصائغ ) من الذهب الخام الحلي الجميلة المتنوعة .. والمربي هو الذي يؤثر بلسان حاله قبل ان يؤثر بلسان مقاله، ولا يخالف الناس إلى ما ينهاهم عنه .. يقول ابن مسعود: « سيأتي على الناس زمان تملح فيه عذوبة القلوب فلا ينتفع بالعلم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0168.png"}, {"n": 169, "paras": ["يومئذ عالمه ولا متعلمه ، فتكون قلوب علمائهم مثل السباخ من ذوات الملح ينزل عليها قطر السماء فلا يوجد لها عذوبة .. وذلك إذا مالت قلوب العلماء إلى حب الدنيا وإيثارها على الآخرة ، فعند ذلك يسلبها الله تعالى ينابيع الحكمة ويطفىء مصابيح الهدى من قلوبهم ، فيخبرك عالمهم حين تلقاه إنه يخشى الله بلسانه والفجور ظاهر في عمله ، فما أخصب الألسن يومئذ وما أجدب القلوب ؟ فوالله الذي لا إله إلا هو ما ذلك إلا لأن المعلمين علموا لغير الله تعالى ، والمتعلمين تعلموا لغير الله تعالى .. وصدق رسول الله ﷺ حيث يقول : « العلماء ثلاثة : رجل عاش بعلمه وعاش الناس به ، ورجل عاش الناس به ، وأهلك نفسه ، ورجل عاش بعلمه ولم يعش به غيره ».", "الخلاصة : إن الحركة الإسلامية حين تحسن اختيار ( المنهج ) اللازم لتربية العناصر المراد تربيتها بحيث تتوفر في مواد هذا المنهج فاعلية التأثير والتفاعل ، وحين تتوفر ( سلامة المقاصد ) لدى المربين والمتربين والمعلمين والمتعلمين ، وعندما يتحقق عزل هؤلاء عزلا شعورياً عن كل مؤثرات المجتمع الجاهلي ، عند ذلك يمكن أن تتحقق ولادة الشخصية الإسلامية كما يريدها الإسلام .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0169.png"}, {"n": 170, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0170.png"}, {"n": 171, "paras": ["من أمراضنا التنظيمية", ". الشورى الملزمة . القيادة الجماعية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0171.png"}, {"n": 172, "paras": ["تعتبر الشورى من أهم المرتكزات التي يقوم عليها نظام الحكم في الإسلام .. ولقد أساء إلى مفهوم الشورى بقصد وبغير قصد كثيرون من الباحثين والكتاب قديماً وحديثاً ، حيث خرجوا به عن التصور الأصيل المتوافق مع روح الدين وأصول التشريع .. بل إن بعض المحدثين منهم أعطوا الشورى مفهوماً كمفهوم الديمقراطية مما يعتبر إنحدار بالفكر الإسلامي، وإنحرافاً عن حقيقة معنى الشورى في النظام الإسلامي .. إن الشورى غير الديمقراطية تماماً .. وهي تخالفها من وجوه عدة .. فالديمقراطية كلمة يونانية تعني ( حاكمية الشعب وسيادته في الدولة الديمقراطية).. وهي تجعل الشعب مصدر السلطات.. فهو الذي يشرع القوانين ويسن الدساتير .. أما الشورى في الإسلام فإنها لا تعدو أن تكون استطلاع رأي فرد أو فريق من الناس في تفسير حكم شرعي أو فهمه أو اجتهاد في أمر من الأمور في ضوء التشريع الإسلامي وفي حدود أصوله وقواعده .. إن ( الشعب ) في النظم الديمقراطية هو الذي يحكم نفسه"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0172.png"}, {"n": 173, "paras": ["بنظام يصنعه بنفسه .. أما في الإسلام فإن الشعب يحكم بنظام ( منزل ) لا يملك تعديله أو تبديله كائناً ما كانت الظروف والأحوال .. والنظام الديمقراطي يجعل الأكثرية صاحبة الصلاحية في نقض الأمور وإبرامها بصرف النظر عن أخطائها وصوابها .. بينما تتقيد الشورى بمبدأ شرعية المقررات والتصرفات دونما كثرة المؤيدين لها أو قلتهم .. (فالكيف) في الشورى الإسلامية هو الذي تستهدفه المشورة وتتقيد به للوصول إلى الأسلم والأقوم ولو كان لفرد واحد في الجماعة كلها ..", "الشورى من حيث المبدأ : إن الشورى من حيث المبدأ سمة أصيلة من سمات النظام الإسلامي .. ووجوبها وفرضيتها قرآنية ونبوية وتاريخية كثيرة منها قوله تعالى : ﴿ وشاورهم في الأمر فإذا عزمت فتوكل على إن الله يحب المتوكلين ﴾ . وقوله : ﴿ وأمرهم شورى بينهم ﴾ . ومنها قوله ﷺ : «ما تشاور قوم قط إلا هدوا إلى رشد أمرهم». وقوله : « ما خاب من استخار ولا ندم من استشار ولا عال من اقتصد (١) ) .. ومن أجل ذلك أجمع المسلمون على ان الشورى", "(١) حديث حسن رواه الطبراني في الأوسط ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0173.png"}, {"n": 174, "paras": ["في كل ما لم يثبت نص ملزم فيه من كتاب أو سنة أو أساس تشريعي دائم لا يجوز إهماله .. ومبدأ الشورى هذا ليس نظرية من النظريات التقليدية ذات الطابع الدعائي الرمزي ، بل إنها على العكس من هذا تماماً .. فالوقائع التطبيقية لمبدأ الشورى كانت سمة بارزة على مدار التاريخ الإسلامي ..", "الشورى من حيث التطبيق : وإذا كانت الشورى مبدأ صريحاً من مبادى التشريع الإسلامي وسمة أصيلة من سمات النظام الإسلامي إلا أن الشكل الذي يستلزمه تطبيق هذا المبدأ موضع خلاف وهو موضوع البحث .. ويتركز الخلاف بصورة أساسية حول الشكل الذي يجري فيه تطبيق الشورى من حيث كونها ملزمة أم غير ملزمة في نتيجتها .. وتمهيداً للوصول إلى جواب في هذا الشأن لا بد من معرفة مفهوم وشكل القيادة أو الرئاسة في الإسلام .. هل الأمير أو صاحب الصلاحية فرد أم مجموعة أفراد ؟ وهل القيادة فردية أم جماعية ؟", "القيادة في الاسلام فردية : والحقيقة التي لا لبس فيها هو ان القائد في النظام الإسلامي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0174.png"}, {"n": 175, "paras": ["هو صاحب الصلاحية في تدبير شؤون الأمة وتصريف أمورها.. وهو وإن كان ملزماً بالاستشارة واستطلاع آراء أهل الحل والعقد في الأمة إلا أنه ليس ملزماً باتباع الأكثرية في كافة الشؤون والأحوال .. وتفسير آية الشورى واضح الدلالة على ان القول الفصل بعد المشورة إنما يعود إلى القائد صاحب الصلاحية وليس إلى الأكثرية، وهذا صريح قوله تعالى : ﴿ وشاورهم في الأمر فإذا عزمت فتوكل على الله ﴾.. وليس مفهوم ( الفردية ) في قيادة الإسلام كمفهوم الفردية في في النظم الديكتاتورية .. فالقائد وإن كان يمارس صلاحياته كفرد غير إنه مقيد بتشريع ليس له أن يتقدم عليه أو يتأخر عنه، بينما يتصرف القائد في النظم الديكتاتورية على هواه من غير ضوابط ولا قيود .. إن مركز القائد في الإسلام هو مركز النائب عن الأمة لا المتسلط عليها، والمنفذ لأمر الله لا المستبد بها .. فهو الذي ينوب عن الأمة في الحكم وفي تنفيذ شرع الله .. بل هو الذي يضع الأحكام الشرعية موضع التنفيذ بل ويجعلها قانوناً .. وبذلك تجب طاعته ما تقيد بالشرع والتزم حدوده .. أما إذا حاد عن الشرع فلا طاعة له على الأمة بل واجب عليها عصيانه وخلعه.. ولقد خطب ابو بكر الصديق رضي الله عنه حين ولي الخلافة فقال : « ايها الناس قد وليت عليكم ولست بخيركم ، فإن احسنت"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0175.png"}, {"n": 176, "paras": ["فاعينوني ، وإن اسأت فقوموني ، الصدق امانة والكذب خيانة والضعيف فيكم قوي عندي حتى آخذ له حقه ، والقوي فيكم ضعيف عندي حتى آخذ الحق منه إن شاء الله . لا يدع احدكم الجهاد فإنه لا يدعه قوم إلا ضربهم الله بالذل. اطيعوني ما اطعت الله ورسوله ، فإذا عصيت فلا طاعة لي عليكم، قوموا إلى صلاتكم يرحمكم الله » وخطب عمر بن العزيز حين ولي الخلافة ، فبين ان عمله في رئاسة الدولة تنفيذي لا تشريعي ، فقال: «ايها الناس.. إنه لا كتاب بعد القرآن، ولا نبي بعد محمد ﷺ . الا واني لست بخيركم بقاض ولكني منفذ .. ولست بمبتدع ولكني متبع .. ولست ولكني اثقلكم حملاً ، وان الرجل الهارب من الإمام الظالم ليس بظلم . الا لا طاعة لمخلوق في معصية الخالق » ..", "من هنا يتبين ان البيعة للقائد في الإسلام إنما تقوم على تنفيذ كتاب الله وسنة رسول الله ﷺ ، وبذلك تكون القيادة في النظام الإسلامي لفرد لا لمجموعة من الأفراد ، ومقيدة وليست مطلقة ..", "مساوىء القيادة الجماعية : تعني القيادة الجماعية تركيز السلطات التشريعية والتنفيذية في ايدي مجموعة من الناس بحيث يجري تصريفها وممارستها وتقريرها والبت بها بشكل جماعي اي وفق ما تراه الاكثرية ، وبحيث تنحصر صلاحيات من يسمى قائداً في امور شكلية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0176.png"}, {"n": 177, "paras": ["وادارية بحتة وتنفيذية ضيقة احياناً ، وبحيث تكون صلاحيات ( المسؤول الأول ) على قدم المساواة تقريباً مع صلاحيات اعضاء القيادة .. ويبرر الآخذون بنظام القيادة الجماعية وجهة نظرهم فيما يلي:", "١ - صون الجماعة المسلمة من خطر طغيان الاعتبارات الشخصية ..", "٢ - تخفيض نسبة الاخطاء التي من شأنها ان تتكاثر - عند حد زعمهم - إذا كانت القيادة فردية .", "٣ - عدم توفر قادة افذاذ في كل حين لملء هذا المكان الحساس على الوجه الاكمل . هذا فضلاً عن ان هؤلاء يحاولون إيجاد مبررات شرعية لآرائهم بتحميل بعض الآيات والأحاديث والأحداث التاريخية من التفسيرات والتأويلات ما لا يتفق والمفهوم الإسلامي الأصيل لشكل القيادة في الإسلام ولمعنى الشورى والطاعة والجندية الإسلامية .. ويكفي القيادة الجماعية سوأ انها ليست من الإسلام ولا تتفق مع طبيعته التشريعية وشواهده التاريخية. وهي فضلاً عن كل هذا وذاك فيها كثير من المثالب والعيوب ولها كثير من السيئات والمضار نذكر منها على سبيل المثال ما يلي : أ - من مساوىء القيادة الجماعية انها تساعد على ضياع المسؤوليات ، وعلى إضعاف السلطة التنفيذية . وإناطة المسؤولية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0177.png"}, {"n": 178, "paras": ["بشخص القائد يعطي الجماعة طابعاً حركياً .. ب - مسؤولية القائد في الإسلام ليست شكلية ولا تقليدية ولا رمزية .. بل إن الإسلام اعتبره الطاقة المحركة والقوة الدافعة في حياة الجماعة المسلمة .. بينما تكرس القيادة الجماعية) شكلية القيادة ورمزيتها وتجعلها في مستوى واحد مع مسؤوليات المشتركين في القيادة الجماعية .. ج كذلك يصطدم منطوق القيادة الجماعية مع مفهوم الطاعة .. فالطاعة في الإسلام لفرد واحد وهو ( الامير ) وليست لمجموعة من الأفراد .. فكيف يمكن أن تكون معصية الأمير من معصية الله - كما جاء في الحديث الصحيح - إذا كانت القيادة جماعية وصلاحية القائد كصلاحية معاونيه ؟ د - ومن مضار القيادة الجماعية إنها معيقة للسير ، مبددة للطاقات والاوقات، لأن ارتباط كل صغيرة وكبيرة برأي مجموعة من الناس سيؤدي حتماً إلى شلل الأعمال ، في حين أن إناطتها بشخص القائد يعين على سرعة حلها وسهولة تصريفها ، والله أعلم ..", "الشورى غير ملزمة بنتيجتها : إن توسيع صلاحيات الأمير أو القائد في الإسلام لا تعني كما قلنا - إنه مطلق التصرف كما قد يتوهم البعض.. وللوصول إلى جواب حاسم هنا يتحتم معرفة نوعية الآراء الموجودة وكيف ينبغي للقائد أن يتصرف حيال كل منها .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0178.png"}, {"n": 179, "paras": ["إن الآراء الموجودة كل الآراء لا تعدوا أن تكون واحدة من ثلاثة : أولاً : فهي إما أن تكون حكماً شرعياً فيه نص واضح ، فليس للقائد أو الأمير حيال ذلك إلا التنفيذ .. ثانياً : أو أن تكون حكماً شرعياً خلافياً ويتقيد تصرف القائد حيال هذا النوع من الآراء بقوة الدليل الذي يمكن الوصول اليه عن طريق المجتهدين من أهل الحل والعقد .. ثالثاً : أو أن يكون رأياً في موضوع طارىء، كرسم سياسة أو تحديد علاقة أو ما شابه ذلك ، وللقائد حيال هذا النوع من الآراء أن يرجح جانب الصواب بعد الاستشارة بصرف النظر عن موقف الاكثرية أو الاقلية .. فالرسول ﷺ خرج بالمسلمين من المدينة يوم بدر والمسلمون كارهون للخروج : ﴿يجادلونك في الحق بعدما تبين كأنما يساقون إلى الموت وهم ينظرون﴾ . وهو الذي استصوب رأي الحباب بن المنذر في تغيير الموقع العسكري من غير الرجوع إلى رأي الآخرين . وهو الذي استصوب رأي سعد بن معاذ في مسألة بناء العريش ورأي أبي بكر في مصير اسرى بدر .. وهو الذي استعمل ابا لبابة على المدينة وعمر بن ام مكتوم على الصلاة ودفع اللواء إلى مصعب بن عمير كل ذلك من غير أن يرجع الى رأي الاكثرية أو الاقلية ..", "- ١٧٧ - الدعرة (١٢)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0179.png"}, {"n": 180, "paras": ["والرسول ﷺ بقي مصراً على الخروج لملاقاة المشركين يوم أحد بالرغم من تراجع المسلمين عن رأيهم في الخروج ، وقال لهم قولته المشهورة: «ما كان لنبي لبس لأمته أن يضعها حتى يقاتل» . ولقد درج المسلمون جميعاً بعد عصر النبوة على نفس الطريق .. وقد كان القائد أو الأمين يقرر السياسة ويرسل الوفود ويعين الولاة ويعزلهم ويجهز الجيوش ويخوض الحروب ، كل ذلك من غير التزام برأي أكثرية أو أقلية وإنما بما كان يستصوبه هو وترتاح اليه نفسه هو بعد استمزاج الآراء وأخذ المشورة ..", "فأبو بكر رضي الله عنه أنفذ جيش المسلمين إلى ( الشام ) بالرغم من معارضة كبار الصحابة لذلك وعلى رأسهم عمر ابن الخطاب الذي قال لأبي بكر ( كيف ترسل هذا الجيش والعرب قد اضطربت عليك ) . قال أبو بكر : « والله لو لعبت الكلاب بخلاخيل نساء المدينة ما رددت جيشاً أنفذه رسول الله » . وحين عزم أبو بكر على قتال المرتدين وقال له عمر وغيره : ( إذا منعك العرب الزكاة فاصبر عليهم ) . قال رضي الله عنه : ( والله لاقاتلنهم ما استمسك السيف بيدي ) . وحين سألوه قائلين : « ومع من تقاتلهم ؟ » قال : « وحدي حتى تنفذ سالفتي أي تقطع عنقي ..", "واكتفي هنا بهذا القدر من الشواهد التاريخية التي سيقت على سبيل المثال لا الحصر للتأكيد على ان صاحب الصلاحية لا بد وان يكون فرداً ولا يجوز أن يكون أكثر من ذلك .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0180.png"}, {"n": 181, "paras": ["لأن واقع الصواب يحتم أن يكون المرجح واحداً ولو ترك الترجيح لأكثر من واحد فلا بد وأن يختلفوا . واختلافهم سيضطرهم للرجوع إلى التحكيم . والذي يرجح التحكيم عادة واحد .. فإعطاء القائد صلاحية الترجيح من الأساس يصبح أفضل وأسلم ومن باب أولى .. والله أعلم ..", "مواصفات القيادة وفلسفة الطاعة : ونقطة أخرى أود أن أشير اليها كذلك في معرض الكلام عن مفهوم القيادة أو الإمارة وشكلها ومواصفاتها في الإسلام ، وهي ان الإسلام حين قرر أن الأمير يطاع بالمعروف ، وإنه طاعته من طاعة الله ومعصيته من معصية الله ، وإنه لا بد لكل جماعة من أمير فرد .. أقول حين قرر الإسلام ذلك لم يشر لا من قريب ولا من بعيد إلى أن القائد حق يطاع يجب أن يكون من أفذاذ الرجال وأكثرهم علماً وأوسعهم جاهاً وأقواهم شخصية . وإنه إذا اختل شرط من هذه الشروط بطل وجوب طاعته وجاز عندئذ معصيته أو استبدال الفردية بالجماعية ؟", "بل إن مفهوم الإسلام معاكس لهذا التصور - المنحرف - تماماً ، حيث أوجب الطاعة والخضوع للقائد كائناً من كان ولو كان من دون الناس في كل شيء طالما إنهم ارتضوه أو ارتضته الأكثرية قائداً عليها وأميراً لها .. ومن ذلك قوله ﷺ : « إسمعوا واطيعوا ولو تأمر عليكم عبد حبشي رأسه"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0181.png"}, {"n": 182, "paras": ["كالزبيبة (١) وقوله: « المسلمون تتكافأ دماؤهم ويسعى بذمتهم أدناهم وهم يد على من سواهم ». ولقد برزت تلكم المعاني في حوادث متعددة في التاريخ الإسلامي ، منها تقليد أسامة قيادة جيش المسلمين وفي الجيش من هو أكبر منه سناً وقدراً وأوسع جاهاً وعلماً . ولم يمنع هذا من التزام الناس بطاعته والخضوع لرأيه . ذلك أن الإسلام يريد تعويد المسلمين على الطاعة للإسلام والطاعة بالمعروف بصرف النظر عمن يكون القائد، حتى تكون الطاعة للحق المجرد لا لكون القائد في مستوى علمي معين ، فإن كان دون ذلك جاز مخالفته ولا لكونه ذا شخصية فذة فان لم يكن كذلك جازت معصيته، علماً بأن الأحسن والأفضل والأمثل توفر تلكم المواصفات القيادية في شخص القائد ..", "الخلاصة : تبين لنا مما تقدم إن الشورى صفة أساسية من صفات النظام الإسلامي .. وإنها سمة أصيلة من سمات التشريع . ثم تأكد لنا أن الأمور التي ورد فيها نص لا يمكن أن تكون محلاً للشورى وموضعاً للاجتهاد .. وإن الأمور التي يطلب لها حكم شرعي اجتهادي يكون خضوعها لقوة الدليل لا للكثرة العددية . وأما فيما عدا ذلك من تفصيلات ومشتقات فإن الترجيح يعود إلى الامير", "(١) رواه البخاري ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0182.png"}, {"n": 183, "paras": ["أو القائد صاحب الصلاحية بعد المشورة وتقليب الآراء. كما تبين لنا إن القيادة في الإسلام لا يمكن أن تكون جماعية وإن القائد والأمير فرد لا أكثر .. وإن القيادة لم تكن في حقب التاريخ الإسلامي كله قيادة جماعية، وإنما قام هذا المفهوم في أدمغة المسلمين حديثاً كنتيجة من نتائج التلوث بالأنظمة الوضعية، فضلاً عن كونه هروباً غير منظور من تكاليف الطاعة والخضوع لرأي فرد من الناس، وبالتالي مظهراً من مظاهر الانانية النفسية وحب الذات وكراهية الانقياد والتبعية، وإن كان هذا الانقياد والتبعية في حقيقتها انقياداً وتبعية للشرع وللإسلام .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0183.png"}, {"n": 184, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0184.png"}, {"n": 185, "paras": ["من أمراضنا النفسية", "• دعاة الاسلام أحوج الناس للتعرف إلى عيوبهم .", "• دعاة الاسلام وداء الكبر .", "• دعاة الاسلام في طاعة الله .", "• دعاة الاسلام والحدود الشرعية للعلاقات الاخوية ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0185.png"}, {"n": 186, "paras": ["دعاة الاسلام أحوج الناس للتعرف إلى عيوبهم", "الإنسان خطاء بطبعه، لأن عوامل الخير والشر لديه في صراع دائم وعراك مستمر. فهو بين ارتفاع وهبوط واستقامة وانحراف إلى أن يتغلب جانب على جانب وينتصر فريق على فريق: ﴿ قد أفلح من زكاها وقد خاب من دساها ﴾. وإلى هذا المعنى يشير الرسول ﷺ في حديثه، حيث يقول: ( تعرض الفتن على القلوب كالحصير عودا عودا. فأي قلب أشربها نكت فيها نكتة سوداء. وأي قلب أنكرها نكت فيها نكتة بيضاء، حتى تصير على قلبين، على أبيض مثل الصفاء فلا تضره فتنة ما دامت السموات والأرض، والآخر أسود مرباداً لا يعرف معروفاً ولا ينكر منكرا (١) ) . والإنسان بخير ما دام يحس بخطئه، ثم يعمل على تصحيحه فكل بني آدم خطاء وخير الخطائين التوابون .. أما الذين انعدم فيهم الاحساس بالخطيئة فلمسنا في مجال الحديث عنهم في هذا المقام.", "(١) حديث صحيح رواه مسلم ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0186.png"}, {"n": 187, "paras": ["هذا بالنسبة للعامة من الناس .. أما الخاصة فيجب أن لا يكتفوا برقابتهم الذاتية على أنفسهم وإنما ينبغي أن يحرصوا على كشف خبايا نفوسهم وسبر أغوار قلوبهم ، ينقبون عن العيوب ويفتشون عن الآفات والذنوب ؛ حتى تطهر أرواحهم ، وتزكو أفئدتهم وتصفو قلوبهم ، وتتصل بالملأ الأعلى ، فلا يكون بينها وبين الله حجاب .. هكذا كان شأن الرعيل الأول الذي عرف طريق الآخرة فسلكها ، وأدرك طول السفر فتزود له وصدق الله تعالى ، حيث يقول : ﴿ وتزودوا فإن خير الزاد التقوى واتقوني يا أولي الألباب ﴾ . ودعاة الإسلام ينبغي أن يكونوا أشد الناس حرصاً على معرفة عيوبهم ، والتنقيب عن ذنوبهم ، ليكونوا على الزمن هداة مهتدين وقدوة صالحة للناس أجمعين .. وعليهم أن لا يحقروا عيباً أو يستصغروا ذنباً ، فالصغائر باب إلى الكبائر. ومن تعود محقرات الذنوب هانت عليه موبقاتها ومن حام حول الحمى أوشك أن يقع فيه . والوسائل التي يمكن بها التعرف على العيوب كثيرة أهمها : أولاً : أن يحرص الأخ على مجالسة العلماء العاملين والدعاة الصالحين على خفايا الآفات ، يسترشدهم ويستنصحهم ويطالبهم بمكاشفته ومصارحته بما يرون من عيوبه .. ولقد حث الرسول ﷺ على"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0187.png"}, {"n": 188, "paras": ["تتبع هذا السبيل في كثير من أحاديثه .. فعن ابن عباس قال : قال رسول الله ﷺ : « إذا مررتم برياض الجنة فارتعوا ، قالوا يا رسول الله ، وما رياض الجنة ؟ قال مجالس العلم (١) » . وعن أبي إمامة قال : قال رسول الله ﷺ : « إن لقمان قال لابنه يا بني : عليك بمجالسة العلماء واسمع كلام الحكماء فإن الله ليحيي القلب الميت بنور الحكمة كما يحيي الأرض الميتة بوابل المطر» وعن ابن عباس قال: قيل يا رسول الله أي جلسائنا خير ؟ قال : «من ذكركم بالله رؤيته وزاد في عملكم منطقه وذكركم بالآخرة عمله (٢) »", "ثانياً : أن يتخذ له أخاً متديناً متورعاً تقياً صادقاً يجعله رقيباً على نفسه وسلوكه وتصرفاته . ينصحه إذ ضل ويقومه إذا أخطأ ويذكره إذا نسي. وهذه من فضائل الاخوة الإسلامية ومحامدها. عن أبي سعيد الخدري رضي الله عنه إنه سمع النبي ﷺ يقول : « لا تصاحب إلا مؤمناً ولا تأكل طعامك إلا تقي (٣) » . وعمر ابن الخطاب رضي الله عنه على جلال قدره فضلاً عن إنه من العشرة المبشرين بالجنة كان يقول باستمرار : « رحم الله امرءا أهدى إلي عيوبي » وكان يسأل حذيفة ويقول له : «أنت صاحب سر رسول", "(١) رواه الطبراني .", "(٢) رواه أبو العلي ،", "(٣) رواه الترمذي وأبو داود ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0188.png"}, {"n": 189, "paras": ["الله ﷺ في المنافقين فهل ترى علي شيئاً من آثار النفاق ؟ ». ثالثاً : أن يتعرف الأخ على عيوبه من عيوب الناس . فكل ما رآه قبيحاً مذموماً عندهم فليتجنبه . ولقد قيل لعيسى بن مريم عليه السلام . من أدبك قال : « ما أدبني أحد . رأيت جهل الجاهل شيئاً فاجتنبته » . هذا بالنسبة للوسائل التي تعين الأخ الداعية على معرفة نفسه وسبر أغوارها وكشف مجهولها وإدراك أمراضها وعيوبها .. وبعدئذ ينبغي أن يبدأ طوراً جديداً من أطوار العمل وهو طور المعالجة والتطبيب . لانه إذا كان من المهم أن نعرف عيوبنا ونكتشف عللنا وأمراضنا ، فإن من الأهم أن نبادر إلى معالجتها وتطبيبها . ولمعالجة النفوس ومغالبة الذنوب والعيوب سبيل واحد هو التوبة الصادقة . وتبدأ التوبة بعقد النية في الباطن على هجر كل ما حظره الشرع ، واجتناب كل ما يؤدي للوقوع فيه وذلك عملاً بقول الرسول الاعظم ﷺ : « من اجتنب الشبهات فقد استبرأ لدينه وعرضه ومن وقع في الشبهات وقع في الحرام». ويترتب على الأخ الداعية خلاف عقد ( النية ) ان يداوم التفكير في ذنوبه مستشعراً الخوف من الله عز وجل ، مؤكداً تصميمه وحرصه على الوفاء بما عاهد الله مقبلاً على الطاعات مكثراً من نوافل العبادات وبخاصة قيام الليل ﴿ ومن الليل فتهجد به"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0189.png"}, {"n": 190, "paras": ["نافلة لك عسى ان يبعثك ربك مقاماً محموداً ﴿ وقد سئل ابراهيم ابن ادهم يوماً بم يتم الورع فقال: « بتسوية جميع الخلق من قلبك وانشغالك عن عيوبهم بذنبك . وعليك باللفظ الجميل من قلب ذليل لرب جليل . فكر في ذنبك وتب إلى ربك يثبت الورع في قلبك . واحسم الطمع إلا من ربك ». إن من بركة العبادة إذا احسن اداؤها مظهراً وجوهراً إنها تستخلص النفس البشرية من ترابيتها وتعمل على تزكيتها وتطهيرها والسمو بها في معارج الكمال والربانية. وهذا معنى قول الله تعالى: ﴿ إن الصلاة تنهى عن الفحشاء والمنكر ﴾ ومعنى قوله ﷺ : « ارايتم لو ان نهراً بباب احدكم يغتسل فيه كل يوم خمس مرات هل يبقى من درنه شيء ؟ قالوا : لا يبقى من درنه شيء. قال: فكذلك مثل الصلوات الخمس يمحو الله بهن الخطايا (١) ». فنسأل الله تعالى ان يوفقنا لطاعته ويعصمنا عن معصيته ومخالفته وان يجعلنا ممن يستمعون القول فيتبعون احسنه .", "(١) حديث متفق عليه ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0190.png"}, {"n": 191, "paras": ["دعات الاسلام وداء الكبر", "دعات الإسلام أكثر تعرضاً لمكائد الشيطان والقاءات الشر وتلبيس ابليس من سواهم من الناس .. ذلك أن الناس قد فرغ الشيطان منهم وغرر بهم وأصبحوا من حزبه وجنده ( يعدهم ويمنيهم وما يعدهم الشيطان إلا غروراً ) . ودعات الإسلام - كذلك - أكثر تعرضاً لأمراض القلوب وآفات النفوس من عوام الناس الذين ماتت قلوبهم وأظلمت نفوسهم ﴿ ختم الله على قلوبهم وعلى سمعهم وعلى أبصارهم غشاوة ولهم عذاب عظيم ﴾. لذلك أجدني دائماً في حاجة إلى أن أكتب واتحدث عن المشكلات والأمراض التي تواجة الدعاة إلى الله تنبيهاً للنفوس من الغفلة ، وإنذاراً لها من الأخطار التي تحيط بها ، وتذكيراً بما يلزمها من أخذ بأسباب الوقاية والحماية ، صيانة لهذه النفوس من العلل والآفات وحفاظاً عليها من الفتن والإنحرافات عملاً بقول"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0191.png"}, {"n": 192, "paras": ["الله تعالى : ﴿ وذكر فإن الذكرى تنفع المؤمنين ﴾ .", "الكبر :", "والكبر يكاد يكون من أشد الأمراض خطراً على دعاة الإسلام . فالمجالات التي يعمل فيها الدعاة مرتع خصب لظهور هذا الداء ونموه وعتوه . لذلك كان الرسول ﷺ وهو سيد المتواضعين ، كثيراً ما يجأر إلى الله بالدعاء فيقول : « اللهم إني أعوذ بك من نفخة الكبرياء » .", "وليس من قبيل العبث أن يعرض علينا القرآن الكريم في أكثر من موضع قصة إبليس الذي خرج من رحمة الله إلى سخطه وهبط من سمائه إلى أرضه حين قال : ﴿ أنا خير منه ، خلقتني من نار وخلقته من طين ﴾ .", "أسبابه :", "والكبر داء تعددت أسبابه وكثرت مسبباته ..", "غرور العلم :", "فهناك غرور العلم ، وهو أشد أنواع الغرور على الاطلاق . ودعاة الإسلام أكثر تعرضاً للإصابة بجرثومه الفتاك . فالخطابة والكتابة والتعليم والتوجيه وسواها من وسائل الدعوة فضلاً عن الشهادات والدرجات العلمية والالقاب الجامعية فإنها تعتبر من أوسع مداخل الشيطان إلى النفس البشرية . لانها مجلبة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0192.png"}, {"n": 193, "paras": ["للشهرة ملفتة للانظار ، مثيرة للاعجاب ، وفي هذا ما فيه من عوامل الاشباع والاملاء لرغائب النفس وجوعاتها البشرية .. وهذا ما لفت الرسول ﷺ النظر اليه بقوله : « آفة العلم الخيلاء» ولقد حذر الرسول عليه الصلاة والسلام من مغبة الانسياق اليه والوقوع فيه فقال : « من تعلم العلم ليجاري به العلماء ويماري به السفهاء ، ويضرب به وجوه الناس اليه أدخله الله النار». فعلى دعاة الإسلام أن يكونوا شديدي الاحتراس من الوقوع في هذا المرض العضال . وليعلموا أن الله الذي منحهم ملكة الخطابة وموهبة الكتابة وقوة التفكير ، قادر على أن يسلبهم هذه النعم من حيث لا يشعرون . وإن من حق الله عليهم أن يكونوا شاكرين لفضله غير جاحدين ولا كافرين: ﴿ولئن شكرتم لأزيدنكم ولئن كفرتم إن عذابي لشديد﴾ . وإن من علائم الشكر لنعمة الله تعالى وفضله زيادة الخوف منه والاقبال على طاعته والادبار عن معصيته والتواضع لجلاله وعظمته، فضلاً عن تسخير العلم لتعليم الناس وهدايتهم وتوجيههم وإرشادهم . وعلى دعاة الإسلام أن يحاسبوا أنفسهم دبر كل حديث ألقوه أو خطاب ارتجلوه أو مقال كتبوه أو اجتماع أداروه، ليطمئنوا إلى أن مشاعر العجب وأحاسيس الكبر لم توقظها طلاقة لسان أو حسن بيان أو مظاهر إعجاب واستحسان .. وان عليهم ان ينظفوا مشاعرهم من كل ما يشوبها ويلوثها ، وليعلموا أن الله"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0193.png"}, {"n": 194, "paras": ["لا يقبل من الأعمال إلا ما خلص له ، وانه هو القائل على لسان نبيه ﷺ : « الكبرياء ردائي والعظمة إزاري فمن نازعني فيها قسمته (١) » .", "غرور التدين : وهناك نوع آخر من الغرور يسمى بغرور التدين، واكثر ما يصيب هذا الداء المتنطعين الذين يشادون الدين ويبالغون في التدين ، وقد يصيب كذلك الاشخاص الذين لم ينم تدينهم نمواً طبيعياً او يتوافر توافراً تدريجياً مرحلياً .", "لهذا حرص الإسلام على الاعتدال والتوسط في كل أمر حق في التدين ، وجاءت أحاديث الرسول ﷺ تنهى عن التفريط والافراط والغلو والمبالغة في كل شيء . فقال ﷺ : « ما شاد هذا الدين أحد إلا قصمه » ، « إن هذا الدين شديد فأوغلوا فيه برفق » ، « الا هلك المتنطعون ، الا هلك المتنطعون » ، كل ذلك ليسد على النفس البشرية مداخل الشيطان وليكلفها ما تطيق فإن المنبت لا ظهراً أبقى ولا أرضاً قطع، وان الله يحب من الاعمال ادومها وان كان قليلاً .", "إن التدين الصحيح ينبغي ان يكون عاملاً من عوامل تزكية النفس وطريقاً يصل بالمتدينين إلى ذروة الكمال البشري", "(١) رواه ابو داود وابن ماجة وابن حبان"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0194.png"}, {"n": 195, "paras": ["حق يتحقق في كمال العبودية كمال الحرية .. الحرية الكاملة من كل النزعات والاهواء. ويوم يكون التدين رمزاً للمباهاة والتفاخر ومصدراً للغرور والتكبر يصبح المتدين في خطر كبير وشر مستطير ، لأن التدين لديه يكون قد فقد حقيقته ومعناه . ومن خلال هذا المعنى نستطيع أن نستشف معنى قول الله لداوود عليه السلام : ﴿ انين المذنبين أحب الي من صياح العابدين ﴾ .", "فليتدبر الدعاة أمورهم وليخلصوا لله قلوبهم وليزدهم التدين تواضعاً ، وإياهم والغرور فانه قاصم للظهور ، مبدد للحسنات موجب لسخط الله والعياذ به تعالى . ويروي في هذ القبيل أن رجلا ببني إسرائيل كان يقال له خليع بني إسرائيل لكثرة فساده ، مر برجل آخر يقال له عابد بني إسرائيل ، وكان على رأس العابد غمامة تظله ، فلما مر الخليع به قال الخليع في نفسه : أدا خليع بني إسرائيل وهذا عابد بني إسرائيل ، فلو جلست اليه لعل الله يرحمني !! فجلس اليه فقال العابد : أنا عابد بني إسرائيل وهذا خليع بني إسرائيل ، فكيف يجلس إلي ، فأنف منه وقال له : قم عني ! فأوحى الله إلى نبي ذلك الزمن : ﴿ مرهما فليستأنفا العمل فقد غفرت للخليع وأحبطت عمل العابد . وتحولت الغمامة إلى رأس الخليع ﴾ .", "غرور الشخصية : وثمة نوع آخر من الغرور يسمى بغرور الشخصية .. وغرور", "الدعوة (١٣)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0195.png"}, {"n": 196, "paras": ["الشخصية يتأتى من إعجاب المرء بنفسه ، بشكله أو صورته أو هيبته أو شخصيته أو قامته أو لباسه أو ما أشبه ذلك . فالشكل الحسن واللحية المهيبة واللباس الأنيق والعمامة الكبيرة والجبة الفضفاضة وسواها من المظاهر قد تكون عامل غواية ومنفذاً من منافذ الشيطان إلى النفس البشرية ، وبخاصة إذا قوبلت من الآخرين بالاستحسان والمديح والاطراء والاطناب والاعجاب ، وهنا تكمن الحكمة في قوله الرسول ﷺ : « لقد قصمت ظهر أخيك » . ويكفي أن يعلم الاخوة الدعاة أن المظاهر لا تغني عن الجواهر شيئاً ، فالعبرة بما في الباطن والقيمة تكمن في اللباب لا في القشور ؟ وصدق رسول الله ﷺ حيث يقول : « إن الله لا ينظر إلى أجسادكم ولا إلى صوركم ولكن ينظر إلى قلوبكم » . وحبذا لو يتوفر حسن المظهر وحسن الجوهر .. إن على دعاة الإسلام أن يغالبوا خداع المظهر باعتماد الجوهر، وإذا داخلهم شيء من وسوسات الشيطان وأحسوا في نفوسهم بانتفاخ من نفخ ابليس وهم أمام المرآة معجبين بأشكالهم ، فليمعنوا التفكير بما تحت الجلد وفيما داخل هذا الهيكل، وعندها سيدركون حقيقة هذا الجسد، فتحت الجلد تجري الدماء والصديد، في الامعاء تعيش الديدان والأقذار ، وفي الكليتين يتجمع البول « قتل الإنسان ما أكفره ، من أي شيء خلقه ، من نطفة خلقه فقدره ، ثم السبيل يسره ، ثم أماته فأقبره ، ثم إذا شاء انشره،"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0196.png"}, {"n": 197, "paras": ["كلا لما يقض ما أمره » . ثم ليعودوا بأفكارهم إلى الوراء قليلا يوم كانوا كتلة مخاطية تعيش بين الدماء ، ثم جعل الله لهم الأسماع والابصار والافئدة والاطراف، وأخرجهم من مجرى البول ليشكر وه لا ليكفروه، وليلتزموا حدودهم فلا يتجاوزوها ، وليعرفوا ان قيمتهم الحقيقية لا تكمن في هذا الحطام البالي وإنما تعدوه إلى القيم الروحية والخلقية والانسانية التي يتحلون بها ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0197.png"}, {"n": 198, "paras": ["دعاة الاسلام في طاعة الله", "من واجبات الاخ الداعية أن يتابع نفسه وروحه بما يصلحها ويزكيها .. وعليه أن لا يتساهل أو يلين في مراقبتها ومحاسبتها لأن النفس أمارة بالسوء ، ومداخل الشيطان اليها اكثر من أن تحصى « والكيس من دان نفسه وعمل لما بعد الموت والعاجز من اتبع نفسه هواها وتمنى على الله الاماني (١) » ومن وصايا عمر بن الخطاب في هذا المعنى قوله : ﴿ حاسبوا انفسكم قبل أن تحاسبوا وزنوها قبل أن توزنوا ، وتهيئوا للعرض الاكبر ﴾ . إن ضغوط الجاهلية التي يواجهها الداعية في حياته كثيرة ومتعددة .. فهو يشعر بغربته وشذوذ المجتمع من حوله .. وهو يحس بأن كل مظاهر المدنية الحديثة ليس لها إلا هدف الاغواء والاغراء ، وتقويض القيم والمثل العليا، وتدمير الاخلاق والمكارم وإشاعة الرذائل والفواحش في المجتمع .. وهو لذلك بحاجة ماسة إلى « صيانة » نفسه من التأثر", "(١) حديث صحيح رواه أحمد والترمذي وابن ماجة ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0198.png"}, {"n": 199, "paras": ["والانحراف ليقوى على المضي في الطريق الذي يرضي الله ، وليتمكن من مكافحة الجاهلية وتسديد الضربات القاضية اليها على كل صعيد . ومسألة « الصيانة » هذه إن لم تتخذ في حياة الأخ شكلا جدياً فستبقى - لا محالة - كلمة فارغة ليس لها في واقعه ادنى مدلول أو تأثير .. من أجل ذلك اقترح على الاخوة، سواء كانوا أفراداً مبتدئين، أو دعاة لامعين ، أو قادة ومسؤولين أن يكون لهم مع أنفسهم موعد يومي للمحاسبة والصيانة .. واقترح أن تجري المحاسبة يومياً على الأمور التالية ومدى التزام الأخ بها :", "١ - إن قيام الليل ( مدرسة روحية ) لا تفوت .. ومولد الطاقة الايمانية لا يعدله آخر ولا غنى عنه بسواه .. وهذا سر قول الله تعالى فيه : ﴿ إن ناشئة الليل هي أشد وطأ وأقوم قيلا ﴾ .. فهل قمت شيئاً من ليلتك الفائتة نافلة لك عسى أن يبعثك ربك مقاماً محموداً ، أم إنك كنت من النائمين الغافلين ساعة ينزل ربنا تبارك وتعالى في ثلث الليل الأخير فيقول: ﴿هل من مستغفر فأغفر له . من يدعوني فأستجيب له . من يسألني فأعطيه ﴾ ثم أين أنت يا أخي من الذين وصفهم الله تعالى بقوله : ﴿تتجافى جنوبهم عن المضاجع ﴾ و ﴿ كانوا قليلاً من الليل ما يهجعون ﴾ . ﴿ أمن هو قانت آناء الليل ساجداً وقائماً يحذر الآخرة ويرجو ﴾"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0199.png"}, {"n": 200, "paras": ["رحمة ربه ، قل هل يستوي الذين يعلمون والذين لا يعلمون إنما يتذكر أولوا الألباب ﴾ . روى الطبراني في الكبير عن سلمان الفارسي رضي الله عنه قال : قال رسول الله ﷺ « عليكم بقيام الليل . فإنه دأب الصالحين قبلكم، ومقربة لكم إلى ربكم ، ومكفرة للسيئات ومنهاة عن الإثم ، ومطردة للداء عن الجسد (١) » .", "٢ - ثم هل تعلم يا أخي بأن الله ملائكة يتعاقبون فينا بالليل والنهار ، وإنهم يجتمعون في صلاة الفجر والعصر ، ثم يعرجون إلى السماء فيسألهم الله - وهو أعلم بهم - كيف تركتم عبادي ؟ فيقولون تركناهم وهم يصلون واتيناهم وهم يصلون .. فهل أديت صلاة الفجر في وقتها مع الجماعة فكنت من الذين قال فيهم رسول الله ﷺ : « من صلى الصبح فهو في ذمة الله ، فانظر يا ابن آدم لا يطلبنك الله من ذمته شيء (٢) » . روى البخاري ومسلم عن أبي هريرة رضي الله عنه إنه قال : قال رسول الله ﷺ : « إن أثقل صلاة على المنافقين صلاة العشاء وصلاة الفجر ولو يعلمون ما فيهما لا توهما ولو حبواً. ولقد هممت أن آمر بالصلاة فتقام ، ثم آمر رجلاً ليصلي بالناس ، ثم انطلق معي برجال معهم حزم من حطب لا يشهدون الصلاة فأحرق", "(١) رواه أحمد الترمذي .", "(٢) رواه مسلم ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0200.png"}, {"n": 201, "paras": ["عليهم بيوتهم بالنار » .", "٣ - واعلم يا أخي إن قلبك بحاجة إلى عذب من معين القرآن يمنحه السكينة والطمأنينة ويكسبه الشفافية والارهاف . وإن المؤمنين هم الذين لهم قلوب حية نابضة مرهفة : ﴿ إنما المؤمنون الذين إذا ذكر الله وجلت قلوبهم ﴾ .. فهل قرأت ورداً من القرآن بعد صلاة الفجر وذكرت الله خالياً متضرعاً حتى فاضت عيناك ؟ ! ام انك من الذين طال عليهم الامد فقست قلوبهم فهي كالحجارة !", "الم تسمع يا أخي إلى قول الله تعالى : ﴿ إن قرآن الفجر كان مشهودا ﴾ . وقول الرسول ﷺ : « ان الذي ليس في جوفه شيء من القرآن كالبيت الخرب (١) » . وقوله : « من قرأ القرآن فقد استدرج النبوة بين جنبيه ، غير انه لا يوحي اليه . لا ينبغي لصاحب القرآن أن يجد ( أى أن يغضب ) مع من وجد ، ولا يجهل مع من جهل ، وفي جوفه كلام الله (٢) » . ثم لا تنس ان تقرأ القرآن وكأنه يتنزل عليك لأول مرة .", "٤ - وحين تجلس على مائدة الطعام فهلا فكرت قليلا في الغاية التي من أجلها تأكل وفي هذه النعم والطيبات التي هيأها لك الله لتكون غذاء وقوة تعينك على شكره وطاعته وتمدك بالقوة", "(١) رواه الترمذي", "(٢) رواه الحاكم"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0201.png"}, {"n": 202, "paras": ["للجهاد في سبيله . ثم هل دققت في المصادر التي حصلت منها على هذه الاطعمة والاشربة وتحريت عن الحلال الطيب منها وتعففت عن الحرام الخبيث ..", "ه - وحين تخرج من بيتك .. ينبغي أن تدرك إن الإسلام دين عمل لا كسل ودين سعي لا بطالة . وإن من واجبك كمسلم أن تنتشر في الأرض وتبتغي من فضل الله تاجراً عاملاً متكسبا .. فهل قمت اليوم بقسطك من هذا الجهاد، وأديته باتقان واخلاص عملاً بقوله ﷺ : «إن الله يحب إذا عمل أحدكم عملاً أن يتقنه (١)» .. ثم هل طهرت مالك بالانفاق على الفقراء والمساكين واصحاب الحاجات وأديت الزكاة المفروضة فيه عليك . وكنت بذلك من الشاكرين .", "روى البخاري عن المقداد بن يكرب عن النبي ﷺ إنه قال : « ما أكل أحد طعاماً قط خيراً من أن يأكل من عمل يديه . وان نبي الله داود عليه السلام كان لا يأكل إلا من عمل يده (٢)» .", "٦ - وفي الشوارع التي تمر بها ، وفي المجتمعات التي تغشاها ، هل كنت دائم المراقبة لله !", "- هل وقع بصرك على حرام فغضضته واستغفرت الله لعلمك", "(١) للبيهقي .", "(٢) حديث صحيح رواه أحمد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0202.png"}, {"n": 203, "paras": ["بأن النظرة الأولى لك والثانية عليك ، وإن النظرة سهم من سهام ابليس . هل دعتك امراة ذات منصب وجمال فأعرضت وقلت انني أخاف الله ، ثم رددت بينك وبين نفسك ( رب السجن احب إلي مما يدعونني اليه ، وإلا تصرف عني كيدهن اصب اليهن واكن من الجاهلين ) .", "- هل تحريت في تجارتك عن الحلال من الرزق وإن كان قليلا ؟..", "- هل فرط منك ما تعتبره مخالفة شرعية ؟ هل استشعرت في كل عمل رقابة الله ووزنته بميزان الإسلام وتورعت عن الشبهات وكنت من المتقين الذين عنهم الرسول ﷺ بقوله : « لا يبلغ العبد ان يكون من المتقين حتى يدع ما لا بأس به حذراً مما به بأس (١)».", "٧ - والآن اسأل نفسك عن مدى استفادة الإسلام من ظروف عملك . هل يشعر زملاؤك بأثرك الإسلامي فيهم .. هل قمت بزيارتهم في منازلهم لتوثيق الصلة بهم ومحاولة اجتذابهم إلى الفكرة وإلى الحركة. إن من واجبك ان تتحرك في كل ميدان وان تترك وراءك اثراً إسلامياً في كل مكان واذكر دائماً قول الرسول ﷺ : « لئن يهدي الله بك رجلا واحداً خيراً لك مما", "(١) رواه الترمذي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0203.png"}, {"n": 204, "paras": ["طلعت عليه الشمس وغربت (١) . » إن لديك يا أخي متسعاً من الوقت خارج وقت عملك .. وإن من واجبك أن تقدم منه قسطاً وافراً لدعوتك .. والوقت كالسكين إن لم تقطعه قطعك . ووصية الرسول ﷺ في هذا قوله : « نعم العطية كلمة حق تسمعها ثم تحملها إلى أخ لك مسلم فتعلمها إياه (٢) . » روى مسلم في صحيحه عن أبي هريرة رضي الله عنه إن رسول الله ﷺ قال : « من دعا إلى هدى كان له من الأجر مثل أجور من تبعه لا ينقص ذلك من أجورهم شيئاً . ومن دعا إلى ضلالة كان عليه من الاثم مثل آثام من اتبعه لا ينقص ذلك من آثامهم شيئاً » .", "٨ - ثم لا تنس أن تسأل نفسك عن الاوقات التي توفرها وتنظمها لتنمية ثقافتك الإسلامية والعامة .. فأنت تعيش في مجتمع تشعبت ثقافاته ، وتعددت اتجاهاته ، وتباينت أفكاره وتصوراته .. وهذا مما يفرض عليك الاحاطة بما حولك من أفكار وتصورات لتتمكن من التحليل والتشخيص والمناقشة والنقد والاصلاح ..", "- فهل طالعت شيئاً عن الإسلام طيلة هذا اليوم ؟", "(١) رواه الطبراني"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0204.png"}, {"n": 205, "paras": ["- هل قرأت شيئاً تعتبره مفيداً لثقافتك العامة الفكرية والسياسية ..", "روى ابن عبد البر في كتاب العلم عن معاذ بن جبل رضي الله عنه قال : قال رسول الله ﷺ : « تعلموا العلم ، فإن تعلمه لله خشية ، وطلبه عبادة ، ومذاكرته تسبيح ، والبحث عنه جهاد ، وتعليمه لمن لا يعلمه صدقة ، وبذله لاهله قربة ، لانه . معالم الحلال والحرام ، ومنار سبل أهل الجنة ، وهو الأنيس في الوحشة ، والصاحب في الغربة ، والمحدث في الخلوة ، والدليل على السراء والضراء ، والسلاح على الاعداء ، والزين عند الاخلاء، يرفع الله به أقواماً فيجعلهم في الخير قادة قائمة تقتفي آثارهم ، ويقتدى بفعالهم وينتهى إلى رأيهم - الحديث » .", "٩ - والآن اسأل نفسك عن مدى استعدادها للبذل والتضحية في سبيل الله .. إن اثقالاً كثيرة تشدك إلى الحطام وتمرغك في الرغام . فهل حاولت أن تتخفف من هذه الاثقال وتتحرر من سلطانها عليك ؟", "- إن الخوف على الحياة ثقل يقعد بك عن الجهاد في سبيل الله ينبغي أن تتحرر منه .. وإن الخوف على المصلحة المادية ثقل يحول بينك وبين التفرع لدعوتك وإسلامك يجب ان تتخلص منه .", "- وإن التعلق بالزوجة والولد والأهل والعشيرة اثقال تعيق الانطلاق يجب التفلت من سلطانها ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0205.png"}, {"n": 206, "paras": ["إن عليك في كل الأحوال أن تغلب مصلحة الإسلام على كل مصلحة . وتخضع أهواءك لما جاء به الشرع ، وتكون مستعداً دائماً وأبداً للموت في سبيل الله . روى البخاري ومسلم عن عبد الله بن أبي أوفى رضي الله عنه قال : قال رسول الله ﷺ : « اعلموا أن الجنة تحت ظلال السيوف » . وروى مسلم في صحيحه عن عقبة بن عامر رضي الله عنه قال : سمعت رسول الله ﷺ : وهو على المنبر يقول : « وأعدوا لهم ما استطعتم من قوة .. ألا أن القوة الرمي . ألا أن القوة الرمي . ألا أن القوة الرمي » . وروى الترمذي عن أبي هريرة رضي الله عنه قال : قال رسول الله ﷺ : « من لقي الله بغير أثر من جهاد لقي الله وفيه ثلمة » .", "١٠ - وأخيراً لا آخراً هل فكرت في هذا الجسد .. في حقه عليك ، وفيما ينبغي أن توفره له ليكون قوياً جداً قادراً على تحمل أعباء السفر الطويل والجهاد المرير .. ينبغي أن تدرك أن المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف ..", "- فهل أديت بعض التمارين الرياضية « المنظمة » هذا الصباح ..", "- هل مارست شيئاً من الرماية والسباحة والسير وركوب الخيل والدراجة والسيارة ؟"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0206.png"}, {"n": 207, "paras": ["هل حاولت الامتناع عن كل ما يرهق البدن ويتعبه فاقتصدت في السهر والاكل والشرب وامتنعت تماماً عن التدخين وتناول القهوة والشاي والمثلجات . إن عليك يا اخي ان تعد نفسك لتكون جندياً في معركة الإسلام بكل ما تتضمنه كلمة الجندية من معنى . والله يتولى الصالحين ويهدينا جميعاً سواء السبيل .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0207.png"}, {"n": 208, "paras": ["دعاة الاسلام والحدود الشرعية للعلاقات الأخوية", "إن من حق الإسلام على دعاته والمنتسبين إليه أن يستفتوه في كل شؤونهم ، وأن ينزلوا عند حكمه في كافة أمورهم ، وأن يسلموا له في شتى الظروف والأحوال من غير ضيق ولا حرج حق يستحقوا بذلك درجه الإيمان : ﴿ فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجاً مما قضيت ويسلموا تسليماً ﴾ .", "وإن شر ما يصيب الدعاة - أحياناً - احتكامهم لأهوائهم ، وعدم خلوصهم من حظوظ أنفسهم ، وفي ذلك الجحود والكفران بالمبادىء التي يحملونها وبالتالي التناقض كل التناقض مع الشرعة التي ينتسبون إليها . وهذا ليس من صفات المؤمنين في شيء ولا هو من أخلاق الدعاة من قريب أو بعيد وصدق الله تعالى حيث يقول : ﴿ ما كان لمؤمن ولا مؤمنة إذا قضى الله ورسوله أمراً ان يكون لهما الخيرة من أمرهم ﴾ ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0208.png"}, {"n": 209, "paras": ["هكذا ينبغي أن يكون شأن دعاة الإسلام .. تبعية مطلقة ، وموالاة واثقة ، وجندية مخلصة صادقة ..", "الاخوة والحب في الله إن موضوع الاخوة الإسلامية والحب في الله من الموضوعات التي كثر الحديث عنها وتعددت الكتابات فيها .. ولست بالذي يود أن يضيف شيئاً إلى ما كتبه الآخرون في الجانب التجريدي من الموضوع ، كذلك لست بالذي يود ان يناقش القضية من هذا الجانب . إنما مرادي توضيح الحدود الشرعية للعلاقة الأخوية والحب في الله منعاً لكل التباس ، ودفعاً لكل انحراف قد يؤدي بالمتحابين في الله - بقصد أو بدون قصد - إلى ما لا يرضي الله عز وجل . وصيانة لهذا العقد المقدس الطاهر من كل ما يسيء إلى قدسيته وطهارته وإلى بهائه ونقائه .", "الاخوة في مفهوم الشرع والاخوة في نظر الإسلام هي الآصرة العقيدية التي تشد المسلمين بعضهم لبعض. وهي الرباط الرباني الذي يربط بين قلوبهم بل هي وشيجة القوى في الله . وهي من أوثق عرى الإيمان كما يقرر ذلك رسول الله ﷺ بقوله : « أوثق عرى الإيمان الحب في الله والبغض في الله » (١) .", "(١) رواه أحمد ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0209.png"}, {"n": 210, "paras": ["والاخوة هي إحدى المقومات الأساسية التي يعتمد عليها الإسلام في بناء المجتمع الإسلامي ، وإحكام الربط بين أفراده وأبنائه . ويوم أقام الرسول ﷺ المجتمع الإسلامي الأول في المدينة ، كانت الاخوة الدعامة الثانية في صرح الدولة الإسلامية الفتية ، بعد العقيدة التي تمثلت في بناء المسجد النبوي الشريف .", "ولهذا عمل الإسلام على توثيق عرى الحب والاخوة بين المؤمنين . ووعد المتحابين فيه الحسنى يوم القيامة وأجزل لهم الأجر والعطاء فقال رسول الله ﷺ : « ما تحاب اثنان في الله إلا كان أحبهما إلى الله أشدهما حباً لصاحبه » ، وقال: « ينصب لطائفة من الناس كراسي حول العرش يوم القيامة ، وجوههم كالقمر ليلة البدر ، يفزع الناس وهم لا يفزعون ويخاف الناس وهم لا يخافون . وهم أولياء الله الذين لا خوف عليهم ولا هم يحزنون . فقيل من هؤلاء يا رسول الله : فقال : هم المتحابون في الله تعالى » (١) .", "وإذا كان الإسلام قد كرّم الاخوة ورفع شأنها ودفع إليها وأثاب عليها فإنما فعل ذلك لما ينتج عنها من خير ، ولما تدفعه من شر في حياة الاخوة المتحابين . فالإسلام لم يعتبر الاخوة غاية بذاتها وإنما اعتبرها وسيلة لكثير من المقاصد والغايات ..", "(١) أخرجه أحمد والحاكم ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0210.png"}, {"n": 211, "paras": ["الاخوة : مقاصدها وأهدافها", "أولاً فالاخوة في نظر الإسلام وسيلة من وسائل التعاون ، على الطاعات ، والتذكير بالله ، والتواصي بالحق والتواصي بالصبر ، ومن هنا كان على الأخ المسلم أن يتخير لصحابته وإخوته الأخيار الصالحين فقال الرسول ﷺ : « من أراد الله به خيراً رزقه خليلاً صالحاً إن نسي ذكره وإن ذكر أعانه » . وقال عيسى عليه السلام : « جالسوا من تذكركم بالله رؤيته ، ومن يزيد في علمكم كلامه ، ومن يرغبكم في الآخرة عمله ». وقال عمر بن الخطاب رضي الله عنه : « عليك بإخوان الصدق فعش في أكنافهم فإنهم زينة في الرخاء ، وعدة في البلاء » .", "ثانياً : والاخوة كذلك وسيلة يستعين بها الاخوان على قضاء حوائج الأزمان ومغالبة الصعاب ومواجهة الأزمات . قد لا يطيق الانسان تحمل الأعباء وحيداً ، ومواجهة المسؤوليات فريداً ، فلا بد له من إنسان آخر تطمئن إليه نفسه وتأنس به روحه ، فيستنهضان همم بعضهما البعض ، ويشدان إزر بعضهما البعض مصداقاً لقوله تعالى : ﴿ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ ﴾ وهذا موسى عليه السلام عندما ألقيت عليه تكاليف النبوة سأل ربه أن يجعل أخاه هارون رفيقاً له في مهمته ومعيناً له في دعوته « واجعل لي وزيراً من أهلي هارون أخي . أشدد", "الدعوة (١٤)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0211.png"}, {"n": 212, "paras": ["به أزري وأشركه في أمري . كي نسبحك كثيراً ونذكرك كثيراً إنك كنت بنا بصيرا » .", "لا تفريط ولا إفراط", "ولكن على الرغم من كل هذا ، ومما للاخوة من شأن ، وما لها من حسنات ، فإن الإسلام حرص على الاعتدال في كل شيء حتى في العبادات . والرسول ﷺ كان لا يخير بين أمرين إلا اختار أوسطهما أو أيسرهما ما لم يكن باطلاً .. والتطرف وضع شاذ كائناً ما كان موضوعه ومنطوقه . وهو بالتالي سلوك غير طبيعي قد يؤدي إلى كثير من المضاعفات والانحرافات .", "والاخوة الإسلامية هي العلاقة الطبيعية الفطرية التي لا تجنح جنوح ( العشق ) ولا تبلغ مبلغ ( الوله والتيم ) بل ينبغي أن لا تصل إلى حد ذوبان المحب بالمحبوب ، لأنها إن وصلت إلى هذا الحد فستفقد بدون شك ضوابط الصيانة الشرعية ، وقد تخالطها", "- بقصد وبغير قصد - أحاسيس ودوافع بشرية خفية مغلفة تتساقط أغلفتها على الزمان ، ويقع ما لم يكن بالحسبان . والعاقل من تدارك الأمر قبل فوات الأوان . ورحم الله امرءاً عرف حدود الشرع فالتزمها وعرف حدود نفسه فوقف عندها .", "من هنا كان على المتحابين في الله أن يتقوا الله في كل خاطرة من خواطر أنفسهم ، وأن يقعدوا اخوتهم وفق تصور الإسلام"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0212.png"}, {"n": 213, "paras": ["ومفهومه ، وأن يكونوا مع أنفسهم صرحاء ، وليلجموا العاطفة بلجام العقل ، ولينيروا العقل بهدى الإسلام ، وإياهم والترخص في الصغائر فإنها طريقهم إلى الكبائر .. إن قلوب الدعاة ينبغي أن تبقى معابد لا يعبد فيها غير الله .. وليحذروا الشرك فإن دبيبه خفي وأثره قوي . ولتكن اخوة الرسول مع أبي بكر رضي الله عنه قدوتهم ومثالهم والتي لم تمنع رسول الله ﷺ من أن يقول : « لو كنت متخذاً من أهل الأرض خليلاً لاتخذت أبا بكر خليلاً». وليذكروا قول أحد الصالحين وقد بلغ من العمر الستين قال : « وقفت على باب قلبي أربعين عاماً حق لا يدخله غير الله » ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0213.png"}, {"n": 214, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0214.png"}, {"n": 215, "paras": ["نحو حركة إسلامية عالمية واحدة", ". مبررات قيامها . تجارب في نطاق العمل للإسلام", "- طريق الوعظ والإرشاد", "- طريق القوة والثورة المسلحة", "- طريق التثقيف وبث الأفكار . الحركة الإسلامية وظروف المنطقة ومنطق المواجهة . ملامح الحركة الإسلامية العالمية الواحدة :", "- الانقلابية", "- اللامركزية", "- الفكرية", "- العلمية", "- الربانية"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0215.png"}, {"n": 216, "paras": ["تشعبت طرائق العمل للاسلام في العصر الحديث مما يبعث على الخوف والقلق من أن يؤدي هذا التشعب إلى تشوه الصورة السليمة الأصيلة لطبيعة العمل الاسلامي وخصائصه ، وبالتالي إلى استنزاف القوى والفعاليات الاسلامية في مماحكات كلامية ومنافسات حزبية رخيصة لا أقول انها لا تخدم الاسلام أو القضية الاسلامية فحسب ، وإنما أقول انها قد تؤدي إن لم تكن قد أدت إلى بلبلة عقول الناس وتنفيرهم ، وفي النهاية خسرانهم وجعلهم في جانب العاملين لهدم الاسلام ، وما أكثرهم في هذه الأيام ؟", "ومنطق المواجهة في العصر الحديث فضلا عن منطق الشرع والإسلام يقضيان ويحتما تلاحم القوى الاسلامية واحتشادها في مسيرة واحدة لضرب الجاهلية ، وإقامة دولة تحتكم إلى شرعة الله ، وتأخذ طريقها إلى هداية العالمين ..", "مبررات قيام حركة إسلامية عالمية واحدة", "إن المبررات التي تحتم قيام حركة إسلامية عالمية واحدة أكبر من أن تناقش وأكثر من أن تعد والعاملون في الحقل الإسلامي مدعوون لتمحيصها ودراستها ، حتى يكون العمل"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0216.png"}, {"n": 217, "paras": ["والسعي لإيجاد الحركة الإسلامية المنشودة قائماً على قناعة وإيمان وليس على عاطفة مشبوهة وحماس عفوي مؤقت .. إن الاسلام يواجه في هذا العصر تحديات ضارية من أكثر من جهة واتجاه .. وأحكام الإسلام وقوانينه المنبثقة عن الشريعة الإسلامية معطلة في سائر أنحاء الوطن الإسلامي .. بل إن حكم الطاغوت والأنظمة والأفكار المادية الوضعية المضادة للاسلام والحاقدة عليه والمتناقضة مع فلسفته الكونية ومبادئه الأخلاقية هي السائدة .. والأفكار المادية والفلسفات الإلحادية عصفت بأدمغة الأجيال .. ومستوى الانحلال الخلقي وصل إلى الدرك الأسفل .. وجور الأنظمة الحاكمة وظلم القوانين القائمة وعدم توفيرها للعدالة والحرية والمساواة مكن للغزو الماركسي اليساري الملحد من أن يجتاح الأمة باسم تحقيق العدالة ونصرة المظلومين ورفع مستوى الفقراء والكادحين .. ثم ان المعركة الدائرة اليوم بين الإسلام وبين (الجاهلية) لم تعد في مستوى البحث العلمي المجرد أو في حدود المناقشة الفكرية الهادفة .. بل أضحى هذا الصراع دموياً ضارياً بكل ما في هاتين الكلمتين من معنى ؟ إن جاهلية اليوم تستخدم في حربها للاسلام ودعاته كل الأسلحة الفتاكة ، الأسلحة المبيدة ، الأسلحة الخبيثة .. إن القتل والسحل والسجن والتعذيب والتشريد ، وإن حملات الإرجاف والتشكيك والتخوين والاتهام كل هذه وغيرها من"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0217.png"}, {"n": 218, "paras": ["الوسائل المعتمدة لدى ( الجاهلية الحديثة ) لضرب الإسلام وتصفية العاملين له في كل مكان .. ثم ان العالم كل العالم بات يعيش حالة ضياع .. وأصبح يئن تحت وطأة الانحراف والشذوذ والفراغ .. العالم الذي أعمته مظاهر المدنية الحديثة ، وأحرقته نار الثورة الجنسية ، وهدته الصراعات البوهيمية ( الهيبية والوجودية الخ .. ) مما يتهدد الوجود الإنساني والأخلاق الإنسانية والأفكار الإنسانية - حق المجردة منها - بالفناء الكامل . وثمة مبرراً آخر يحتم قيام حركة إسلامية عالمية واحدة وهو أن التحديات التي تواجه الإسلام إنما هي في حقيقتها تحديات ( حركات عالمية ) كالحركة الصهيونية والحركة الماسونية والحركة الشيوعية والحركة التبشيرية الصليبية .. ومثل هذه الحركات العالمية ذات القدرات والإمكانيات البشرية والمادية والفنية الهائلة لا يمكن - بل لا يجوز - مواجهتها إلا على نفس مستواها وبنفس وسائلها ، وسوى ذلك لا يعني غير التراجع والاندثار ؟ هذه المبررات وغيرها تحتم بما لا يدع مجالاً للتباطؤ والشك والتلكؤ قيام حركة إسلامية عالمية واحدة تكون في مستوى المواجهة تفكيراً وتنظيماً وتخطيطاً وإعداداً ، وصدق الله تعالى حيث يقول : ( وأعدوا لهم ما استطعتم من قوة ، ومن رباط الخيل ترهبون به عدو الله وعدوكم ) ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0218.png"}, {"n": 219, "paras": ["تجارب في نطاق العمل للاسلام وقبل أن نناقش المواصفات العامة والملامح الأساسية التي ينبغي توفرها في الحركة الاسلامية العالمية الواحدة لا بد وأن نستعرض التجارب التي قامت في نطاق العمل للاسلام في العصر الحديث تلمساً للعبرة واستزادة للخبرة والله الهادي إلى سواء السبيل ..", "١ - طريق الوعظ والارشاد ( أو تجربة جماعة التبليغ ) وهو الأسلوب الذي يمارسه الوعاظ والمرشدون بشكل إفرادي في غالب الأحيان والذي تمارسه جماعة التبليغ بشكل جماعي .. وجماعة التبليغ تلزم أتباعها ببذل أوقات معينة للقيام بهذا الواجب ساعة في الأسبوع أو يوماً في الشهر أو شهراً في السنة ، يقومون فيها بالدعوة إلى الإسلام في سائر أنحاء الوطن الإسلامي .. وجماعة التبليغ مع حرارة دعاتها إلى الله وحماسهم وصدقهم وإخلاصهم وصفائهم ، إلا أنه لا يقدر لها أن تكسب الجولة مع الجاهلية العاتية إن بقي أسلوبها الحالي نفس الأسلوب في المستقبل أو أصبح سياسة مضطردة في سائر مراحل العمل وفي مختلف الظروف .. أ - إن هذا الأسلوب لا يفضي بنتيجته إلى إقامة تجمع"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0219.png"}, {"n": 220, "paras": ["حركي منظم قادر على مواجهة الجاهلية وتحدياتها المتزايدة ، وبالتالي إلى إيجاد المجتمع الإسلامي وإقامة الدولة الإسلامية واستئناف الحياة الإسلامية . ب - ثم إن مثل هذا الاسلوب سيبقى نطاق عمله محصوراً في المساجد وروادها بمعنى أن أثره لن يمتد إلى الآخرين الذين يمثلون اليوم السواد الأعظم من الناس ، وإلى قطاعاتهم المختلفة .. ج - كما أن هذا الأسلوب لن يتمكن من مواجهة تحديات الأفكار والفلسفات المادية يرد عليها ، لأنه ينتهج في غالب الأحيان أسلوب الموعظة العاطفية المؤثرة وأسلوب الترغيب والترهيب ، وهذا لا يمكن أن يؤثر في غير المتدينين أصلا .. د - ومن ظاهر هذا الأسلوب أنه ليس في تخطيطه - والله أعلم - أن يتابع البذور حتى تنمو وتصبح غرساً ليجنيها بعد ذلك ثمراً . وقد يكون مماثلا للأسلوب الذي انتهجه ( طاهر الجزائري ) و ( جمال الدين الافغاني ) والذي عبر عنه بقوله : « قل كلمتك وامش » وهذه الطريقة غير مضمونة النتيجة فضلاً عن كونها بطيئة الأثر قليلة الثمر .. يقول الأستاذ أبو الأعلى المودودي ( أمير الجماعة الإسلامية بباكستان ) مشيراً الى عقم أسلوب الوعظ والإرشاد : « يصبح من العبث الدعوة الى الإسلام على طريقة التبشير المسيحي . ولو طبعت ملايين النشرات تدعو الى التمسك بالإسلام وتصيح بالناس أن ( اتقوا الله ) صباح مساء . لما كانت ذات فائدة تذكر . إذ"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0220.png"}, {"n": 221, "paras": ["ما هي الفائدة العملية التي ستنجم عن تأكيد أن الإسلام صالح لكل زمان ومكان وأن فوائده ومزاياه ليس لها مثيل عن طريق القلم والخطابة؟ إن حاجة العصر تتطلب إبراز هذه المزايا بصورة عملية في عالم الواقع .. إن مشاكل العالم المادية لن تحل لمجرد القول بأن الإسلام يملك حلها .. إن قيمة الإسلام الذاتية لا بد وأن تبرز إلى الوجود في هيئة نظام عملي مهيمن يلمس الناس آثاره ويجنون ثماره .. إننا نعيش في عالم يقوم على الصراع والكفاح، والخطابة والوعظ لن تفلح في تغيير مجراه . ولكن الكفاح الثائر وحده هو الذي يستطيع ذلك » .. ( رسالة داء المسلمين ودواؤهم ص ١٥ ) .", "٢ - طريق القوة أو الثورة المسلحة ولقد قامت في العصر الحديث محاولات عدة في نطاق العمل للاسلام اتسمت بطابع الثورة وتوسلت القوة أساساً لمواجهة التحديات واستئناف الحياة الاسلامية .. من هذه التجارب ( الشهيد أحمد بن عرفان ) في الهند الذي استجاب له عدد كبير من الناس فجندهم وحمل أمامهم راية الجهاد، واستطاعوا أن يؤسسوا دولة إسلامية في مدينة (بشاور) شمالي الهند . غير أن الانجليز تآمروا عليها بدهاء ، وألبوا المسلمين من رجال القبائل ضدها ، مما أدى الى قيام معركة عنيفة بين الطرفين قتل فيها الإمام وكبار أصحابه وذلك عام ١٢٤٦ه. ومنها تجربة الشهيد ( الشيخ عز الدين القسام ) الذي استحيا"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0221.png"}, {"n": 222, "paras": ["من الله أن يقرىء تلاميذه أحكام الجهاد ثم هو لا ينفر معهم الى الانجليز الذين كانوا يحتلون فلسطين في ذلك الحين . فما كان منه إلا أن استنفر تلاميذه وأتباعه وتدرب على القتال ودربهم عليه ، وأعلن الجهاد على أعداء الله حتى سقط شهيداً عام ١٩٣٦ م .", "ومنها تجربة الشهيد ( نواب صفوي ) زعيم حركة الفدائيين المسلمين في إيران التي تؤمن بأن القوة والإعداد هي السبيل الوحيد لتطهير أرض الإسلام من الصهيونية والمستعمرين وإقامة حكم الإسلام .. ولقد قاومت الحركة أعداء الإسلام في إيران مقاومة الأبطال إلى أن سقط نواب صفوي وعصبة من إخوانه الأبرار برصاص الخونة المجرمين عام ١٩٥٦م .", "وليس من شأننا هنا أن نناقش بالتفصيل الأسلوب الذي اعتمدته هذه الحركات في مواجهة خصومها ، غير أننا نود الإشارة إلى أن منطق العصر ومنطق المواجهة ومنطق الإسلام وإن كان يحتم امتلاك القوة وأسبابها ، ولكن بشرط أن يتحقق التوسل بها واستعمالها كجزء من استراتيجية وليس الاستراتيجية كلها ..", "ولنا أن نثبت هنا ما أشار إليه الشهيد حسن البنا في معرض مناقشته لموضوع استخدام القوة في نطاق العمل للاسلام . قال رحمه الله : « ويتساءل كثير من الناس : هل في عزم الاخوان المسلمين أن يستخدموا القوة في تحقيق أغراضهم والوصول الى غايتهم : وهل يفكر الإخوان المسلمون في إعداد ثورة عامة على"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0222.png"}, {"n": 223, "paras": ["النظام السياسي أو النظام الاجتماعي ؟ ولا أريد أن أدع هؤلاء المتسائلين في حيرة ، بل إني أنتهز هذه الفرصة فأكشف اللثام عن الجواب السافر لهذا التساؤل فأقول في وضوح وجلاء ، وليسمع من يشاء: أما القوة فشعار الإسلام في كل نظمه وتشريعاته، فالقرآن الكريم ينادي في وضوح وجلاء : ﴿ وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم﴾. ولكن الإخوان المسلمين أعمق فكراً وأبعد نظراً من أن تستهويهم سطحية الأعمال والفكر فلا يغوصوا إلى أعماقها ولا يزنوا نتائجها وما يقصد منها وما يراد بها . فهم يعلمون أن أول درجة من درجات القوة قوة العقيدة والإيمان ، ويلي ذلك قوة الساعد والسلاح . ولا يصح أن توصف جماعة بالقوة حتى تتوفر لها هذه المعاني جميعاً . وأنها استخدمت قوة الساعد والسلاح وهي مفككة الأوصال مضطربة النظام أو ضعيفة العقيدة خامدة الإيمان فسيكون مصيرها الفناء والهلاك .. هذه نظرة ، ونظرة أخرى ، هل أوصى الإسلام - والقوة شعاره - باستخدام القوة في كل الظروف والأحوال ؟ أم حدد لذلك حدوداً واشترط شروطاً ووجه القوة توجيهاً محدوداً ؟ ونظرة ثالثة ، هل تكون القوة أول علاج أم أن آخر الدواء الكي ؟ وهل من الواجب أن يوازن الإنسان بين نتائج استخدام القوة النافعة ونتائجها الضارة وما يحيط بهذا الاستخدام من ظروف ؟ أم من واجبه أن يستخدم القوة وليكن بعد ذلك ما يكون ؟ هذه نظرات يلقيها الإخوان المسلمون على أسلوب استخدام القوة قبل أن"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0223.png"}, {"n": 224, "paras": ["يقدموا عليه » . ( رسالة المؤتمر الخامس عام ١٣٥٧ ه ) .", "٣ - طريق التثقيف وبث الافكار ( أو تجربة حزب التحرير الاسلامي )", "يؤمن حزب التحرير الإسلامي بأن عملية إنقاذ الأمة مما تتخبط فيه من أمراض وعلل تتم بإعادة ثقتها بصحة أفكار الإسلام وأحكامه .. وأن طريقها إلى ذلك ثورة فكرية سياسية تدمر الأفكار الباطلة وتحطم الحكم الفاسد. ولهذا وضع الحزب مجموعة من الكتب والنشرات في شتى الموضوعات ، كما انه يوالي إصدار نشرات فكرية وسياسية بين الحين والآخر ، إما بياناً لحكم الإسلام أو تحديداً لموقف الحزب من قضية ..", "وآراء الإسلاميين في حزب التحرير مختلفة .. فمنهم من يشك في نشأة الحزب وأهدافه وغاياته .. فيعتبر أن قيامه لم يكن ذاتياً وإنما بغرض بلبلة أفكار الناس وتشكيكهم بالحركات الإسلامية الأصيلة التي سبقته ، أو على الأقل بتشكيك أفراد هذه الحركات بحركاتهم وجماعاتهم. ويستدل أصحاب هذا القول على ذلك بالغموض الذي يكتنف حزب التحرير والإبهام الذي يحيط بقيادته ، كما يستدلون على ذلك بما ورد في مقدمة رسالة ( التكتل الحزبي) التي تعتبر كل التجمعات والتكتلات والحركات التي سبقت حزب التحرير فاشلة متناقضة وقائمة على أساس مغلوط .. كما يستدلون على ذلك - كذلك - بانحصار نشاط الحزب في رصد العناصر الإسلامية العاملة - دون غيرها -"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0224.png"}, {"n": 225, "paras": ["ومحاولة امتصاصها عن طريق تشكيكها بانحراف خط سير الجماعة التي تنتسب إليها ، وبضعف أفكارها وتباين هذه الأفكار وعدم وحدتها ، وأخيراً بعدم نجاحها في إقامة الدولة الإسلامية خلال السنوات الطويلة من حياتها ، ثم بإيهام هذه العناصر بقوة الحزب وقدرته ( السحرية ) على إقامة الدولة بسرعة حتى ليخيل إلى بعضهم أنها قامت فعلا ، أو أن قيامها لم يعد بحاجة إلا إلى إعلان ويقول أصحاب هذا الرأي ان النتائج النفسية المقصودة لهذا الأسلوب الذي يتبعه حزب التحرير هو تدمير نفسية هؤلاء الذين يجتذبهم الحزب لفترة من الزمن ثم لا يلبث أن يلفظهم إما عناصر شوهاء موتورة ، ضررها للاسلام أكبر من نفعها أو عناصر مسيخة معدومة الإنتاج مبلبلة التفكير صدمها الواقع المرير بعد الأمل العريض .. ومنهم من يعتبر حزب التحرير تجربة من التجارب التي مرت وتمر بالعمل الإسلامي ، وأن لهذه التجربة حسناتها كما أن لها سيئاتها . وأن هذه التجربة أكدت فشلها لعدم بلوغها أهدافها بالسرعة التي حددتها لنفسها ، والتي سبق أن اعتبرتها حجة على سابقاتها ، والتي هي اليوم تبررها لنفسها فتقول في إحدى نشراتها الداخلية ( سؤال وجواب ) : « ومن ذلك يتبين أن ما يبدو من عدم ظهور أي تأثير للحزب بين الناس من حيث الأفكار الإسلامية الأساسية ليس ناتجاً عن خطأ في فهم الطريقة ، ولا عن إساءة في تطبيقها ، ولا عن انحراف عنها ، وإنما طبيعة الطريقة نفسها لا تجعل بروز آثارها سريعاً .. وطبيعة المجتمعات"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0225.png"}, {"n": 226, "paras": ["ولا سيما المجتمعات المتأخرة فكرياً يكون انتقال الحرارة إليها بطيئاً جداً أي يكون تأثرها بالأفكار يحتاج إلى المدى الطويل والجرعات القوية .. » وأنا لا أود أن استعرض آراء الناس كل الناس في حزب التحرير وإنما قصدي الاستفادة من دراسة الحزب كتجربة من تجارب العمل للاسلام في العصر الحديث بصرف النظر عن موقفه الآخرين منه ، سيما وأنه لم يقم أي دليل قطعي يصم الحزب بما يشين تبعيته أو مقاصده .. وإطلاق ما يطلقه الناس أو إشاعة ما يشيعونه أسلوب غوغائي يجب أن يترفع عنه أصحاب الرسالات ، والنقد الموضوعي المنطقي الهادف هو الأسلوب الأسلم لإثبات ما للحزب وما عليه ، وهو الطريق الأقوم للبلوغ بالحركة الإسلامية المستوى اللائق بها كحركة عالمية رائدة . وفيما يلي سأستعرض بعضاً من المآخذ التي يؤخذ بها الحزب كتجربة من التجارب في نطاق التمهيد والتحضير لنشأة الحركة الإسلامية العالمية الواحدة :", "١ - أخطئنا ( حزب التحرير ) حين اعتمد الفكر - أولاً وآخراً - وسيلة لبناء الشخصية الإسلامية.. وحين يأخذ الحزب على حركة ( الاخوان المسلمين ) استغراقها في التربية والتكوين الروحي والأخلاقي تأخذ هي عليه بالتالي استغراقه في اعتماد الفكر إلى حد الإسفاف ، في الوقت الذي لا تهمل هي (الفكر) كذلك .. وأسلوب الرسول ﷺ واضح الدلالة في أنه كان يعتمد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0226.png"}, {"n": 227, "paras": ["التوعية الفكرية والتربية الروحية والأخلاقية والجهادية في بناء الشخصية الإسلامية .", "٢ - وأخطأ حزب التحرير - كذلك - حين قرر مبدأ القفز من مرحلة ( الثقافة ) إلى مرحلة ( التفاعل ) .. ذلك أن الحزب بانتقاله من مرحلة التثقيف الداخلي إلى مرحلة التفاعل أي ضرب الأفكار والكيانات الجاهلية يكون كمن يود قطع واد من غير جسر .. ذلك أن مرحلة ( التثقيف ) لا تكفي للوقوف بالحزب في مواجهة التحدي الجاهلي دفعة واحدة .. كما أنه لا تؤهل أفراد الحزب للصمود أمام هذا التحدي الشرس .. فكان لا بد من مرحلة يتسلل فيها الحزب إلى الناس ويتخذ له بينهم مواطىء أقدام ، وقواعد ارتكاز وحماية .. تماماً كما كانت هجرة الرسول ﷺ أشبه بعملية احتشاد ، ومرحلة استنفار ، وقاعدة حماية قبل أن يعلن النفير وتدق ساعة الصفر ..", "٣ - وأخطأ حزب التحرير مرة أخرى حين اعتمد القوى والفعاليات ( غير الذاتية ) أي غير الحزبية أو حسب تعبيره واصطلاحه ( طلب النصرة ) في عملية الوصول إلى الحكم .. فحزب التحرير يرى أن يستعين بالقوة للوصول إلى السلطة واستئناف الحياة الإسلامية لكنه لا يرى ضرورة كذلك لامتلاك هذه القوة أساساً .. يقول الحزب في نشرة ( جواب وسؤال ) ولقد طلب الحزب النصرة في سورية ليتمكن من القيام بحمل الدعوة وليأخذ الحكم.. وطلب النصرة في العراق ليتمكن من القيام بحمل الدعوة وليأخذ", "- ٢٢٥ - الدعوة (١٥)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0227.png"}, {"n": 228, "paras": ["الحكم .. وظل الحال كذلك حتى أوائل ١٩٦٤ دون أن يجد من يلبي النصرة ) ثم يقول : « فقد يكون طلب النصرة من رئيس دولة فيحتاج الأمر الى وفد واحد او الى شاب واحد .. وقد يكون طلب النصرة من رئيس كتلة أو قائد جماعة أو زعيم قبيلة أو من سفير أو ما شاكل ذلك، فيحتاج الأمر الى اختيار معرفين وعدة شباب ، وقد لا يحتاج إلا إلى شاب واحد .. ) . غريب منطق ( طلب النصرة ) هذا لدى حزب التحرير حيث انه مرفوض بداهة .. فأما انه مرفوض بداهة فلكونه طلباً لن يحظى يوماً بالقبول من أحد .. واعتماد الحركة على قواها الذاتية ، وتمكين عناصرها الصميمة من بعض القطاعات الاستراتيجية هو الأسلوب الأقوم والأسلم في تحقيق ما تهدف إليه ، وبخاصة في ظروف سيئة كالظروف التي تعيشها البلاد الإسلامية في ظل أنظمة ( المخابرات الداخلية والاستخبارات الخارجية ) ؟ إن منطق ( طلب النصرة ) الذي يعتمده حزب التحرير لتحقيق الانقلاب الإسلامي للوصول إلى السلطة منطق غير سديد ، ومن شأنه أن يجعل الانقلاب الإسلامي المنشود صيحة في واد ونفخة في رماد ؟", "٤ - وأخطأ حزب التحرير - أيضاً - حين التزم بفكرة تبني الأحكام والأفكار بشكلها التعميمي .. حيث أعطى لكل سؤال جواباً ، وتبنى لكل قضية حكماً .. إن هذا الأمر يبدو في ظاهره ولأول مرة جميلا ورائعاً وبخاصة للشباب المحدودي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0228.png"}, {"n": 229, "paras": ["الثقافة الإسلامية ، ولكنه في نتائجه وأبعاده من شأنه أن يمسخ الثقافة الإسلامية ويضيق الفكر الإسلامي ويحجر عليه ضمن دائرة الكتب التي أصدرها حزب التحرير دون سواها . إن فكرة التبني في الأمور الخلافية الكبرى والمصيرية الهامة ذات الانعكاس الحركي والسياسي جيد ومفيد، ولكن اطلاقها بحيث تشمل كل شأن من التشريع سيء ومخيف ؟ وأود هنا أن أنقل فقرة وردت في كتاب ( معالم في الطريق ) للشهيد سيد قطب تعبر عن هذا المعنى أفصح تعبير .. قال رحمه الله : « ولقد يخيل لبعض المخلصين المتعجلين ، ممن لا يتدبرون طبيعة هذا الدين ، وطبيعة منهجه الرباني القويم ، وعلمه بطبائع البشر وحاجات الحياة .. نقول لقد يخيل لبعض هؤلاء أن عرض أسس النظام الإسلامي - بل التشريعات الإسلامية كذلك على الناس مما ييسر لهم طريق الدعوة ويحبب الناس في هذا الدين .. فالذين يريدون من الإسلام اليوم أن يصوغ نظريات وأن يصوغ قوالب نظام ، وأن يصوغ تشريعات للحياة . بينما ليس على وجه الأرض مجتمع قد قرر فعلاً تحكيم شريعة الله وحدها ، ورفض كل شريعة سواها ، مع تملكه للسلطه التي تفرض هذا وتنفذه . الذين يريدون من الإسلام هذا لا يدركون طبيعة هذا الدين ، ولا كيف يعمل في الحياة ، كما يريد له الله » .. وأكتفي هنا بهذا القدر من المآخذ (١) التي برزت خلال", "(١) لقد برزت على الحزب في الآونة الأخيرة مآخذ سياسية ومآخذ فقهية متعددة لا مجال لذكرها هنا .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0229.png"}, {"n": 230, "paras": ["التجربة التي مارسها حزب التحرير ومن خلال محتواه الفكري والحركي لأنتقل إلى تجربة أخرى من تجارب العمل الإسلامي في العصر الحديث ..", "٤ - طريق الايمان العميق والتكوين الدقيق والعمل المتواصل ( أو تجربة حركة الاخوان المسلمين )", "حركة الإخوان المسلمين هي الحركة الممتدة عبر أكثر أقطار العالم الإسلامي وإن لم تصبح بعد حركة واحدة تخطيطاً وتنظيماً .. وقد أوضح مؤسس الحركة الإمام الشهيد حسن البنا من أول يوم طريق دعوته وأسلوبها ووسائلها فقال : « أيها الاخوان .. لقد أراد الله أن نرث هذه التركة مثقلة بالتبعات .. وأن يشرق نور دعوتكم في ثنايا هذا الظلام .. وأن يهيئكم الله لإعلاء كلمته . وإظهار شريعته ، وإقامة دولته من حديد .", "أما كيف نصل لهذه الأهداف ؟ إن الخطب والأقوال والمكاتبات والدروس والمحاضرات وتشخيص الداء ووصف الدواء كل ذلك وحده لا يجدي نفعاً ولا يحقق غاية ولا يصل بالداعين إلى هدف من الأهداف .. ولكن للدعوات وسائل لا بد من الأخذ بها والعمل لها .. والوسائل العامة للدعوات لا تتغير ولا تتبدل ولا تعدو هذه الأمور :", "١ - الإيمان العميق . ٢ - التكوين الدقيق .", "٣ - العمل المتواصل ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0230.png"}, {"n": 231, "paras": ["أيها الاخوان .. انتم لستم جمعية خيرية ، ولا حزباً سياسياً ولا هيئة موضعية لاعراض محدودة المقاصد ، ولكنكم روح جديد يسري في قلب هذه الأمة فيحييه بالقرآن.. ونور جديد يشرق فيبدد ظلام المادة بمعرفة الله .. وصوت داو يعلو مردداً دعوة الرسول ﷺ . ومن الحق الذي لا غلو فيه أن تشعروا انكم تحملون هذا العبء بعد أن تخلى الناس عنه .. فإذا قيل لكم إلام تدعون ؟ فقولوا ندعوا إلى الإسلام الذي جاء به محمد ﷺ والحكومة جزء منه ، والحرية فريضة من فرائضه وإذا قيل لكم هذه سياسة فقولوا هذا هو الإسلام ونحن لا نعرف هذه الاقسام . وإن قيل لكم انتم دعاة ثورة ، فقولوا نحن دعاه حق وسلام نعتقده ونعتز به ، فان ثرتم علينا ووقفتم في طريق دعوتنا فقد آن لنا أن ندفع عن انفسنا وكنتم الثائرين الظالمين وإن قيل لكم انكم تستعينون بالاشخاص والهيئات ، فقولوا : آمنا بالله وحده وكفرنا بما كنتم به مشركين.. فان لجوا في عدوانهم فقولوا : سلام عليكم لا نبتغي الجاهلين .. من خلال ما تقدم يتبين لنا إن حركة الاخوان المسلمين تتميز بعموميتها عن سائر الحركات الاخرى .. فهي دعوة فكرية من حيث انها تدعو إلى الالتزام بالأفكار الإسلامية ولفظ وترك كل ما عدا ذلك من أفكار وتشريعات ومبادىء وفلسفات ( من أجل تكوين العقلية الإسلامية ) .", "- وهي دعوة تربوية من حيث إنها تدعو إلى الالتزام باخلاق الإسلام وآدابه وإلى تزكية النفس والسمو بها في مدارج الربانية .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0231.png"}, {"n": 232, "paras": ["( من أجل تكوين النفسية الإسلامية ) .", "- وهي دعوة جهادية من حيث أنها تدعو إلى الإعداد الجهادي بكافة وسائله وأسبابه .. حق يكون للحق القوة التي تحميه ، وحق تتمكن الدعوة من مواجهة التحديات ومجاوزة الملمات .. وقد اشار الإمام البنا إلى هذا المعنى في ( رسالة إلى أي شيء ندعو الناس ) فقال : ما أحكم ذلك القائل : « القوة اضمن طريق لاحقاق الحق وما أجمل أن تسير القوة والحق جنباً إلى جنب . فهذا الجهاد في سبيل نشر الدعوة الإسلامية فضلا عن الاحتفاظ بمقدسات الإسلام فريضة أخرى فرضها الله على المسلمين كما فرض عليهم الصوم والصلاة والحج والزكاة وفعل الخير وترك الشر ، والزمهم إياها وندبهم اليها ، ولم يعذر في ذلك أحداً فيه قوة واستطاعة . وانها لآية زاجرة رادعة وموعظة بالغة: ﴿انفروا خفافا وثقالا وجاهدوا بأموالكم وأنفسكم في سبيل الله﴾ . ولقد كان الامام الشهيد يؤكد على هذه المعاني الجهاديه في أكثر أحاديثه وخطبه ، لأن الحق الاعزل لن يحقق شيئاً ولن يصل إلى شيء ، ولانه لا قيمة لحق لا تسنده القوة .. ولقد جاء تركيز هذا المعنى واضحاً في خطاب القاه في المؤتمر الخامس للحركة عام ١٣٥٧ هجرية حيث قال : « وفي الوقت الذي يكون فيه منكم - معشر الاخوان المسلمين - ثلاثمائة كتيبة قد جهزت كل نفسها روحياً بالايمان والعقيدة. وفكرياً بالعلم والثقافة، وجسمياً بالتدريب والرياضة .. في هذا الوقت طالبوني بأن أخوض بكم لجاج البحار ، واقتحم بكم عنان السماء ، وأغزو بكم كل عنيد"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0232.png"}, {"n": 233, "paras": ["جبار ، فاني فاعل إن شاء الله ، وصدق رسول الله القائل: «ولن يغلب اثنا عشر ألفاً من قلة» ..", "الحركة الاسلامية وظروف المنطقة ومنطق المواجهة : ولقد كان مقدراً لحركة الاخوان المسلمين ان تنجح وتحقق الهدف من وجودها بعد أن اصبحت ملء عين العالم وسمعه وبصره لولا أن تكاتفت عليها معاول الهدم من كل جانب ، وتآمرت عليها قوى الاستعمار من كل جهة ، وتلاحقت على رأسها الضربات والمحن .. بدأت باستشهاد مؤسسها المرحوم حسن البنا عام ١٩٤٨ ثم باستشهاد عدد ضخم من رجالاتها وقادتها ممن يعتبرون عمالقة ليس على المستوى الحركي الحزبي الضيق ولكن على المستوى العالمي الفسيح ..", "ولقد كان من نتائج ذلك انكماش نشاط الحركة وانحسارها عن معترك الصراع السياسي وإن بني وجودها الفكري والعقائدي قائماً .. كما كان من نتائج المحنة التي لحقت بالحركة الإسلامية ان تحكمت أنظمة الكفر في بلاد المسلمين ، وعمل الغزو الماركسي الملحد عمله في تخريب عقول الناس وادماغتهم .. وبذلك تغير في المنطقة - على الأقل العربية - كل شيء .. والحياة الديمقراطية التي تسمح بحرية العمل الحزبي ذهبت إلى غير رجعة .. والنظم القائمة في المنطقة معبأة بالحقد الأسود على الإسلام والمسلمين .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0233.png"}, {"n": 234, "paras": ["والمواجهات الحزبية لم تعد في مستوى النقاش والحوار العقائدي وإنما غدت دموية غوغائية شرسة .. إلى غير ذلك من الظروف والاوضاع مما يحتم على الحركة الإسلامية رسم استراتيجية جديده للعمل تمكنها من التحرك والإنتاج والتطور لتكون الحركة الإسلامية العالمية المنشودة ولتصبح في مستوى المواجهة الفعلية مع التحديات العالمية التي يواجهها الإسلام في العصر الحديث .. ملامح الحركة الاسلامية الواحدة : إن الحركات الإسلامية المعاصرة وإن لم تتمكن حتى اليوم من تحقيق الهدف الاساسي من وجودها وهو إقامة الدولة الإسلامية واستئناف الحياة الإسلامية ، إلا أنها خلفت وراءها ثورة كبيره من التجارب في نطاق العمل والتحضير لتحقيق هذا الهدف ، كما إنها تركت ميراثاً فكرياً ضخماً مما يمهد السبيل أمام نشأة حركة إسلامية واحدة تكون في مستوى المواجهة مع جاهلية القرن العشرين .. الانقلابية : إن الصفة الأساسية التي يجب أن تتصف بها الحركة الإسلامية المنشودة هي ( الانقلابية ) فالإسلام منهج انقلابي وليس منهجاً ترقيعياً .. وتحقيق المنهج الانقلابي يحتم بالتالي قيام تجمع حركي انقلابي ، ويعين على الحركة التي تتصدر للعمل الإسلامي أن تكون في مستوى تحقيق الانقلاب الإسلامي وعيناً ونهجاً وكفاية .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0234.png"}, {"n": 235, "paras": ["إن الحركة الإسلامية هذه أحوج ما تكون إلى استراتيجية انقلابية تبلغ بها مرحلة التنفيذ العملي لاهدافها ومبادئها.. واعني بالاستراتيجية الانقلابية (نظرية الحركة واسلوبها في تغيير الواقع الجاهلي القائم بالواقع الإسلامي المنشود ، بكل ما يقتضية هذا التغيير من فهم شامل ودقيق للواقع القائم ، وتقديراً واع للقوى والعوامل التي تحركه وتؤثر فيه .. وبالتالي تصور عميق للواقع الإسلامي المرتقب ومدى ما يحتاجه من كفايات وامكانيات على كل صعيد .. )", "وينبغي أن يكون في مضمون هذه الاستراتيجية حرص الحركة الإسلامية على ان تتولى هي بنفسها تحقيق منهجها في الحكم الإسلامي .. وليس من الإخلاص والتجرد في شيء - كما يتصور البعض - زهدها في تولي الحكم .. ذلك أن العالم والتاريخ لا يعرفان حركة على الإطلاق قدمت عصارة نضالها وكفاحها لغير المؤمنين بأهدافها الملتفين معها على دروب الكفاح والنضال .. فالدولة الإسلامية الأولى لم تأت إلا بنتيجة لجهاد الرسول ﷺ ومن معه من المسلمين .. والثورة الفرنسية لم تكن إلا أمنية من الاماني التي عمل لها روسو وفولتير ومونتسكيو .. والانقلاب الشيوعي جاء ثمرة المخطط الذي وضعه ماركس ولينين وانجاز والنازية الالمانية لم تظهر إلا في أرض غزاها هيكل وفيختبه وغوته ونيتشه ..", "هذا التصور من شأنه أن ( يقيم ) ادراك الحركة لمسؤولياتها ومهماتها تقييماً صحيحاً وسليماً فما هي بجمعية توجيهية تقف عند"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0235.png"}, {"n": 236, "paras": ["حدود الوعظ والارشاد.. ولا هي بمنتدى أدبي لاقامة المحاضرات والمناظرات .. ولا هي بمعهد شرعي لتخريج علماء في الشريعة والفكر الإسلامي.. ولا هي بدار نشر لطباعة الكتب والمؤلفات الإسلامية نشراً للثقافة واحياء للتراث .. ولكنها الدعوة التي قدر لها ان تحمل مواريث النبوة ورسالة الإسلام في العصر الحديث .. ان تحملها ابعادها وتكاليفها .. ان تحملها فكراً يكشف زيف الافكار والمبادىء والفلسفات المادية الطاغية .. وجهاداً يتصدى للباطل في كل اشكاله، ويطيح بالطواغيت - كل الطواغيت - حتى لا تكون فتنة ويكون الدين كله لله .. وحتى تقوم الدولة الإسلامية التي تنشر الخير وتحقق الطمأنينة والعدالة والمساواة ، وتخرج الناس من عبادة العباد إلى عبادة الله الواحد القهار ، ومن ضيق الدنيا إلى سعة الإسلام ، ومن جور الاديان إلى عدالة الإسلام .. وإن مثل هذه المهمات والتبعات لتتطلب من الحركة التي تقوم بها ان تكون في مستوى عال وعال جداً من الاعداد والكفاية على كافة المستويات ..", "اللامركزية : وصفة رئيسية أخرى يجب أن تتصف بها الحركة الإسلامية العالمية الواحدة وهي صفة اللامركزية أو مجاوزة الانتماء القطري المصطنع .. والهجرة في عصر النبوة لم تكن في معناها العميق إلا لفتة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0236.png"}, {"n": 237, "paras": ["إلى اللامركزية في العمل الإسلامي ، وإشارة إلى أن تحقيق الإسلام قد يكون سهلاً وممكناً في مكان وصعباً ومستحيلا في آخر .. وعندها يصبح من الضروري افراغ الجهد فيما هو ممكن وميسور حفاظاً على الطاقات والاوقات من التلف والضياع .. وهذا المنطق بالذات يفرط وجود تخطيط عالمي للعمل الإسلامي في العصر الحديث . من شأنه أن يوجه الطاقات - كل الطاقات - ويحشد القوى - كل القوى وتسخر الإمكانيات كلها ويعمل على دفعها وحشدها حيث يؤمل الاثمار والعطاء ..", "الفكرية : بمعنى أن تعتمد الحركة الإسلامية الفكر وليس العاطفة", "- أساساً لانطلاقها .. فهي دعوة الحجة والدليل ودعوة العقل والمنطق . وهي الميزة التي امتازت بها دعوة الإسلام وتمتاز عن سواها من الدعوات قديماً وحديثاً .. ومن شرائط هذه الفكرية أن يكون الفهم للإسلام والدعوة اليه والحاجة فيه مبنية على عميق التصور وكلية النظر ووضوح الرؤيا .. ومن شرائطها - كذلك - أن تكون المواجهة مع الجاهلية قائمة على دراسة مسبقة ومركزة لافكار هذه الجاهلية ومبادئها ووسائلها واستراتيجيتها ..", "العلمية : بمعنى أن تسعى الحركة للاستفادة من كل التجارب العلمية التي"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0237.png"}, {"n": 238, "paras": ["انتجتها الحضارة الإنسانية ومن كل ما تفتقت عنه عقول البشر في شتى الحقول والميادين .. ما دامت كلها وسائل يمكن الافادة منها والانتفاع بها واستخدامها وتسخيرها فيما يعود على البشرية بالخير والنفع .. ومن ملامح هذه العلمية استفادة الحركة من أحدث النظريات في حقل التنظيم .. ومن أحسن الوسائل واوقعها في حقل الاعلام .. ومن أفضل الاساليب الحركية في حقل العمل الشعبي والطلابي والسياسي وغيره .. ومن ملامح هذه العلمية اعتماد الحركة على معرفة واسعة ودقيقة للمجتمع الذي تعيش فيه ، لأوضاعه النفسية والفكرية والسياسية والحزبية، ولارتباطاته الدولية وعلائقه الخارجية ..", "الربانية : واخيراً أن تعتمد الحركة الإسلامية التربية الربانية سبيلاً لتكوين أفرادها وطلائع صفها .. فالشخصية الإسلامية لا تتحقق ولادتها بالتوعية الفكرية المجردة ، بل لابد لذلك من تربية وتعهد حتى يصبح الإسلام وحده المقياس الأساسي لاشباع الميول والنوازع ولدوافع الخير والشر ، ولحدود الحلال .. والحرام .. إن الشخصية الإسلامية هي العنصر الأساسي في عملية التحضير لتحقيق الانقلاب الإسلامي وإقامة الدولة الإسلامية .. ونجاح الحركة في تكوين الشخصية الإسلامية سيملكها اقوى الامكانيات وأشدها فعالية في مغالبة الصعاب وفي بلوغ الأماني والآمال .."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0238.png"}, {"n": 239, "paras": ["ولهذا وجب إعداد ( الطليعة الإسلامية ) إعداداً غير عادي لان مهمتها كذلك غير عادية .. إعدادها نفسياً ومعنوياً .. إعدادها عقيدياً واخلاقياً .. إعدادها فكرياً وحركياً للقيام بالدور الكبير .. إن الحركة الإسلامية في كل مكان مدعوة لمواجهة مصيرها المشترك . لمواجهة مسؤولياتها الضخمة ، باعادة النظر في تجاربها وبرسم قواعد سيرها في ضوء حاضرها ومستقبلها ، بمستوى السرعة والدقة والكفاية التي يتطلبها العصر والتي تتطلبها مواجهة جاهلية هي غاية في المكر والشراسة .. وعند ذلك فقط يتحقق فيها التفسير العلمي لقوله تعالى : ﴿ وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم ﴾ ."], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0239.png"}, {"n": 240, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0240.png"}, {"n": 241, "paras": ["فهرس", "الموضوع الصفحة مقدمة الطبعة الأولى ٥ مقدمة الطبعة الثانية ٧ الحركة الإسلامية في مدار الأربعين عاماً ١٠ المحنة في حياة الدعوة والداعية ١٧ المنعطفات الكبرى في حياة الدعاة ٤٧ الداعية بين الفهم والتطبيق ٦٥ القيادة بين التوجيه والتنظيم ٧٣ العلاقة التنظيمية بين الدعوة والداعية ٨٣ الطبيعة الحركية ٩٥ شخصية الداعية ١٠٥ الشخصية الإسلامية ١٠٨ الداعية واسلوب الدعوة ١١٧ دعاة الإسلام وتفاوت القابليات ١٢٥"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0241.png"}, {"n": 242, "paras": ["بين العقائدية والحزبية الحركة الإسلامية بين التكامل والتآكل مظاهر وأسباب تشوه الشخصية الإسلامية الحديثة من أمراضنا التنظيمية من أمراضنا النفسية نحو حركة إسلامية عالمية واحدة"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0242.png"}, {"n": 243, "paras": ["Converted by Tiff Combine - (no stamps are applied by registered version)"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0243.png"}, {"n": 244, "paras": ["تطلب جميع منشوراتنا من : الشركة المتحدة للتوزيع بيروت - شارع سورية - بناية صمدي وصالحة ٦٠٢٢٤٣ - ٨١٥١١٢ ٧٤٦٠ دمشق - حماة - شارع مأتم البارودي - بناء صولي وصالجي ٢٢١٢٧٧٣ - ٢٢٢٦٤٤٣ ٢٦٢٥ برقياً بيوشتران عمان - دار البشير - العبدلي - مركز جوهرة القدس التجاري ٦٥٩٨٩١ - ٦٥٩٨٩٤ ١٨٢٠٧٧"], "img": "../../../_ocr-work/libocr/yakan-mishkilat/pages/0244.png"}]};
